/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"통칙과 권리ㆍ신의성실의 원칙":{"묶음":[{"머리":"민법의 법원(法源)","줄":[{"t":"법원 적용 순서: 민사에 관하여 법률에 규정이 없으면 관습법에 의하고, 관습법이 없으면 조리에 의한다.","src":"민법 제1조 | 기출 2022-1 | 기출 2025-1"},{"t":"민법의 법원이 되는 것: 민사에 관한 헌법에 의해 체결ㆍ공포된 조약.","src":"기출 2021-1 | 기출 2025-1"},{"t":"민법의 법원이 되는 것: 민사에 관한 일반적으로 승인된 국제법규.","src":"기출 2022-1 | 기출 2024-1"},{"t":"민법의 법원이 되는 것: 민사에 관한 집행명령, 대법원규칙(부동산등기규칙 포함), 대통령의 긴급재정명령.","src":"기출 2021-1 | 기출 2022-1 | 기출 2024-1 | 기출 2025-1"},{"t":"법률에 규정이 없을 때 적용되는 것은 관습법이다. 사실인 관습이 아니다. 관습법도 없으면 조리를 적용한다.","src":"민법 제1조 | 기출 2021-1"}]},{"머리":"관습법","줄":[{"t":"관습법: 사회생활규범이 사회의 법적 확신으로 법적 규범으로 승인된 것이다. 법원(法源)으로서 효력을 가진다.","src":"기출 2023-1 | 보충"},{"t":"관습법의 확정: 당사자의 주장ㆍ증명이 없어도 법원(法院)이 직권으로 확정하여야 한다.","src":"기출 2021-1 | 기출 2022-1 | 기출 2024-1 | 기출 2025-1 | 기출 2026-1"},{"t":"관습법의 효력 상실: 사회질서의 변화로 적용 시점의 전체 법질서에 반하게 되면 법적 규범으로서의 효력이 부정된다.","src":"기출 2021-1 | 기출 2023-1 | 기출 2026-1"},{"t":"효력이 상실된 관습법의 예: 종중 구성원의 자격을 성년남자만으로 제한하는 종래의 관습법.","src":"기출 2025-1"},{"t":"법원(法院)은 관습법이 헌법에 위반되는지 여부를 판단할 수 있다.","src":"기출 2024-1"},{"t":"물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다. 관습법으로 물권이 창설될 수 있다(분묘기지권, 관습법상 법정지상권 등).","src":"민법 제185조 | 기출 2023-1 | 보충"},{"t":"미등기 무허가건물의 취득자에게는 소유권에 준하는 관습상의 물권이 인정되지 않는다.","src":"기출 2026-1"}]},{"머리":"사실인 관습","줄":[{"t":"사실인 관습: 법령 중 선량한 풍속 기타 사회질서에 관계없는 규정(임의규정)과 다른 관습이 있고 당사자의 의사가 명확하지 아니한 때에 그 관습에 의한다.","src":"민법 제106조"},{"t":"사실인 관습은 법령으로서의 효력이 없는 단순한 관행이다. 법률행위 당사자의 의사를 보충하는 데 그친다.","src":"기출 2021-16 | 기출 2022-1 | 기출 2026-1"},{"t":"사실인 관습은 사적 자치가 인정되는 분야에서 임의규정에 관한 법률행위의 해석기준이 되며 재판의 자료가 된다.","src":"기출 2024-1 | 기출 2026-1"},{"t":"사실인 관습은 존재 여부를 당사자가 주장ㆍ증명하여야 한다(관습법과 다름).","src":"보충"}]},{"머리":"신의성실의 원칙","줄":[{"t":"신의칙: 권리의 행사와 의무의 이행은 신의에 좇아 성실히 하여야 한다. 권리는 남용하지 못한다.","src":"민법 제2조 | 기출 2024-3"},{"t":"신의칙 위반 여부는 당사자의 주장이 없어도 법원이 직권으로 판단할 수 있다.","src":"기출 2024-3 | 기출 2025-3"},{"t":"신의칙은 사법관계에만 적용되지 않고 공법관계에도 적용된다.","src":"기출 2024-3"},{"t":"권리남용이라고 해서 그 권리가 언제나 소멸하는 것은 아니다.","src":"기출 2024-3"},{"t":"사정변경의 원칙에서 ‘사정’은 계약의 기초가 된 객관적 사정이다. 일방 당사자의 주관적 사정이 아니다.","src":"기출 2024-3"},{"t":"법령에 위반되어 무효임을 알면서 법률행위를 한 자가 강행법규 위반을 이유로 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반하지 않는다.","src":"기출 2025-3 | 기출 2026-20"},{"t":"신의칙상 의무 인정 사례: 병원의 입원환자 휴대품 도난 방지 보호의무, 아파트 분양자의 단지 인근 공동묘지 사실 고지의무, 사용자의 근로자 안전 보호의무.","src":"기출 2021-2 | 기출 2025-3"},{"t":"신의칙 적용 사례: 부당하게 과다한 세무사 보수 약정은 상당하다고 인정되는 범위의 보수액만 청구할 수 있다.","src":"기출 2021-2"},{"t":"계속적 보증계약의 보증인은 주채무가 확정된 이후에는 사정변경을 이유로 보증계약을 해지할 수 없다.","src":"기출 2021-2"},{"t":"인지청구권은 포기할 수 없는 권리이므로 실효의 원칙이 적용되지 않는다.","src":"기출 2021-2 | 기출 2025-3"},{"t":"무효인 편입허가를 받은 자에 대해 오랜 기간 경과 후 편입학을 취소하는 것은 신의칙 위반이 아니다.","src":"기출 2021-2"}]},{"머리":"권리의 종류 1 — 작용(내용)에 따른 분류","줄":[{"t":"지배권: 소유권, 저당권 등 물권이 대표적이다. 타인의 행위 없이 객체를 직접 지배한다.","src":"기출 2022-2 | 기출 2025-2"},{"t":"절대권: 점유권, 물권은 누구에게나 주장할 수 있는 절대권이다.","src":"기출 2025-2"},{"t":"청구권: 특정인에게 일정한 행위(급부)를 요구하는 권리. 소유권이전등기청구권, 전세금반환채권, 유익비상환청구권, 상속회복청구권, 지상권갱신청구권이 이에 속한다.","src":"기출 2021-4 | 기출 2024-2 | 기출 2025-2 | 기출 2026-28 | 보충"},{"t":"형성권: 권리자의 일방적 의사표시로 법률관계를 발생ㆍ변경ㆍ소멸시킨다. 상계권, 계약해제권ㆍ해지권, 법률행위 취소권, 매매의 일방예약완결권, 지상권자ㆍ토지임차인의 지상물매수청구권, 법률행위에 대한 동의권이 해당한다.","src":"기출 2021-4 | 기출 2022-2 | 기출 2024-2 | 기출 2025-2 | 기출 2026-2 | 기출 2026-8"},{"t":"형성권 아님(청구권): 점유자의 유익비상환청구권, 전세권자의 전세금반환채권, 상속회복청구권, 지상권자의 지상권갱신청구권. 상계권을 청구권이라 하면 틀리다.","src":"기출 2021-4 | 기출 2022-2 | 기출 2024-2 | 기출 2025-2 | 기출 2026-28"},{"t":"법원의 판결이 있어야 효과가 발생하는 형성권: 채권자취소권(법원에 취소 및 원상회복을 청구, 취소원인을 안 날부터 1년ㆍ법률행위 있은 날부터 5년 내에 제기).","src":"민법 제406조 | 기출 2023-2 | 기출 2026-2"},{"t":"매매의 일방예약완결권은 형성권이다(청구권 아님). 상계권ㆍ계약해제권ㆍ동의권ㆍ일방예약완결권은 재판 없이 의사표시만으로 효과가 발생한다.","src":"기출 2023-2 | 기출 2024-2 | 기출 2025-2 | 기출 2026-2"},{"t":"사원권: 사원총회에서의 결의권. 재산권: 소유권이전등기청구권.","src":"기출 2022-2"}]},{"머리":"항변권ㆍ일신전속권ㆍ종된 권리","줄":[{"t":"연기적(일시적) 항변권(동시이행의 항변권, 보증인의 최고ㆍ검색의 항변권)은 청구권의 행사를 일시 저지할 뿐이며 청구권 자체를 소멸시키지 않는다.","src":"기출 2023-2 | 기출 2026-8"},{"t":"영구적 항변권은 청구권의 행사를 영구적으로 저지한다. 보증인의 최고ㆍ검색의 항변권은 연기적 항변권이다.","src":"기출 2026-8"},{"t":"부양청구권은 일신전속권이다.","src":"기출 2026-8"},{"t":"인격권 침해에 대하여는 예방적 구제수단으로서 금지청구권이 인정될 수 있다.","src":"기출 2026-8"},{"t":"주된 권리의 소멸시효가 완성한 때에는 종속된 권리에 그 효력이 미친다.","src":"민법 제183조 | 기출 2023-2 | 기출 2026-8"}]},{"머리":"권리의 경합(청구권경합)","줄":[{"t":"계약 취소로 인한 부당이득반환청구권과 불법행위로 인한 손해배상청구권은 경합하여 병존한다.","src":"기출 2022-3 | 기출 2023-18"},{"t":"강박에 의한 의사표시를 취소한 경우 부당이득반환청구권과 불법행위 손해배상청구권은 경합하여 병존한다.","src":"기출 2023-18"},{"t":"매도인의 하자담보책임과 채무불이행책임은 별개의 권원으로 경합하여 병존할 수 있다.","src":"기출 2022-3"},{"t":"공무원의 직무상 위법행위에 대해 국가의 민법상 불법행위책임과 국가배상법상 배상책임은 경합하여 병존하는 것이 아니다. 국가배상법이 우선 적용된다.","src":"기출 2022-3 | 보충(추정)"}]}],"함정":[{"x":"민사에 관하여 법률과 관습법이 없는 경우에는 사실인 관습에 의한다.","o":"법률과 관습법이 없으면 조리에 의한다.","src":"민법 제1조 | 기출 2021-1"},{"x":"민사에 관한 대통령의 긴급재정명령은 민법의 법원이 될 수 없다.","o":"민사에 관한 대통령의 긴급재정명령도 민법의 법원이 될 수 있다.","src":"기출 2024-1"},{"x":"관습법은 당사자가 그 존재를 주장ㆍ증명해야만 법원(法院)이 이를 적용할 수 있다.","o":"관습법은 당사자의 주장ㆍ증명이 없어도 법원이 직권으로 확정한다.","src":"기출 2022-1"},{"x":"관습법은 당사자의 주장ㆍ증명이 없으면 법원이 직권으로 이를 확정할 수 없다.","o":"법원은 직권으로 관습법을 확정할 수 있다.","src":"기출 2025-1"},{"x":"관습법이 그 적용 시점에서의 전체 법질서에 부합하지 않더라도 그 법적 규범으로서의 효력이 부정되지는 않는다.","o":"전체 법질서에 반하게 되면 법적 규범으로서의 효력이 부정된다.","src":"기출 2026-1"},{"x":"물권은 관습법에 의하여 창설될 수 없다.","o":"물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다. 관습법으로 창설될 수 있다.","src":"민법 제185조 | 기출 2023-1"},{"x":"사실인 관습은 법령에 저촉되지 않는 한 법칙으로서의 효력을 갖는다.","o":"사실인 관습은 법칙으로서의 효력이 없고 법률행위 당사자의 의사를 보충할 뿐이다.","src":"기출 2021-16 | 기출 2023-1"},{"x":"사실인 관습은 당사자의 주장ㆍ증명이 없더라도 법원이 직권으로 확정하여야 한다.","o":"직권 확정은 관습법에 해당한다. 사실인 관습은 당사자가 주장ㆍ증명한다.","src":"기출 2023-1 | 보충"},{"x":"사실인 관습은 사회생활규범이 사회의 법적 확신에 의하여 법적 규범으로 승인된 것을 말한다.","o":"그 정의는 관습법의 정의이다. 사실인 관습은 법적 확신 없는 단순한 관행이다.","src":"기출 2023-1"},{"x":"무효인 편입허가를 받은 자에 대하여 오랜 기간이 경과한 후 편입학을 취소하는 것은 신의칙 위반이다.","o":"신의칙 위반이 아니다.","src":"기출 2021-2"},{"x":"매매예약 완결권의 법적 성질은 청구권이다.","o":"형성권이다.","src":"기출 2023-2"},{"x":"채권자취소권은 권리자의 의사표시만으로 그 효과가 발생한다.","o":"법원에 청구하여 판결로써 행사한다.","src":"민법 제406조 | 기출 2023-2"},{"x":"연기적 항변권의 행사는 상대방의 청구권을 소멸시킨다.","o":"청구권을 소멸시키지 않고 행사를 일시 저지할 뿐이다.","src":"기출 2023-2 | 보충"},{"x":"임대인의 임대차계약 해지권은 행사상 일신전속권이다.","o":"출제 오답(바른 설명 미확인).","src":"기출 2023-2"},{"x":"권리를 남용한 경우 그 권리는 언제나 소멸한다.","o":"권리남용이라고 그 권리가 언제나 소멸하는 것은 아니다.","src":"기출 2024-3"},{"x":"신의성실의 원칙에 반하는지의 여부는 법원이 직권으로 판단할 수 없다.","o":"당사자의 주장이 없어도 직권으로 판단할 수 있다.","src":"기출 2024-3 | 기출 2025-3"},{"x":"신의성실의 원칙은 사법관계에만 적용되고, 공법관계에는 적용될 여지가 없다.","o":"공법관계에도 적용된다.","src":"기출 2024-3"},{"x":"사정변경의 원칙에서 사정은 계약의 기초가 된 일방당사자의 주관적 사정을 의미한다.","o":"계약의 기초가 된 객관적 사정을 의미한다.","src":"기출 2024-3"},{"x":"법령에 위반되어 무효임을 알면서 법률행위를 한 자가 강행법규 위반을 이유로 그 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반한다.","o":"특별한 사정이 없는 한 신의칙에 반하지 않는다.","src":"기출 2025-3 | 기출 2026-20"},{"x":"보증인의 최고ㆍ검색의 항변권은 청구권의 행사를 영구적으로 저지할 수 있는 항변권에 해당한다.","o":"연기적 항변권이다.","src":"기출 2026-8"},{"x":"상계권 - 청구권 (권리 분류 연결)","o":"상계권은 형성권이다.","src":"기출 2022-2"},{"x":"상속회복청구권은 형성권이다.","o":"청구권이다.","src":"기출 2025-2"},{"x":"지상권자의 지상권갱신청구권은 형성권이다.","o":"청구권이다(지상물매수청구권은 형성권).","src":"기출 2026-28 | 민법 제283조(원문 미확인)"},{"x":"점유자의 유익비상환청구권은 형성권이다(2021-4 ㄴ, 2024-2 선지 3).","o":"청구권이다.","src":"기출 2021-4 | 기출 2024-2"},{"x":"공무원 직무상 위법행위에서 국가의 민법상 불법행위책임과 국가배상법상 배상책임은 경합하여 병존한다.","o":"경합 병존하지 않는다. 국가배상법이 우선 적용된다.","src":"기출 2022-3 | 보충(추정)"}]},"자연인(권리능력ㆍ행위능력ㆍ부재와 실종)":{"묶음":[{"머리":"권리능력","줄":[{"t":"권리능력의 존속기간: 사람은 생존한 동안 권리와 의무의 주체가 된다.","src":"민법 제3조"},{"t":"권리능력의 시기: 출생 시(전부노출)부터다. 출생신고나 가족관계등록부 기재가 있어야 인정되는 것이 아니다.","src":"기출 2023-3 | 기출 2026-3 | 보충"},{"t":"자연인의 권리능력을 제한하는 약정(당사자 합의)은 무효이다.","src":"기출 2021-8 | 기출 2025-4"},{"t":"실종선고가 있더라도 당사자가 생존하는 한 권리능력은 상실되지 않는다.","src":"기출 2023-3"},{"t":"반려동물은 물건이다. 위자료청구권의 귀속주체가 될 수 없다.","src":"기출 2021-8 | 기출 2024-12 | 기출 2026-3"},{"t":"법인도 유증을 받을 수 있다.","src":"기출 2025-4"},{"t":"청산법인의 권리능력은 청산의 목적범위 내로 제한된다.","src":"민법 제81조 | 기출 2025-4"}]},{"머리":"태아의 권리능력(개별적 보호주의)","줄":[{"t":"손해배상청구권: 태아는 손해배상의 청구권에 관하여는 이미 출생한 것으로 본다. 불법행위로 인한 손해배상청구권을 뜻한다(채무불이행 손해배상은 해당 없음).","src":"민법 제762조 | 기출 2025-4"},{"t":"태아는 부(父)의 생명침해로 인한 위자료청구권에 관하여 이미 출생한 것으로 본다.","src":"기출 2026-3"},{"t":"태아는 대습상속에 관하여 이미 출생한 것으로 본다(상속ㆍ유증ㆍ대습상속은 인정).","src":"민법 제1001조 | 기출 2025-4 | 보충(원문 미확인: 제1000조 제3항)"},{"t":"유증: 제1000조 제3항(태아의 상속순위)과 제1004조(결격사유)는 수증자에 준용한다. 태아도 수증자가 된다.","src":"민법 제1064조"},{"t":"증여: 태아는 증여(수증행위)에 관하여 이미 출생한 것으로 보지 않는다. 법정대리인이 태아를 대리하여 수증행위를 할 수도 없다.","src":"기출 2021-8 | 기출 2023-3 | 보충"},{"t":"태아가 불법행위로 사산된 경우 태아는 가해자에 대하여 자신의 생명침해로 인한 손해배상을 청구할 수 없다(포태 시 가해된 불법행위의 손해배상청구권도 인정되지 않음).","src":"기출 2021-8 | 기출 2024-4"}]},{"머리":"동시사망","줄":[{"t":"2인 이상이 동일한 위난으로 사망한 경우에는 동시에 사망한 것으로 추정한다(간주 아님).","src":"민법 제30조 | 기출 2021-8 | 기출 2023-3 | 기출 2026-3"},{"t":"인정사망: 사망의 원인이 될 위난 후 시신 미발견이어도 사망으로 인정하는 제도. 강한 추정력이 있으나 반증으로 번복될 수 있다.","src":"기출 2023-3 | 기출 2026-3 | 보충(추정)"},{"t":"법원은 인정사망이나 실종선고에 의하지 않고도 경험칙에 의거하여 사망사실을 인정할 수 있다.","src":"기출 2024-4"}]},{"머리":"의사능력","줄":[{"t":"의사능력의 유무는 구체적인 법률행위와 관련하여 개별적으로 판단한다.","src":"기출 2024-4"},{"t":"의사무능력을 이유로 법률행위의 무효를 주장하는 자가 의사무능력에 대하여 증명책임을 진다.","src":"기출 2024-4"},{"t":"의사무능력으로 무효가 된 경우 의사무능력자는 받은 이익이 현존하는 한도에서 상환할 책임이 있다.","src":"기출 2024-4"},{"t":"의사능력이 없는 자라도 성년후견개시의 심판을 받아야 피성년후견인이 된다.","src":"기출 2023-5"}]},{"머리":"미성년자","줄":[{"t":"성년: 사람은 19세로 성년에 이른다.","src":"민법 제4조"},{"t":"미성년자가 법률행위를 할 때는 법정대리인의 동의를 얻어야 한다. 단 권리만을 얻거나 의무만을 면하는 행위는 동의 불요. 위반한 행위는 취소할 수 있다.","src":"민법 제5조"},{"t":"법정대리인이 범위를 정하여 처분을 허락한 재산은 미성년자가 임의로 처분할 수 있다.","src":"민법 제6조 | 기출 2022-4"},{"t":"법정대리인은 미성년자가 아직 법률행위를 하기 전에는 동의와 허락을 취소할 수 있다.","src":"민법 제7조"},{"t":"영업의 허락: 허락받은 특정한 영업에 관하여 성년자와 동일한 행위능력이 있다. 법정대리인은 허락을 취소 또는 제한할 수 있으나 선의의 제3자에게 대항하지 못한다.","src":"민법 제8조 | 기출 2021-6 | 기출 2022-4"},{"t":"법정대리인의 동의는 묵시적으로도 할 수 있다.","src":"기출 2022-4 | 기출 2026-4"},{"t":"미성년자는 법정대리인의 동의 없이 부담부증여계약을 체결할 수 없다(의무를 지므로).","src":"기출 2026-4"},{"t":"미성년자는 타인의 임의대리인이 될 수 있다. 법정대리인의 승낙은 필요 없다(대리인은 행위능력자임을 요하지 않는다).","src":"민법 제117조 | 기출 2022-4 | 기출 2025-5"},{"t":"미성년자가 혼인을 한 때에는 성년자로 본다(성년의제).","src":"기출 2025-5 | 보충(원문 미확인: 제826조의2)"},{"t":"단독으로 취소할 수 있는 행위의 예: 시가 300만원 상당 물품을 100만원에 매수한 행위(의무를 부담).","src":"기출 2021-6"},{"t":"미성년자가 단독으로 취소할 수 없는 행위의 예: 만 17세 5개월 된 자의 유언(17세에 달하면 유언 가능, 제한능력 규정 배제), 대리인으로서 한 대리행위, 허락받은 특정 영업행위, 속임수로 능력자로 믿게 한 법률행위.","src":"민법 제1061조 | 민법 제1062조 | 민법 제117조 | 민법 제8조 | 민법 제17조 | 기출 2021-6"}]},{"머리":"피성년후견인ㆍ피한정후견인ㆍ피특정후견인","줄":[{"t":"성년후견개시: 정신적 제약으로 사무를 처리할 능력이 지속적으로 결여된 사람에 대하여, 본인ㆍ배우자ㆍ4촌 이내 친족ㆍ검사 등의 청구로 가정법원이 심판한다. 심판 시 본인의 의사를 고려하여야 한다.","src":"민법 제9조 | 기출 2024-6"},{"t":"피성년후견인의 법률행위는 취소할 수 있다. 가정법원은 취소할 수 없는 법률행위의 범위를 정할 수 있고 청구에 의해 변경할 수 있다. 일용품 구입 등 일상생활에 필요하고 대가가 과도하지 않은 법률행위는 성년후견인이 취소할 수 없다.","src":"민법 제10조 | 기출 2022-6 | 기출 2025-5"},{"t":"한정후견개시: 정신적 제약으로 사무를 처리할 능력이 부족한 사람에 대한 심판이다. 개시 시 본인의 의사를 고려한다(제9조 제2항 준용).","src":"민법 제12조 | 기출 2022-6"},{"t":"피한정후견인이 한정후견인의 동의를 받아야 하는 행위의 범위는 가정법원이 정한다. 범위 변경은 본인ㆍ배우자ㆍ4촌 이내 친족ㆍ한정후견인 등의 청구에 의한다.","src":"민법 제13조 제1항ㆍ제2항 | 기출 2024-6 | 기출 2025-5 | 기출 2026-4"},{"t":"한정후견인이 이익침해 염려에도 동의를 하지 않으면 가정법원은 피한정후견인의 청구에 의해 동의를 갈음하는 허가를 할 수 있다.","src":"민법 제13조 제3항"},{"t":"한정후견인의 동의가 필요한 법률행위를 동의 없이 하면 취소할 수 있다. 일용품 구입 등 일상생활에 필요하고 대가가 과도하지 않은 행위는 제외된다.","src":"민법 제13조 제4항"},{"t":"특정후견: 일시적 후원 또는 특정한 사무에 관한 후원이 필요한 사람에 대한 심판이다. 본인의 의사에 반하여 할 수 없다. 심판 시 특정후견의 기간 또는 사무의 범위를 정하여야 한다.","src":"민법 제14조의2 | 기출 2024-6 | 기출 2026-4"},{"t":"특정후견의 심판이 있어도 피특정후견인의 행위능력은 제한되지 않는다.","src":"기출 2023-5 | 보충"},{"t":"심판 사이의 관계: 피한정후견인ㆍ피특정후견인에 대한 성년후견개시 시 종전 한정후견 또는 특정후견의 종료 심판을 한다. 피성년후견인ㆍ피특정후견인에 대한 한정후견개시 시에도 종전 성년후견 또는 특정후견의 종료 심판을 한다.","src":"민법 제14조의3 | 기출 2026-4"},{"t":"성년후견개시 청구가 있더라도 가정법원은 필요하다면 한정후견을 개시할 수 있다.","src":"기출 2024-6 | 기출 2025-5"},{"t":"피성년후견인이 법정대리인의 동의서를 위조하여 계약을 체결한 경우에도 성년후견인은 취소할 수 있다.","src":"기출 2023-5"},{"t":"한정후견이 종료된 후에도 종료 전에 동의 없이 한 법률행위는 취소할 수 있다.","src":"기출 2023-5"},{"t":"피한정후견인은 임의대리인이 될 수 있다.","src":"기출 2025-18"}]},{"머리":"제한능력자의 상대방 보호","줄":[{"t":"확답을 촉구할 권리: 상대방은 제한능력자가 능력자가 된 후 그에게 1개월 이상의 기간을 정해 추인 여부의 확답을 촉구할 수 있다. 능력자가 그 기간 내에 확답을 발송하지 않으면 추인한 것으로 본다.","src":"민법 제15조 제1항 | 기출 2023-4"},{"t":"아직 능력자가 되지 못한 경우에는 법정대리인에게 촉구할 수 있다. 법정대리인이 기간 내에 확답을 발송하지 않으면 추인한 것으로 본다. 상대방이 계약 당시 제한능력자임을 알았더라도 확답 촉구는 할 수 있다.","src":"민법 제15조 제2항 | 기출 2023-4"},{"t":"특별한 절차가 필요한 행위는 기간 내에 그 절차를 밟은 확답을 발송하지 않으면 취소한 것으로 본다.","src":"민법 제15조 제3항"},{"t":"철회권: 제한능력자가 맺은 계약은 추인이 있을 때까지 상대방이 철회할 수 있다. 계약 당시 제한능력자임을 알았던 상대방은 철회할 수 없다(선의만 철회).","src":"민법 제16조 제1항 | 기출 2022-6 | 기출 2023-4"},{"t":"거절권: 제한능력자의 단독행위는 추인이 있을 때까지 상대방이 거절할 수 있다.","src":"민법 제16조 제2항"},{"t":"철회나 거절의 의사표시는 제한능력자에게도 할 수 있다.","src":"민법 제16조 제3항 | 기출 2022-6"},{"t":"속임수: 제한능력자가 속임수로 자기를 능력자로 믿게 한 경우 취소할 수 없다. 미성년자나 피한정후견인이 속임수로 법정대리인의 동의가 있는 것으로 믿게 한 경우도 같다. 제1항은 제한능력자 전체(피성년후견인 포함)에 적용된다.","src":"민법 제17조 | 기출 2021-6 | 기출 2022-6"},{"t":"취소의 효과: 취소된 법률행위는 처음부터 무효로 본다. 제한능력자는 받은 이익이 현존하는 한도에서 상환할 책임이 있다(선악 불문, 이자 가산 없음).","src":"민법 제141조 | 기출 2022-4 | 기출 2025-21"}]},{"머리":"부재자의 재산관리","줄":[{"t":"부재자: 종래의 주소나 거소를 떠난 자. 생존이 분명해도 부재자가 될 수 있다. 법인은 부재자가 될 수 없고 자연인에 한한다.","src":"민법 제22조 | 기출 2021-7 | 기출 2024-5"},{"t":"재산관리인을 정하지 아니한 때: 법원은 이해관계인이나 검사의 청구에 의하여 재산관리에 필요한 처분을 명하여야 한다. 본인의 부재 중 재산관리인의 권한이 소멸한 때에도 같다.","src":"민법 제22조 제1항"},{"t":"재산관리인 개임: 부재자가 재산관리인을 정한 경우 생사가 분명하지 아니하면 법원은 재산관리인ㆍ이해관계인ㆍ검사의 청구에 의하여 재산관리인을 개임할 수 있다.","src":"민법 제23조 | 기출 2023-6"},{"t":"법원이 선임한 재산관리인은 관리할 재산목록을 작성하여야 한다. 법원은 선임한 재산관리인에게 부재자의 재산을 보존하기 위하여 필요한 처분을 명할 수 있다. 비용은 부재자의 재산으로 지급한다.","src":"민법 제24조 | 기출 2022-5"},{"t":"권한: 법원이 선임한 재산관리인이 제118조의 권한(보존행위, 이용ㆍ개량행위)을 넘는 행위를 하려면 법원의 허가를 얻어야 한다. 부재자의 생사가 분명하지 않은 경우 부재자가 정한 재산관리인이 권한을 넘는 행위를 할 때도 같다.","src":"민법 제25조 | 민법 제118조 | 기출 2021-7 | 기출 2022-5 | 기출 2024-5"},{"t":"법원의 허가는 사후적으로 처분행위를 추인하는 방법으로도 할 수 있다. 허가 없이 매각한 후 허가를 얻어 이전등기를 마쳤다면 추인된 것으로 본다.","src":"기출 2023-6 | 기출 2024-5 | 기출 2026-5"},{"t":"법원은 재산관리인에게 재산의 관리 및 반환에 관하여 상당한 담보를 제공하게 할 수 있고, 부재자의 재산으로 상당한 보수를 지급할 수 있다.","src":"민법 제26조 | 기출 2023-6 | 기출 2026-5"},{"t":"법원이 선임한 재산관리인은 법정대리인이다. 언제든지 사임할 수 있다(법원의 허가는 불요).","src":"기출 2021-7 | 기출 2023-6 | 기출 2024-5"},{"t":"재산관리인의 보존행위: 법원 허가 없이 보존행위(예: 말소등기절차 이행청구)를 할 수 있다.","src":"기출 2026-5"},{"t":"법원이 선임한 재산관리인이 부재자의 사망을 확인한 경우에도 선임결정이 취소되지 않는 한 권한을 행사할 수 있다. 선임결정 취소의 효력은 장래에 향하여서만 생기며, 취소 전의 권한 내 행위는 실종선고기간 만료 후에 이루어졌더라도 유효하다.","src":"기출 2023-6 | 기출 2024-5 | 기출 2026-5"},{"t":"부재자가 스스로 재산처분권을 위임한 재산관리인이 재산을 처분하는 데는 법원의 허가가 필요하지 않다(법원 선임 재산관리인과 구별).","src":"기출 2026-5 | 보충(추정)"}]},{"머리":"실종선고","줄":[{"t":"보통실종: 부재자의 생사가 5년간 분명하지 아니한 때 법원은 이해관계인이나 검사의 청구에 의하여 실종선고를 하여야 한다.","src":"민법 제27조 제1항 | 기출 2022-5"},{"t":"특별실종: 전지(戰地)에 임한 자, 침몰한 선박 중에 있던 자, 추락한 항공기 중에 있던 자, 기타 사망의 원인이 될 위난을 당한 자의 생사가 전쟁종지 후 또는 위난 종료 후 1년간 분명하지 아니한 때.","src":"민법 제27조 제2항"},{"t":"잠수장비를 착용하고 입수한 후 행방불명된 것은 특별실종의 원인이 되는 사유에 해당하지 않는다.","src":"기출 2021-7"},{"t":"실종선고의 효과: 실종선고를 받은 자는 실종기간이 만료한 때에 사망한 것으로 본다(선고 시가 아님).","src":"민법 제28조 | 기출 2022-5"},{"t":"실종선고를 받은 자가 종전 주소에서 새로운 법률행위를 하는 데 실종선고의 취소는 필요하지 않다. 생존하는 한 권리능력이 있다.","src":"기출 2021-7 | 기출 2023-3"},{"t":"실종선고의 취소: 실종자의 생존 또는 다른 시기의 사망 사실의 증명이 있으면 법원은 본인ㆍ이해관계인ㆍ검사의 청구로 취소하여야 한다. 실종선고 후 취소 전에 선의로 한 행위의 효력에는 영향이 없다.","src":"민법 제29조 제1항"},{"t":"취소 시 반환: 실종선고를 직접원인으로 재산을 취득한 자가 선의면 현존이익 한도로, 악의면 받은 이익에 이자를 붙이고 손해가 있으면 배상한다.","src":"민법 제29조 제2항"},{"t":"실종선고 청구권자: 이해관계인(법률상 이해관계인)이나 검사. 부재자의 제1순위 상속인이 있으면 제4순위 상속인은 실종선고를 청구할 수 없다(후순위 상속인은 이해관계인이 아님).","src":"민법 제27조 | 기출 2022-5 | 기출 2025-6"},{"t":"실종선고 절차: 가정법원은 6개월 이상 공시최고를 하고, 그 기간 내에 생사의 신고가 없으면 실종을 선고하여야 한다.","src":"기출 2025-6 | 보충(원문 미확인)"}]}],"함정":[{"x":"생존하고 있음이 분명한 자는 부재자가 될 수 없다.","o":"종래의 주소나 거소를 떠난 자이면 생존이 분명해도 부재자가 될 수 있다.","src":"민법 제22조 | 기출 2021-7"},{"x":"법원이 선임한 부재자의 재산관리인은 일종의 법정대리인이므로 자유로이 사임할 수 없다.","o":"법정대리인이지만 언제든지 사임할 수 있다.","src":"기출 2021-7 | 기출 2023-6"},{"x":"법원이 선임한 재산관리인은 법원의 허가가 없더라도 부재자 재산에 대한 처분행위를 자유롭게 할 수 있다.","o":"제118조의 권한을 넘는 처분행위는 법원의 허가를 얻어야 한다.","src":"민법 제25조 | 기출 2021-7 | 기출 2022-5"},{"x":"실종선고를 받은 자가 종전의 주소에서 새로운 법률행위를 하기 위해서는 실종선고를 취소하여야 한다.","o":"실종선고의 취소 없이도 새로운 법률행위를 할 수 있다(권리능력 상실 없음).","src":"기출 2021-7 | 기출 2023-3"},{"x":"태아는 증여와 유증에 관하여 이미 출생한 것으로 본다.","o":"증여에는 적용되지 않는다. 손해배상청구, 상속, 유증, 대습상속에서 개별적으로 인정된다.","src":"기출 2021-8 | 기출 2023-3"},{"x":"미성년자가 제한능력을 이유로 자신의 법률행위를 취소한 경우, 악의인 미성년자는 받은 이익에 이자를 붙여 반환해야 한다.","o":"제한능력자는 선악 불문 현존이익 한도에서 상환한다.","src":"민법 제141조 | 기출 2022-4"},{"x":"법원이 선임한 재산관리인은 법원의 허가 없이도 민법 제118조에서 정한 권한을 넘는 행위를 할 수 있다.","o":"제118조의 권한을 넘는 행위는 법원의 허가가 필요하다.","src":"민법 제25조 | 기출 2022-5"},{"x":"법원은 법원이 선임한 재산관리인에 대하여 부재자의 재산을 보존하기 위하여 필요한 처분을 명할 수 없다.","o":"필요한 처분을 명할 수 있다.","src":"민법 제24조 제2항 | 기출 2022-5"},{"x":"실종선고가 확정되면 실종선고를 받은 자는 실종선고 시에 사망한 것으로 본다.","o":"실종기간이 만료한 때에 사망한 것으로 본다.","src":"민법 제28조 | 기출 2022-5"},{"x":"보통실종의 실종기간은 3년이다.","o":"5년이다(특별실종은 위난 종료 후 1년).","src":"민법 제27조 | 기출 2022-5"},{"x":"피성년후견인이 적극적으로 속임수를 써서 자기를 능력자로 믿게 한 경우에도 그 행위를 취소할 수 있다.","o":"제한능력자가 속임수로 능력자로 믿게 한 경우에는 취소할 수 없다.","src":"민법 제17조 제1항 | 기출 2022-6"},{"x":"태아는 법정대리인에 의한 수증행위를 할 수 있다.","o":"태아는 증여에 관하여 이미 출생한 것으로 보지 않으므로 법정대리인이 수증행위를 할 수 없다.","src":"기출 2023-3 | 보충"},{"x":"인정사망 후 그에 대한 반증만으로 사망의 추정력이 상실되는 것은 아니다.","o":"출제 오답(바른 설명 미확인). 인정사망은 반증으로 번복될 수 있는 추정으로 이해한다.","src":"기출 2023-3 | 보충(추정)"},{"x":"출생 후 그 사실이 가족관계등록부에 기재되어야 권리능력이 인정된다.","o":"출생 시 권리능력을 취득한다.","src":"기출 2023-3"},{"x":"2인 이상이 동일한 위난으로 사망한 경우에는 동시에 사망한 것으로 간주된다.","o":"동시에 사망한 것으로 추정한다.","src":"민법 제30조 | 기출 2023-3 | 기출 2026-3"},{"x":"甲이 성년자가 되더라도 丙은 甲에게 계약의 추인 여부에 대한 확답을 촉구할 수 없다.","o":"능력자가 된 甲에게 1개월 이상의 기간을 정하여 확답을 촉구할 수 있다.","src":"민법 제15조 제1항 | 기출 2023-4"},{"x":"丙이 계약체결 당시 甲이 미성년자임을 알았다면, 丙은 법정대리인 乙에게 추인 여부의 확답을 촉구할 수 없다.","o":"악의여도 확답 촉구는 할 수 있다. 악의이면 철회만 할 수 없다.","src":"민법 제15조ㆍ제16조 | 기출 2023-4"},{"x":"특정후견의 심판이 있으면 피특정후견인의 행위능력이 제한된다.","o":"제한되지 않는다.","src":"기출 2023-5"},{"x":"가정법원은 피한정후견인에 대하여 한정후견의 종료 심판 없이 성년후견개시의 심판을 할 수 있다.","o":"성년후견개시 시 종전 한정후견의 종료 심판을 한다.","src":"민법 제14조의3 | 기출 2023-5"},{"x":"의사능력이 없는 자는 성년후견개시의 심판 없이도 피성년후견인이 된다.","o":"성년후견개시의 심판을 받아야 피성년후견인이 된다.","src":"기출 2023-5"},{"x":"피한정후견인이 동의를 요하는 법률행위를 동의 없이 하였더라도 그 후 한정후견심판이 종료되었다면 그 법률행위는 취소할 수 없다.","o":"종료 후에도 취소할 수 있다.","src":"기출 2023-5"},{"x":"법원이 선임한 재산관리인이 부재자의 사망을 확인하였다면, 그 선임결정이 취소되지 않아도 재산관리인은 권한을 행사할 수 없다.","o":"선임결정이 취소되지 않는 한 권한을 행사할 수 있다.","src":"기출 2023-6"},{"x":"법원은 인정사망이나 실종선고에 의하지 않고 경험칙에 의거하여 사람의 사망사실을 인정할 수 없다.","o":"경험칙에 의한 사망사실의 인정이 가능하다.","src":"기출 2024-4"},{"x":"법원이 선임한 재산관리인의 권한초과행위에 대한 법원의 허가는 사후적으로 그 행위를 추인하는 방법으로는 할 수 없다.","o":"사후 추인의 방법으로도 할 수 있다.","src":"기출 2024-5 | 기출 2026-5"},{"x":"가정법원은 본인의 의사에 반하더라도 특정사무에 관한 후원의 필요가 있으면 특정후견 심판을 할 수 있다.","o":"특정후견은 본인의 의사에 반하여 할 수 없다.","src":"민법 제14조의2 제2항 | 기출 2024-6 | 기출 2026-4"},{"x":"법인은 유증을 받을 수 있는 능력이 없다.","o":"법인도 유증을 받을 수 있다.","src":"기출 2025-4"},{"x":"청산법인의 권리능력은 청산의 목적범위내로 제한되지 않는다.","o":"청산의 목적범위 내에서만 권리ㆍ의무가 있다.","src":"민법 제81조 | 기출 2025-4"},{"x":"태아는 채무불이행으로 인한 손해배상청구권에 관하여 이미 출생한 것으로 본다.","o":"불법행위로 인한 손해배상청구권에 관해 인정된다.","src":"민법 제762조 | 기출 2025-4"},{"x":"사람의 권리능력은 당사자의 합의에 의하여 제한할 수 있다.","o":"합의로 제한할 수 없다. 제한하는 약정은 무효다.","src":"기출 2021-8 | 기출 2025-4"},{"x":"미성년자가 타인의 대리인으로서 대리행위를 하기 위해서는 법정대리인의 승낙을 얻어야 한다.","o":"대리인은 행위능력자임을 요하지 않는다. 승낙이 필요 없다.","src":"민법 제117조 | 기출 2025-5"},{"x":"乙이 실종선고를 청구하지 않을 경우, 丙은 상속에 관한 이해관계인으로서 법원에 실종선고를 청구할 수 있다.","o":"선순위 상속인이 있으면 후순위 상속인은 이해관계인으로서 청구할 수 없다.","src":"기출 2022-5 | 기출 2025-6"},{"x":"자연인은 출생신고 시부터 권리능력을 취득한다.","o":"출생 시부터 취득한다.","src":"기출 2026-3"},{"x":"반려동물은 위자료청구권의 귀속주체가 될 수 있다.","o":"물건이므로 귀속주체가 될 수 없다.","src":"기출 2026-3"},{"x":"2인 이상이 동일한 위난으로 사망한 경우에는 동시에 사망한 것으로 본다.","o":"동시에 사망한 것으로 추정한다.","src":"민법 제30조 | 기출 2026-3"},{"x":"인정사망 후에는 반대 증거가 제출되더라도 그 효력이 소멸하지 않는다.","o":"출제 오답(바른 설명 미확인). 반증이 있으면 번복된다고 이해한다.","src":"기출 2026-3 | 보충(추정)"},{"x":"가정법원은 정신적 제약으로 일시적 후원이 필요한 사람에 대하여는 본인의 의사에 반하여 특정후견심판을 할 수 있다.","o":"본인의 의사에 반하여 할 수 없다.","src":"민법 제14조의2 제2항 | 기출 2026-4"},{"x":"부재자로부터 재산처분권을 위임받은 재산관리인이 그 재산을 처분하기 위해서는 특별한 사정이 없는 한 법원의 허가가 필요하다.","o":"법원의 허가가 필요한 것은 법원이 선임한 재산관리인이다. 부재자가 스스로 위임한 재산관리인에게는 허가가 필요 없다.","src":"기출 2026-5 | 보충(추정)"}]},"법인":{"묶음":[{"머리":"법인의 성립과 종류","줄":[{"t":"법인법정주의: 법인은 법률의 규정에 의함이 아니면 성립하지 못한다.","src":"민법 제31조 | 기출 2023-9 | 기출 2024-9"},{"t":"비영리법인: 학술ㆍ종교ㆍ자선ㆍ기예ㆍ사교 기타 영리 아닌 사업을 목적으로 하는 사단 또는 재단은 주무관청의 허가를 얻어 법인으로 할 수 있다(허가주의). 종교사업 사단도 허가(인가 아님)다.","src":"민법 제32조 | 기출 2021-9 | 기출 2025-7"},{"t":"영리법인: 영리를 목적으로 하는 사단은 상사회사 설립의 조건에 좇아 법인으로 할 수 있고 상사회사에 관한 규정을 준용한다. 영리 목적의 재단은 법인이 될 수 없다. 재단법인은 항상 비영리법인이다.","src":"민법 제39조 | 기출 2021-9 | 기출 2025-7 | 기출 2026-9"},{"t":"법인의 성립시기: 법인은 주된 사무소의 소재지에서 설립등기를 함으로써 성립한다. 설립등기는 성립요건이다(대항요건 아님). 사단법인은 정관이 작성된 때가 아니라 설립등기 시에 성립한다.","src":"민법 제33조 | 기출 2022-16 | 기출 2023-9 | 기출 2025-7 | 기출 2026-9"},{"t":"법인의 권리능력: 법률의 규정에 좇아 정관으로 정한 목적의 범위 내에서 권리와 의무의 주체가 된다.","src":"민법 제34조"},{"t":"법인의 불법행위능력: 이사 기타 대표자가 직무에 관하여 타인에게 가한 손해를 배상할 책임이 있고, 대표자 개인의 책임도 면하지 못한다. 목적범위 외 행위로 손해를 가한 때에는 의결에 찬성하거나 집행한 사원ㆍ이사ㆍ대표자가 연대하여 배상한다.","src":"민법 제35조"},{"t":"대표권 없는 이사는 법인의 대표기관이 아니므로 그의 행위로 법인의 불법행위가 성립하지 않는다.","src":"기출 2022-8"},{"t":"법인의 주소는 주된 사무소의 소재지에 있는 것으로 한다.","src":"민법 제36조"},{"t":"법인의 사무는 주무관청이 검사ㆍ감독한다. 법인의 해산 및 청산은 법원이 검사ㆍ감독한다.","src":"민법 제37조 | 민법 제95조 | 기출 2022-9 | 기출 2025-9"},{"t":"설립허가의 취소: 법인이 목적 이외의 사업을 하거나 설립허가의 조건에 위반하거나 기타 공익을 해하는 행위를 한 때 주무관청은 그 허가를 취소할 수 있다.","src":"민법 제38조 | 기출 2021-9"}]},{"머리":"설립행위와 정관","줄":[{"t":"사단법인의 설립행위: 설립자가 정관을 작성하여 기명날인하여야 하는 요식행위다(2인 이상). 주무관청의 허가가 필요하다.","src":"민법 제40조 | 기출 2021-9 | 기출 2023-9"},{"t":"사단법인 정관의 필요적 기재사항(7가지): 목적, 명칭, 사무소의 소재지, 자산에 관한 규정, 이사의 임면에 관한 규정, 사원자격의 득실에 관한 규정, 존립시기나 해산사유를 정하는 때에는 그 시기 또는 사유.","src":"민법 제40조 | 기출 2021-12 | 기출 2024-7 | 기출 2025-7 | 기출 2026-9"},{"t":"필요적 기재사항이 아닌 것: 이사회의 구성에 관한 규정, 감사의 임면에 관한 규정. 존립시기ㆍ해산사유는 정한 경우에만 기재한다.","src":"기출 2024-7 | 기출 2024-9 | 민법 제40조"},{"t":"재단법인의 정관: 설립자가 일정한 재산을 출연하고 제40조 제1호~제5호(목적, 명칭, 사무소 소재지, 자산에 관한 규정, 이사 임면에 관한 규정)를 기재한 정관을 작성하여 기명날인하여야 한다. 존립시기ㆍ해산사유는 필요적 기재사항이 아니다.","src":"민법 제43조 | 기출 2022-7 | 기출 2023-12 | 기출 2025-9"},{"t":"재단법인 설립자가 명칭, 사무소 소재지, 이사 임면 방법을 정하지 않고 사망한 때: 이해관계인 또는 검사의 청구에 의해 법원이 이를 정한다.","src":"민법 제44조 | 기출 2021-12"},{"t":"재단법인 설립행위: 생전처분이면 증여, 유언이면 유증에 관한 규정을 준용한다. 출연재산은 생전처분이면 법인이 성립한 때, 유언이면 유언의 효력이 발생한 때 법인에 귀속한다. 설립행위는 요식행위이며 출연자도 착오를 이유로 출연의 의사표시를 취소할 수 있다.","src":"민법 제47조 | 민법 제48조 | 기출 2021-9 | 기출 2026-9"},{"t":"사단법인 정관의 법적 성질은 계약이 아니라 자치법규다. 사원총회가 정관의 규범적 의미와 다른 해석을 결의로 표명해도 사원이나 법원을 구속하지 않는다.","src":"기출 2021-12 | 기출 2023-9 | 기출 2025-9 | 기출 2026-12"},{"t":"정관의 임의적 기재사항도 정관에 기재되면 그 변경은 정관변경 절차에 따라야 한다.","src":"기출 2026-12"}]},{"머리":"정관의 변경","줄":[{"t":"사단법인 정관변경: 총사원 3분의 2 이상의 동의가 있어야 한다(정수에 관해 정관에 다른 규정이 있으면 그에 의함). 주무관청의 허가를 얻지 아니하면 효력이 없다.","src":"민법 제42조 | 기출 2023-9 | 기출 2026-12"},{"t":"재단법인 정관변경: 변경방법을 정관에 정한 때에 한하여 가능. 목적달성 또는 재산보전을 위하여 적당한 때에는 명칭 또는 사무소 소재지를 변경할 수 있다. 어느 경우든 주무관청의 허가를 얻어야 한다.","src":"민법 제45조 | 기출 2026-12"},{"t":"재단법인의 목적을 달성할 수 없는 때: 설립자나 이사는 주무관청의 허가를 얻어 설립의 취지를 참작하여 목적 기타 정관 규정을 변경할 수 있다.","src":"민법 제46조 | 기출 2021-12 | 기출 2024-9"},{"t":"재단법인이 부동산을 기본재산으로 새로이 편입시키는 행위는 정관변경에 해당하여 주무관청의 허가를 얻어야 유효하다.","src":"기출 2025-9 | 기출 2026-12"},{"t":"재단법인의 기본재산에 관한 저당권 설정행위는 특별한 사정이 없는 한 정관변경을 필요로 하지 않으므로 주무관청의 허가가 필요하지 않다.","src":"기출 2021-12 | 기출 2026-9"}]},{"머리":"법인의 등기","줄":[{"t":"설립등기: 설립허가가 있는 때에는 3주간 내에 주된 사무소 소재지에서 설립등기를 하여야 한다. 등기기간은 허가서가 도착한 날부터 기산한다.","src":"민법 제49조 제1항 | 민법 제53조 | 기출 2022-16"},{"t":"등기사항(9가지): 목적, 명칭, 사무소, 설립허가의 연월일, 존립시기나 해산이유를 정한 때 그 시기 또는 사유, 자산의 총액, 출자의 방법을 정한 때 그 방법, 이사의 성명ㆍ주소, 이사의 대표권을 제한한 때 그 제한.","src":"민법 제49조 제2항 | 기출 2022-16 | 기출 2025-8"},{"t":"감사의 성명ㆍ주소는 등기사항이 아니다. 이사의 성명과 주소는 등기사항이다.","src":"민법 제49조 제2항 | 기출 2024-9 | 기출 2025-8"},{"t":"분사무소 설치: 주사무소 소재지에서 3주일 내에 분사무소 소재지와 설치 연월일을 등기한다.","src":"민법 제50조"},{"t":"사무소 이전: 주사무소 이전은 종전 소재지 또는 새 소재지에서 3주일 내에 새 소재지와 이전 연월일을 등기한다. 같은 등기소 관할구역 내 이전이면 그 이전을 등기하면 된다.","src":"민법 제51조 | 기출 2022-16"},{"t":"변경등기: 등기사항에 변경이 있으면 3주간 내에 한다.","src":"민법 제52조"},{"t":"설립등기 이외의 등기사항은 등기 후가 아니면 제3자에게 대항하지 못한다. 등기한 사항은 법원이 지체없이 공고한다.","src":"민법 제54조"},{"t":"직무집행정지ㆍ직무대행자 선임 가처분은 주사무소 소재지 등기소에서 등기한다. 직무대행자는 법원의 허가 없이 통상사무에 속하지 않는 행위를 못하지만, 위반해도 법인은 선의의 제3자에 대하여 책임을 진다.","src":"민법 제52조의2 | 민법 제60조의2"},{"t":"재산목록과 사원명부: 성립한 때 및 매년 3월 내에 재산목록을 작성해 사무소에 비치한다. 사단법인은 사원명부를 비치한다.","src":"민법 제55조"},{"t":"사단법인의 사원의 지위는 양도 또는 상속할 수 없다. 정관에 별도의 정함이 있으면 상속될 수 있다.","src":"민법 제56조 | 기출 2024-9"}]},{"머리":"이사와 감사","줄":[{"t":"법인은 이사를 두어야 한다(필수기관). 이사의 수와 임기는 제한이 없고 정관으로 정한다.","src":"민법 제57조 | 기출 2025-8 | 기출 2026-10"},{"t":"이사의 사무집행: 이사는 법인의 사무를 집행한다. 이사가 수인이면 정관에 다른 규정이 없는 한 이사의 과반수로 결정한다.","src":"민법 제58조"},{"t":"이사의 대표권: 이사는 법인의 사무에 관하여 각자 법인을 대표한다. 정관의 취지에 위반할 수 없고 특히 사단법인은 총회의 의결에 의한다. 대표에 관하여는 대리에 관한 규정을 준용한다.","src":"민법 제59조 | 기출 2022-8"},{"t":"대표권 제한: 정관에 기재하지 아니하면 효력이 없다. 기재하더라도 등기하지 아니하면 제3자에게 대항하지 못한다.","src":"민법 제41조 | 민법 제60조 | 기출 2021-11 | 기출 2022-8 | 기출 2025-7 | 기출 2026-10"},{"t":"비법인사단의 정관에 대표권 제한이 있어도 거래 상대방이 제한을 알지 못하고(선의) 과실이 없다면 거래행위는 유효하다. 제60조(등기 요건)는 비법인사단에 유추적용되지 않는다.","src":"기출 2022-8 | 기출 2023-11"},{"t":"이사의 주의의무: 선량한 관리자의 주의로 직무를 행한다. 임무를 해태한 이사는 법인에 대하여 연대하여 손해배상 책임이 있다.","src":"민법 제61조 | 민법 제65조"},{"t":"이사의 대리인 선임: 정관 또는 총회의 결의로 금지하지 아니한 사항에 한하여 타인으로 하여금 특정한 행위를 대리하게 할 수 있다.","src":"민법 제62조 | 기출 2022-8"},{"t":"임시이사: 이사가 없거나 결원이 있는 경우 이로 인하여 손해가 생길 염려가 있으면 법원은 이해관계인이나 검사의 청구에 의하여 임시이사를 선임하여야 한다(법원 직권 아님).","src":"민법 제63조 | 기출 2021-11 | 기출 2026-10"},{"t":"특별대리인: 법인과 이사의 이익이 상반하는 사항에 관하여 이사는 대표권이 없고, 이 경우 특별대리인을 선임하여야 한다(임시이사 아님).","src":"민법 제64조 | 기출 2024-9 | 기출 2025-8 | 기출 2026-10"},{"t":"이사는 주무관청의 허가 없이도 사임할 수 있다.","src":"기출 2026-10"},{"t":"감사: 법인은 정관 또는 총회의 결의로 감사를 둘 수 있다(임의기관). 사단법인은 감사를 두지 않을 수 있다.","src":"민법 제66조 | 기출 2021-11"},{"t":"감사의 직무(4가지): ① 법인의 재산상황 감사 ② 이사의 업무집행 상황 감사 ③ 재산상황 또는 업무집행에 부정ㆍ불비가 있음을 발견한 때 총회 또는 주무관청에 보고 ④ 보고를 위해 필요한 때 총회 소집.","src":"민법 제67조 | 기출 2025-8"}]},{"머리":"사원총회","줄":[{"t":"총회의 권한: 사단법인의 사무는 정관으로 이사 또는 기타 임원에게 위임한 사항 외에는 총회의 결의에 의하여야 한다.","src":"민법 제68조"},{"t":"통상총회: 이사는 매년 1회 이상 소집하여야 한다.","src":"민법 제69조 | 기출 2025-8"},{"t":"임시총회: 이사가 필요하다고 인정한 때 소집할 수 있다. 총사원의 5분의 1 이상이 회의의 목적사항을 제시하여 청구하면 이사는 소집하여야 한다(정수는 정관으로 증감 가능). 청구 후 2주간 내에 소집절차를 밟지 않으면 청구한 사원이 법원의 허가를 얻어 소집할 수 있다.","src":"민법 제70조"},{"t":"총회의 소집: 1주간 전에 그 회의의 목적사항을 기재한 통지를 발하고 기타 정관에 정한 방법에 의한다(통지를 발송하면 되고 도달할 필요는 없다).","src":"민법 제71조 | 기출 2023-19"},{"t":"총회는 소집통지에서 목적사항으로 기재한 사항에 관하여서만 결의할 수 있다(정관에 다른 규정이 있으면 그에 의함). 목적사항으로 기재하지 않은 사항의 결의는 특별한 사정이 없는 한 무효다.","src":"민법 제72조 | 기출 2021-11"},{"t":"결의권: 각 사원의 결의권은 평등이다. 서면이나 대리인으로 행사할 수 있다. 정관에 다른 규정이 있으면 적용하지 않는다.","src":"민법 제73조"},{"t":"사단법인과 어느 사원과의 관계사항을 의결하는 경우 그 사원은 결의권이 없다.","src":"민법 제74조 | 기출 2021-11"},{"t":"결의방법: 본법 또는 정관에 다른 규정이 없으면 사원 과반수의 출석과 출석사원의 결의권의 과반수로 한다. 서면ㆍ대리인으로 결의권을 행사하는 사원은 출석한 것으로 본다.","src":"민법 제75조"},{"t":"의사록: 총회의 의사에 관하여 의사록을 작성한다. 의사의 경과ㆍ요령ㆍ결과를 기재하고 의장 및 출석한 이사가 기명날인한다. 이사는 주된 사무소에 비치한다.","src":"민법 제76조"}]},{"머리":"해산","줄":[{"t":"해산사유(공통): 존립기간의 만료, 법인의 목적의 달성 또는 달성의 불능 기타 정관에 정한 해산사유의 발생, 파산, 설립허가의 취소.","src":"민법 제77조 제1항 | 기출 2021-10 | 기출 2022-9 | 기출 2023-12"},{"t":"사단법인에만 있는 해산사유: 사원이 없게 되거나 총회의 결의. 재단법인에는 적용되지 않는다.","src":"민법 제77조 제2항 | 기출 2021-10 | 기출 2024-8"},{"t":"사단법인의 해산결의는 총사원 4분의 3 이상의 동의가 있어야 한다. 정관에 다른 규정이 있으면 그에 의한다.","src":"민법 제78조 | 기출 2021-10 | 기출 2025-9"},{"t":"사원이 없게 되면 법인의 해산사유가 될 뿐, 이로써 곧 권리능력이 소멸하는 것은 아니다.","src":"기출 2022-9"},{"t":"법인이 채무를 완제하지 못하게 된 때 이사는 지체없이 파산신청을 하여야 한다.","src":"민법 제79조"},{"t":"목적달성이 불가능한 경우 별도의 설립허가 취소 없이 해산사유가 된다. 재단법인의 목적 달성도 해산사유다.","src":"민법 제77조 | 기출 2022-9 | 기출 2023-12"}]},{"머리":"청산","줄":[{"t":"청산법인: 해산한 법인은 청산의 목적범위 내에서만 권리가 있고 의무를 부담한다.","src":"민법 제81조 | 기출 2024-8"},{"t":"청산인: 법인이 해산한 때(파산 제외) 이사가 청산인이 된다. 정관 또는 총회의 결의로 달리 정하면 그에 의한다. 청산인이 될 자가 없거나 결원으로 손해 염려가 있으면 법원이 직권 또는 이해관계인ㆍ검사의 청구로 선임할 수 있다. 중요한 사유가 있으면 법원이 해임할 수 있다.","src":"민법 제82조 | 민법 제83조 | 민법 제84조"},{"t":"해산등기: 청산인은 파산이 아닌 경우 취임 후 3주일 내에 해산 사유와 연월일, 청산인의 성명ㆍ주소, 청산인의 대표권 제한을 주사무소 소재지에서 등기한다. 주무관청에 3주간 내 신고한다.","src":"민법 제85조 | 민법 제86조"},{"t":"청산인의 직무: ① 현존사무의 종결 ② 채권의 추심 및 채무의 변제 ③ 잔여재산의 인도. 이 직무를 행하기 위하여 필요한 모든 행위를 할 수 있다.","src":"민법 제87조 | 기출 2024-8"},{"t":"채권신고의 공고: 취임한 날로부터 2월 내에 3회 이상의 공고로 채권자에게 일정 기간(2월 이상) 내 채권을 신고하도록 최고한다. 신고하지 아니하면 청산에서 제외될 것을 표시한다.","src":"민법 제88조"},{"t":"알고 있는 채권자에게는 각각 채권신고를 최고하여야 하고, 알고 있는 채권자는 청산으로부터 제외하지 못한다.","src":"민법 제89조 | 기출 2024-8"},{"t":"신고기간 내에는 채권자에게 변제하지 못한다. 법인은 지연손해배상 의무를 면하지 못한다.","src":"민법 제90조"},{"t":"청산 중의 법인은 변제기에 이르지 아니한 채권에 대하여도 변제할 수 있다. 조건 있는 채권 등 가액 불확정 채권은 법원이 선임한 감정인의 평가에 의하여 변제한다.","src":"민법 제91조 | 기출 2022-9 | 기출 2023-12"},{"t":"청산으로부터 제외된 채권자는 법인의 채무를 완제한 후 귀속권리자에게 인도하지 아니한 재산에 대하여서만 변제를 청구할 수 있다.","src":"민법 제92조"},{"t":"청산 중 재산이 채무를 완제하기에 부족함이 분명하면 청산인은 지체없이 파산선고를 신청하고 공고한다. 파산관재인에게 사무를 인계하면 임무가 종료한다.","src":"민법 제93조"},{"t":"청산종결: 청산인은 3주간 내에 등기하고 주무관청에 신고한다(감사가 아님). 청산사무가 종결되지 않았다면 청산종결등기가 되어도 법인은 소멸하지 않는다.","src":"민법 제94조 | 기출 2022-16 | 기출 2023-12 | 보충(추정)"},{"t":"잔여재산의 귀속: ① 정관으로 지정한 자에게 귀속 ② 지정이 없으면 이사 또는 청산인이 주무관청의 허가를 얻어 법인의 목적과 유사한 목적을 위하여 처분(사단법인은 총회 결의 필요) ③ 처분되지 않은 재산은 국고에 귀속(출연자 귀속 아님).","src":"민법 제80조 | 기출 2024-8"},{"t":"정관 또는 청산절차 규정에 반하는 잔여재산 처분행위는 특별한 사정이 없는 한 무효다.","src":"기출 2022-9 | 기출 2023-12"},{"t":"청산인에 대하여는 제58조 제2항, 제59조~제62조, 제64조, 제65조, 제70조를 준용한다.","src":"민법 제96조"},{"t":"과태료: 법인의 이사ㆍ감사 또는 청산인이 등기 해태, 재산목록ㆍ사원명부 부정기재, 검사ㆍ감독 방해 등을 한 때 500만원 이하의 과태료.","src":"민법 제97조"}]},{"머리":"법인 아닌 사단ㆍ재단","줄":[{"t":"총유: 법인이 아닌 사단의 사원이 집합체로서 물건을 소유할 때 총유로 한다. 총유물의 관리 및 처분은 사원총회의 결의에 의한다. 각 사원은 정관 기타 규약에 좇아 사용ㆍ수익할 수 있다.","src":"민법 제275조 | 민법 제276조 | 기출 2023-11"},{"t":"총유물의 보존행위도 사원총회 결의가 필요하며, 구성원 개인은 특별한 사정이 없는 한 총유재산의 보존을 위한 소를 단독으로 제기할 수 없다(사원 각자가 할 수 없다).","src":"기출 2023-11 | 기출 2024-10"},{"t":"비법인사단이 타인 간의 금전채무를 보증하는 행위는 총유물의 관리ㆍ처분행위가 아니다. 사원총회 결의를 거치지 않았어도 특별한 사정이 없는 한 계약은 유효하다.","src":"기출 2023-11 | 기출 2025-10"},{"t":"비법인사단의 채권자가 채권자대위권으로 총유재산에 대한 권리를 대위행사할 때는 사원총회 결의 등 내부 의사결정을 거칠 필요가 없다.","src":"기출 2025-10 | 보충(추정)"},{"t":"비법인사단ㆍ재단은 대표자(관리인)가 있으면 그 이름으로 민사소송의 당사자가 될 수 있다.","src":"기출 2024-10 | 기출 2025-10"},{"t":"고유한 의미의 종중의 경우 종중원이 종중을 임의로 탈퇴할 수 없다.","src":"기출 2023-11"},{"t":"공동주택의 입주자대표회의는 동별 세대수에 비례하여 선출되는 동별 대표자를 구성원으로 하는 법인 아닌 사단에 해당한다.","src":"기출 2024-10"},{"t":"법인 아닌 재단은 법인격이 없으나 대표자 또는 관리인이 있으면 당사자능력이 인정된다. 민법이 법인 아닌 재단의 재산 소유를 단독소유로 규정한 것은 아니다.","src":"기출 2024-10"},{"t":"합유: 법률의 규정 또는 계약에 의하여 수인이 조합체로서 물건을 소유하는 때. 합유물의 처분ㆍ변경은 합유자 전원의 동의, 보존행위는 각자. 지분처분은 전원의 동의가 필요하고 분할을 청구하지 못한다.","src":"민법 제271조 | 민법 제272조 | 민법 제273조"}]}],"함정":[{"x":"사단법인 설립행위는 법률행위이므로 특별한 방식이 요구되지 않는다.","o":"정관을 작성하여 기명날인해야 하는 요식행위다.","src":"민법 제40조 | 기출 2021-9"},{"x":"사단법인은 주무관청의 허가 없이 자유롭게 설립할 수 있다.","o":"주무관청의 허가를 얻어야 한다(허가주의).","src":"민법 제32조 | 기출 2021-9"},{"x":"재단법인 설립행위는 단독행위이므로 출연자라 하더라도 착오를 이유로 출연의 의사표시를 취소할 수 없다.","o":"출연자도 착오를 이유로 취소할 수 있다.","src":"기출 2021-9 | 기출 2023-17"},{"x":"법인이 목적 이외의 사업을 하더라도 주무관청은 설립허가 자체를 취소할 수 없다.","o":"주무관청은 설립허가를 취소할 수 있다.","src":"민법 제38조 | 기출 2021-9"},{"x":"이사의 결원으로 인하여 손해가 발생할 염려가 있는 경우, 법원은 직권으로 임시이사를 선임할 수 있다.","o":"이해관계인이나 검사의 청구에 의하여 선임한다.","src":"민법 제63조 | 기출 2021-11"},{"x":"재단법인의 목적을 달성할 수 없다고 하여 이사가 주무관청의 허가를 얻어 정관을 변경할 수는 없다.","o":"설립자나 이사가 주무관청의 허가를 얻어 목적 기타 정관규정을 변경할 수 있다.","src":"민법 제46조 | 기출 2021-12"},{"x":"법인의 정관에 규정된 대표권제한을 등기하지 않았더라도 그 제한으로 악의의 제3자에게 대항할 수 있다.","o":"등기하지 아니하면 선악을 불문하고 제3자에게 대항하지 못한다.","src":"민법 제60조 | 기출 2022-8"},{"x":"법인의 목적달성이 불가능한 경우, 법인은 설립허가가 취소되어야 해산할 수 있다.","o":"목적달성의 불능은 그 자체가 해산사유다.","src":"민법 제77조 | 기출 2022-9"},{"x":"청산이 종결한 때에는 감사는 3주간내에 이를 등기하고 주무관청에 신고해야 한다.","o":"청산인이 한다.","src":"민법 제94조 | 기출 2022-16"},{"x":"사단법인의 정관변경은 총사원 3분의 2 이상의 동의가 있으면 주무관청의 허가가 없더라도 그 효력이 생긴다.","o":"주무관청의 허가를 얻지 아니하면 효력이 없다.","src":"민법 제42조 | 기출 2023-9 | 기출 2026-12"},{"x":"법인 아닌 사단이 타인 간의 금전채무를 보증하는 행위는 총유물의 관리ㆍ처분행위에 해당한다.","o":"총유물의 관리ㆍ처분행위에 해당하지 않는다.","src":"기출 2023-11"},{"x":"재단법인의 목적 달성은 해산사유가 될 수 없다.","o":"목적의 달성 또는 달성 불능은 해산사유다.","src":"민법 제77조 | 기출 2023-12"},{"x":"청산 중인 법인은 변제기에 이르지 않은 채권에 대하여 변제할 수 없다.","o":"변제기에 이르지 아니한 채권에 대하여도 변제할 수 있다.","src":"민법 제91조 | 기출 2023-12"},{"x":"재단법인의 해산사유는 정관의 필요적 기재사항이다.","o":"필요적 기재사항이 아니다(제43조는 제40조 제1~5호만 준용).","src":"민법 제43조 | 기출 2023-12"},{"x":"법인의 청산사무가 종결되지 않았더라도 법인에 대한 청산종결등기가 마쳐지면 법인은 소멸한다.","o":"청산사무가 종결되어야 소멸한다.","src":"기출 2023-12 | 보충(추정)"},{"x":"재단법인은 사원이 없게 되거나 총회의 결의로도 해산한다.","o":"사원이 없게 되거나 총회 결의로 해산하는 것은 사단법인이다.","src":"민법 제77조 제2항 | 기출 2024-8"},{"x":"해산한 법인의 재산은 정관으로 지정한 자에게 귀속하고, 정관에 정함이 없으면 출연자에게 귀속한다.","o":"정관에 정함이 없으면 이사 또는 청산인이 주무관청의 허가를 얻어 유사 목적으로 처분하고, 처분되지 않은 재산은 국고에 귀속한다.","src":"민법 제80조 | 기출 2024-8"},{"x":"청산인은 현존사무의 종결, 채권의 추심 및 채무의 변제, 잔여재산의 인도만 할 수 있다.","o":"이 직무를 행하기 위하여 필요한 모든 행위를 할 수 있다.","src":"민법 제87조 제2항 | 기출 2024-8"},{"x":"청산인은 알고 있는 채권자에게 채권신고를 최고하여야 하고, 최고를 받은 그 채권자가 채권신고를 하지 않으면 청산으로부터 제외하여야 한다.","o":"알고 있는 채권자는 청산으로부터 제외하지 못한다.","src":"민법 제89조 | 기출 2024-8"},{"x":"감사의 임면에 관한 규정은 정관의 필요적 기재사항이므로 감사의 성명과 주소는 법인의 등기사항이다.","o":"감사 임면은 필요적 기재사항이 아니고 감사의 성명ㆍ주소도 등기사항이 아니다.","src":"민법 제40조ㆍ제49조 | 기출 2024-9"},{"x":"법인설립등기는 법인의 대항요건이다.","o":"성립요건이다.","src":"민법 제33조 | 기출 2025-7"},{"x":"종교사업을 목적으로 하는 사단은 주무관청의 인가를 얻어 이를 법인으로 할 수 있다.","o":"주무관청의 허가를 얻어야 한다.","src":"민법 제32조 | 기출 2025-7"},{"x":"이사의 대표권의 제한은 정관에 기재하지 않더라도 그 효력이 있다.","o":"정관에 기재하지 아니하면 효력이 없다.","src":"민법 제41조 | 기출 2025-7"},{"x":"영리를 목적으로 하는 재단은 상사회사설립의 조건에 좇아 이를 법인으로 할 수 있으며, 그러한 법인에는 상사회사에 관한 규정을 준용한다.","o":"영리 목적의 사단이 상사회사 설립의 조건으로 법인이 될 수 있다. 영리 재단은 법인이 될 수 없다.","src":"민법 제39조 | 기출 2025-7"},{"x":"법인과 이사의 이익이 상반하는 경우, 법원은 이해관계인의 청구에 의하여 임시이사를 선임하여야 한다.","o":"특별대리인을 선임한다.","src":"민법 제64조 | 기출 2025-8"},{"x":"사단법인은 총 사원 4분의 3 이상의 동의가 없으면 해산을 결의하지 못하고, 이는 정관에 다른 규정이 있더라도 마찬가지이다.","o":"정관에 다른 규정이 있으면 그에 의한다.","src":"민법 제78조 | 기출 2025-9"},{"x":"재단법인은 영리법인으로 설립할 수 있다.","o":"재단법인은 항상 비영리법인이다.","src":"민법 제32조ㆍ제39조 | 기출 2026-9"},{"x":"사단법인은 정관이 작성된 때로부터 성립한다.","o":"설립등기를 함으로써 성립한다.","src":"민법 제33조 | 기출 2026-9"},{"x":"재단법인의 설립행위는 법률행위이므로 특별한 방식이 요구되지 않는다.","o":"서면으로 정관을 작성하고 기명날인하는 요식행위다.","src":"민법 제43조 | 기출 2026-9"},{"x":"사단법인의 정관에는 자산에 관한 규정을 기재하지 않아도 된다.","o":"자산에 관한 규정은 필요적 기재사항이다.","src":"민법 제40조 제4호 | 기출 2025-7 | 기출 2026-9"},{"x":"법인과 이사의 이익이 상반하는 경우, 임시이사를 선임하여야 한다.","o":"특별대리인을 선임한다.","src":"민법 제64조 | 기출 2026-10"},{"x":"이사는 주무관청의 허가가 없으면 사임할 수 없다.","o":"허가 없이도 사임할 수 있다.","src":"기출 2026-10"},{"x":"이사의 대표권에 대한 제한은 이를 등기하지 않더라도 제3자에 대하여 대항할 수 있다.","o":"등기하지 아니하면 제3자에게 대항하지 못한다.","src":"민법 제60조 | 기출 2026-10"},{"x":"이사의 결원으로 인하여 손해가 발생할 염려가 있는 경우, 법원은 직권으로 특별대리인을 선임할 수 있다.","o":"이해관계인이나 검사의 청구로 법원이 임시이사를 선임한다.","src":"민법 제63조 | 기출 2026-10"},{"x":"사단법인의 정관변경은 총사원 3분의 2 이상의 동의가 있으면 주무관청의 허가를 얻지 않아도 그 효력이 있다.","o":"허가를 얻어야 효력이 있다.","src":"민법 제42조 | 기출 2026-12"},{"x":"정관에서 정한 변경방법을 따른 재단법인의 정관변경은 주무관청의 허가를 얻지 않아도 그 효력이 있다.","o":"주무관청의 허가가 필요하다.","src":"민법 제45조 | 기출 2026-12"},{"x":"재단법인의 기본재산을 새로이 편입하는 경우에는 정관변경을 필요로 하지 않는다.","o":"정관변경에 해당하여 주무관청 허가가 필요하다.","src":"기출 2025-9 | 기출 2026-12"},{"x":"정관의 임의적 기재사항은 정관에 기재되더라도 정관의 변경 절차 없이 변경할 수 있다.","o":"정관변경 절차에 따라야 한다.","src":"기출 2026-12"},{"x":"총유물에 관한 보존행위는 특별한 사정이 없는 한 법인 아닌 사단의 사원 각자가 할 수 있다(2024-10 ㄱ).","o":"사원 각자가 단독으로 할 수 없다.","src":"기출 2023-11 | 기출 2024-10"},{"x":"민법은 법인 아닌 재단의 재산 소유를 단독소유로 규정하고 있으므로, 법인 아닌 재단 자체의 명의로 부동산등기를 할 수 있다(2024-10 ㄹ).","o":"민법이 단독소유로 규정한 것이 아니다. 그 근거가 틀린 문장이다.","src":"기출 2024-10"},{"x":"비법인 사단의 채권자가 채권자대위권에 기하여 총유재산에 대한 권리를 대위행사하는 경우에도 사원총회의 결의 등 내부적 의사결정을 거쳐야 한다(2025-10 ㄷ).","o":"채권자대위권 행사에는 내부 의사결정이 필요하지 않다.","src":"기출 2025-10 | 보충(추정)"}]},"물건":{"묶음":[{"머리":"물건의 정의와 권리의 객체","줄":[{"t":"물건: 유체물 및 전기 기타 관리할 수 있는 자연력을 말한다. 자연력은 배타적 지배를 할 수 있는 등 관리할 수 있어야 물건이다.","src":"민법 제98조 | 기출 2022-10 | 기출 2024-12"},{"t":"권리의 객체는 물건에 한정되지 않는다. 사람은 재산권의 객체가 될 수 없으나 사람의 일정한 행위는 재산권(채권)의 객체가 될 수 있다.","src":"기출 2024-12"},{"t":"사람의 유체ㆍ유골은 매장ㆍ관리ㆍ제사ㆍ공양의 대상이 되는 유체물이며, 분묘에 안치된 선조의 유체ㆍ유골은 제사주재자에게 승계된다.","src":"기출 2024-12"},{"t":"반려동물은 민법 규정의 해석상 물건에 해당한다.","src":"기출 2024-12"},{"t":"전기 기타 관리할 수 있는 자연력은 동산이다.","src":"민법 제98조ㆍ제99조 | 기출 2022-10"},{"t":"물건 분류 연결: 등유 - 소비물(1회 사용으로 소멸), 자동차 - 단일물(집합물 아님), 황소 - 불가분물, 유명화가의 특정 작품 - 부대체물, 아편 - 불융통물.","src":"기출 2021-3 | 보충"},{"t":"공부(公簿)상 1필로 등록된 토지는 특별한 사정이 없는 한 현실의 경계에 관계없이 지적공부상의 경계에 의해 소유권의 범위가 확정된다.","src":"기출 2026-6"}]},{"머리":"부동산과 동산 — 토지와 정착물","줄":[{"t":"부동산: 토지 및 그 정착물. 부동산 이외의 물건은 동산이다.","src":"민법 제99조"},{"t":"건물은 토지와 별개의 독립한 부동산이다(동산이 아니다). 민법이 명문으로 규정한 것도 아니다(토지의 정착물이되 독립 부동산으로 해석).","src":"민법 제99조 | 기출 2024-11"},{"t":"건물의 개수는 공부상의 등록이 아니라 사회통념에 따라 소유자의 의사 등 제반 사정을 참작하여 결정한다.","src":"기출 2022-10 | 기출 2026-6"},{"t":"건물의 요건: 최소한의 기둥과 지붕 그리고 주벽이 이루어지면 사회통념상 독립된 부동산으로서 건물로 인정될 수 있다.","src":"기출 2023-8"},{"t":"일시사용을 위한 가설건축물은 토지의 정착물로 볼 수 없다.","src":"기출 2026-6"},{"t":"「입목에 관한 법률」상 입목(소유권보존등기한 수목의 집단)은 토지와 별개의 부동산으로 보며 토지와 분리하여 저당권의 목적이 될 수 있다. 별도의 공시방법을 갖추면 토지와 독립하여 거래의 객체가 될 수 있다.","src":"기출 2023-25 | 기출 2024-11 | 기출 2025-11"},{"t":"명인방법을 갖춘 수목의 집단ㆍ미분리 과실은 독립한 거래 객체가 되며 양도담보권을 설정할 수 있다.","src":"기출 2021-5 | 기출 2023-8 | 기출 2026-6"},{"t":"토지를 구성하는 토석(土石)은 특별한 경우를 제외하고는 토지와 분리하여 별도로 거래할 수 없다.","src":"기출 2022-10"},{"t":"지하의 미채굴 광물에는 토지소유권이 미치지 않는다. 지중의 지하수는 토지소유권의 범위에 포함된다.","src":"기출 2021-5 | 기출 2024-11"},{"t":"온천수는 토지와 별개의 부동산이 아니고, 온천에 관한 권리는 독립한 물권(관습상 물권)이 아니다.","src":"기출 2021-27 | 기출 2024-11 | 기출 2025-11"},{"t":"1필의 토지의 일부에도 전세권ㆍ지역권을 설정할 수 있다. 1필 토지의 일부에 대한 시효취득도 인정될 수 있다(분필 후 등기).","src":"기출 2022-10 | 기출 2025-11 | 기출 2026-27 | 보충(추정)"},{"t":"토지는 부동산이므로 동산질권의 객체가 될 수 없다.","src":"기출 2024-11"},{"t":"특정할 수 있는 집합물(집합동산) 전체를 하나의 재산권으로 하는 양도담보권을 설정할 수 있다(일물일권주의의 예외).","src":"기출 2022-10 | 기출 2023-8 | 기출 2021-27"},{"t":"구분건물이 물리적으로 완성되기 전이라도 건축허가 신청 등으로 장래 신축되는 건물을 구분건물로 하겠다는 구분의사가 객관적으로 표시되면 구분행위의 존재를 인정할 수 있다.","src":"기출 2025-11"}]},{"머리":"주물과 종물","줄":[{"t":"종물의 요건: 물건의 소유자가 그 물건의 상용에 공하기 위하여 자기 소유인 다른 물건을 부속하게 한 것. 종물은 주물의 처분에 따른다.","src":"민법 제100조 | 기출 2022-11"},{"t":"주물 소유자의 사용에 공여되더라도 주물 자체의 효용과 관계없는 물건은 종물이 아니다.","src":"기출 2022-11 | 기출 2026-7"},{"t":"종물인 예: 주유소 건물의 주유기. 부동산도 종물이 될 수 있다. 저당목적 토지 위의 건물은 종물이 아니라 독립 부동산이다.","src":"기출 2022-11 | 기출 2023-7"},{"t":"특약으로 종물을 제외하거나 종물만 별도로 처분할 수 있다(제100조 제2항은 임의규정).","src":"기출 2023-7 | 기출 2026-7"},{"t":"주물에 저당권이 설정된 경우 저당권의 효력은 설정 후의 종물에도 미친다.","src":"기출 2023-7 | 기출 2026-7"},{"t":"주물을 점유취득시효로 취득해도 그 효력은 종물에 당연히 미치지 않는다(종물을 점유하지 않았다면 종물에는 효력이 없음).","src":"기출 2023-7 | 보충(추정)"},{"t":"종물 법리는 물건뿐 아니라 권리 상호간(예: 건물 소유를 위한 지상권)에도 유추적용된다.","src":"기출 2026-7 | 기출 2025-32"},{"t":"원본채권이 양도된 경우 이미 변제기에 도달한 이자채권은 별도의 의사표시가 없는 한 당연히 함께 양도되지는 않는다.","src":"기출 2026-7"}]},{"머리":"과실","줄":[{"t":"천연과실: 물건의 용법에 의하여 수취하는 산출물. 원물로부터 분리하는 때 수취할 권리자에게 속한다.","src":"민법 제101조 제1항 | 민법 제102조 제1항 | 기출 2022-11 | 기출 2023-8"},{"t":"법정과실: 물건의 사용대가로 받는 금전 기타의 물건(차임, 이자 등). 수취할 권리의 존속기간 일수의 비율로 취득한다.","src":"민법 제101조 제2항 | 민법 제102조 제2항 | 기출 2022-11"},{"t":"건물을 사용함으로써 얻는 이득은 그 건물의 과실에 준하는 것으로 본다.","src":"기출 2022-11"},{"t":"국립공원의 입장료는 토지의 사용대가가 아니므로 법정과실이 아니다.","src":"기출 2026-6"}]}],"함정":[{"x":"건물의 개수는 공부상의 등록에 의해서만 결정된다.","o":"사회통념에 따라 소유자의 의사 등 제반 사정을 참작하여 결정한다.","src":"기출 2022-10 | 기출 2026-6"},{"x":"저당목적 토지 위의 건물은 특별한 사정이 없는 한 그 토지의 종물이다.","o":"건물은 토지와 별개의 독립한 부동산이므로 종물이 아니다.","src":"기출 2022-11"},{"x":"1필의 토지의 일부에 대하여 분필절차 없이도 독립하여 시효로 그 소유권을 취득할 수 있다.","o":"출제 오답(바른 수치 미확인). 일부 시효취득은 인정되나 분필절차를 거쳐 등기하는 것으로 이해한다.","src":"기출 2023-8 | 보충(추정)"},{"x":"건물은 토지와 별개의 독립한 동산이며, 이는 민법이 명문으로 규정하고 있다.","o":"건물은 독립한 부동산이다.","src":"민법 제99조 | 기출 2024-11"},{"x":"토지에 식재된 「입목에 관한 법률」상의 입목은 토지와 별개의 동산이다.","o":"입목은 부동산으로 보며 토지와 분리하여 저당권의 목적이 된다.","src":"기출 2024-11"},{"x":"지하수의 일종인 온천수는 토지와 별개의 부동산이다.","o":"토지소유권의 범위에 포함된다. 온천에 관한 권리는 독립한 물권이 아니다.","src":"기출 2024-11"},{"x":"토지는 질권의 객체가 될 수 있다.","o":"질권은 동산ㆍ재산권을 객체로 한다. 토지는 질권의 객체가 아니다.","src":"기출 2024-11"},{"x":"권리의 객체는 물건에 한정된다.","o":"사람의 일정한 행위(채권의 객체) 등도 객체가 된다.","src":"기출 2024-12"},{"x":"1필의 토지의 일부에 대해서는 지역권을 설정할 수 없다.","o":"1필 토지의 일부에도 지역권ㆍ전세권을 설정할 수 있다.","src":"기출 2025-11"},{"x":"「입목에 관한 법률」에 의해 소유권보존등기를 한 수목의 집단이더라도 토지와 분리하여 저당권의 목적이 될 수 없다.","o":"토지와 분리하여 저당권의 목적이 될 수 있다.","src":"기출 2025-11"},{"x":"온천에 관한 권리는 관습상의 물권에 해당한다.","o":"독립한 물권이 아니다.","src":"기출 2025-11"},{"x":"등기부상 1동의 건물로 등기되어 있는 것의 일부에 대하여는 구분등기를 하지 않으면 전세권을 설정할 수 없다.","o":"건물의 일부에 구분등기 없이도 전세권을 설정할 수 있다.","src":"기출 2025-11 | 보충(추정)"},{"x":"국립공원의 입장료는 토지의 사용대가로서 법정과실에 해당한다.","o":"법정과실이 아니다.","src":"기출 2026-6"},{"x":"명인방법을 갖춘 수목의 집단에 대하여는 양도담보권을 설정할 수 없다.","o":"양도담보권을 설정할 수 있다.","src":"기출 2026-6"},{"x":"일시사용을 위한 가설건축물은 일반적으로 토지의 정착물로 볼 수 있다.","o":"정착물이 아니다.","src":"기출 2026-6"},{"x":"건물의 개수는 공부상의 등록에 의해 결정되고, 소유자의 주관적 사정을 참작하여 결정되는 것은 아니다.","o":"사회통념에 따라 소유자의 의사 등을 참작하여 결정한다.","src":"기출 2026-6"},{"x":"주물 자체의 효용과 직접 관계가 없는 물건이라도 주물 소유자의 사용에 공여되면 종물이다.","o":"주물 자체의 효용과 관계없는 물건은 종물이 아니다.","src":"기출 2026-7"},{"x":"주물ㆍ종물에 관한 민법상 법리는 물건 상호간에만 적용되고 권리 상호간에는 유추적용되지 않는다.","o":"권리 상호간에도 유추적용된다.","src":"기출 2026-7"},{"x":"당사자의 특약으로 종물만을 별도로 처분할 수는 없다.","o":"특약으로 종물만 별도로 처분할 수 있다.","src":"기출 2026-7"},{"x":"주물에 설정된 저당권의 효력은 원칙적으로 종물에 미치지 않는다.","o":"원칙적으로 종물에 미친다.","src":"기출 2023-7 | 기출 2026-7"},{"x":"점유에 의하여 주물을 시효취득하면 종물을 점유하지 않아도 그 효력이 종물에 미친다(2023-7 정답 4가 옳지 않은 설명).","o":"주물의 시효취득 효력이 종물에 당연히 미치지는 않는다.","src":"기출 2023-7 | 보충(추정)"},{"x":"황소 - 가분물 (물건 분류 연결)","o":"황소는 불가분물이다.","src":"기출 2021-3 | 보충"},{"x":"자동차 - 집합물 (물건 분류 연결)","o":"자동차는 단일물이다.","src":"기출 2021-3 | 보충"},{"x":"유명화가의 특정작품 - 대체물 (물건 분류 연결)","o":"부대체물이다.","src":"기출 2021-3 | 보충"},{"x":"아편 - 융통물 (물건 분류 연결)","o":"불융통물이다.","src":"기출 2021-3 | 보충"}]},"법률행위 총론(종류ㆍ해석, 반사회질서ㆍ불공정한 법률행위)":{"묶음":[{"머리":"법률행위의 종류","줄":[{"t":"단독행위 중 상대방 없는 단독행위: 1인의 설립자에 의한 재단법인 설립행위, 유언, 소유권의 포기, 상속의 포기(상대방 없음) 등.","src":"기출 2021-14 | 기출 2022-17 | 보충"},{"t":"상대방 있는 단독행위: 법률행위(계약)의 취소(사기에 의한 매매계약 취소 포함), 한정후견인의 동의, 계약의 해지ㆍ해제, 공유지분의 포기, 법인 이사의 사임, 채무면제, 상계.","src":"기출 2021-14 | 기출 2022-17 | 기출 2026-17 | 보충"},{"t":"1인 설립자에 의한 재단법인 설립행위는 상대방 없는 단독행위다. 유언도 상대방 없는 단독행위다.","src":"기출 2021-14 | 기출 2022-17"},{"t":"준법률행위(의사표시 아닌 법률요건): 기한의 정함이 없는 채무에 대한 이행의 최고, 시효중단을 위한 채무의 승인, 채권양도의 통지(관념의 통지), 무주물의 선점, 유실물의 습득.","src":"기출 2021-13"},{"t":"채무의 승인은 의사표시가 아니라 관념의 통지다. 묵시적 승인도 관념의 통지에 해당한다.","src":"기출 2024-24 | 기출 2021-13"},{"t":"준물권행위: 물권 이외의 권리(채권 등)를 직접 변동시키는 처분행위. 채권양도가 대표적이다.","src":"기출 2025-12 | 보충"},{"t":"처분행위: 현존하는 권리의 변동을 직접 일으키는 법률행위. 채권양도, 채무면제, 취소권의 행사, 지상권의 설정이 처분행위이고, 매매계약은 채권행위로서 처분행위가 아니다.","src":"기출 2026-13"},{"t":"법률행위의 일반원칙: 법률행위의 당사자가 법령 중 선량한 풍속 기타 사회질서에 관계없는 규정(임의규정)과 다른 의사를 표시한 때에는 그 의사에 의한다.","src":"민법 제105조"}]},{"머리":"법률행위의 해석","줄":[{"t":"자연적 해석: 표의자의 실제 의사를 밝히는 해석. 쌍방 당사자가 X토지를 계약목적물로 삼았으나 계약서에 착오로 Y토지를 기재했다면 X토지에 관하여 계약이 성립한다(오표시 무해의 원칙).","src":"기출 2021-16 | 기출 2025-15"},{"t":"규범적 해석: 상대방이 이해한 바에 따른 객관적 해석. 상대방 있는 의사표시에 적용된다. 유언 같은 상대방 없는 의사표시는 자연적 해석이 우선한다.","src":"기출 2021-16 | 보충"},{"t":"보충적 해석: 법률행위의 성립이 인정되는 경우에만 가능하다(의사표시의 흠결 보충).","src":"기출 2021-16"},{"t":"처분문서가 존재해도 그 기재내용과 다른 묵시적 약정이 인정되면 기재내용을 달리 인정할 수 있다.","src":"기출 2021-16"},{"t":"사실인 관습은 법률행위 당사자의 의사를 보충하는 효력이 있을 뿐이며 법칙으로서의 효력이 없다.","src":"기출 2021-16 | 민법 제106조"}]},{"머리":"반사회질서의 법률행위(제103조)","줄":[{"t":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다.","src":"민법 제103조"},{"t":"반사회질서에 해당하는 예: 변호사 아닌 자가 승소를 조건으로 소송당사자로부터 소송목적물 일부를 양도받기로 한 약정.","src":"기출 2021-15 | 기출 2023-14"},{"t":"반사회질서에 해당하는 예: 보험계약자가 다수의 보험계약을 통해 보험금을 부정취득할 목적으로 체결한 보험계약, 오로지 보험사고를 가장하여 보험금을 취득할 목적으로 체결한 생명보험계약.","src":"기출 2023-14 | 기출 2024-13"},{"t":"반사회질서에 해당하는 예: 이미 매도된 부동산임을 알면서 매도인의 배임행위에 적극 가담하여 체결한 저당권설정계약(이중매매). 제2매수인이 선의여도 등기는 무효이나 선의 제3자 보호 규정이 없어 절대적 무효다.","src":"기출 2021-21 | 기출 2025-13"},{"t":"반사회질서에 해당하는 예: 증인이 사실을 증언하는 조건으로 통상 용인될 수 있는 수준을 넘는 대가를 지급받기로 한 약정.","src":"기출 2023-14"},{"t":"반사회질서에 해당하는 예: 형사사건에서 변호사가 성공보수금을 약정한 경우(2023-14 선지 1은 반사회질서에 해당하는 보기).","src":"기출 2023-14"},{"t":"반사회질서에 해당하지 않는 예: 양도소득세 회피 목적의 명의신탁약정, 양도소득세 회피 및 투기 목적의 미등기 전매, 양도소득세 일부를 회피할 목적으로 계약서에 실제보다 낮은 금액을 대금으로 기재한 매매계약(다운계약서).","src":"기출 2021-15 | 기출 2023-14 | 기출 2024-13"},{"t":"반사회질서에 해당하지 않는 예: 강제집행을 면할 목적의 허위 근저당권설정(통정허위표시로 무효), 산모가 태아의 상해에 대비하여 체결한 상해보험계약, 도박채무 변제를 위한 대리권 수여행위.","src":"기출 2021-15 | 기출 2025-13 | 기출 2026-16"},{"t":"전통사찰의 주지직을 거액의 금품을 대가로 양도ㆍ양수하는 약정을 알고도 묵인ㆍ방조한 상태에서 한 종교법인의 주지임명행위는 반사회질서가 아니다.","src":"기출 2021-15 | 기출 2024-13"},{"t":"채무자의 허위 저당권설정행위(통정허위표시)는 채권자취소권의 대상이 될 수 있고, 반사회질서의 법률행위로 볼 수 없다.","src":"기출 2026-16 | 기출 2021-17"}]},{"머리":"불공정한 법률행위(제104조)","줄":[{"t":"요건: 당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다.","src":"민법 제104조"},{"t":"급부와 반대급부 사이의 현저한 불균형은 객관적 가치를 기준으로 판단한다(당사자의 주관적 가치 아님).","src":"기출 2022-19"},{"t":"급부와 반대급부가 현저히 균형을 잃었다고 하여 궁박ㆍ경솔ㆍ무경험이 추정되는 것은 아니다.","src":"기출 2024-15 | 기출 2026-14"},{"t":"궁박ㆍ경솔ㆍ무경험은 법률행위 당시를 기준으로 판단한다.","src":"기출 2023-15 | 기출 2026-14"},{"t":"궁박에는 경제적 원인뿐 아니라 정신적ㆍ심리적 원인에 의한 것도 포함될 수 있다.","src":"기출 2022-19"},{"t":"대리인에 의한 법률행위의 경우 경솔과 무경험은 대리인을 기준으로 판단한다(궁박은 본인 기준).","src":"기출 2022-19 | 기출 2024-15 | 기출 2026-14 | 보충(추정)"},{"t":"무상증여 등 무상계약에는 제104조가 적용되지 않는다. 대가관계를 상정할 수 있는 한 단독행위에도 적용될 수 있다.","src":"기출 2022-19 | 기출 2023-15"},{"t":"경매절차(공경매)에서는 매각대금이 시가에 비해 현저히 저렴해도 제104조가 적용되지 않는다.","src":"기출 2023-15 | 기출 2024-15"},{"t":"불공정한 법률행위는 추인에 의해서도 유효로 될 수 없다. 법정추인 법리도 적용되지 않는다. 무효행위의 전환(제138조)은 적용될 수 있다.","src":"민법 제138조 | 기출 2022-19 | 기출 2023-15 | 기출 2025-20 | 기출 2026-14"}]}],"함정":[{"x":"사실인 관습은 법률행위 당사자의 의사를 보충할 뿐만 아니라 법칙으로서의 효력을 갖는다.","o":"의사를 보충하는 효력만 있고 법칙으로서의 효력은 없다.","src":"기출 2021-16"},{"x":"유언의 경우 우선적으로 규범적 해석이 이루어져야 한다.","o":"상대방 없는 단독행위인 유언은 자연적 해석이 우선한다.","src":"기출 2021-16 | 보충"},{"x":"처분문서가 존재한다면 처분문서의 기재내용과 다른 묵시적 약정이 있는 사실이 인정되더라도 그 기재내용을 달리 인정할 수는 없다.","o":"묵시적 약정이 인정되면 기재내용을 달리 인정할 수 있다.","src":"기출 2021-16"},{"x":"계약당사자 쌍방이 X토지를 계약목적물로 삼았으나, 계약서에는 착오로 Y토지를 기재하였다면, Y토지에 관하여 계약이 성립한 것이다.","o":"X토지에 관하여 계약이 성립한다(자연적 해석).","src":"기출 2021-16 | 기출 2025-15"},{"x":"급부와 반대급부 사이의 ‘현저한 불균형’ 여부의 판단은 당사자의 주관적 가치에 의해야 한다.","o":"객관적 가치에 의한다.","src":"기출 2022-19"},{"x":"경매절차에서 경매부동산의 매각대금이 시가에 비해 현저히 저렴한 경우에는 제104조가 적용될 수 있다.","o":"공경매에는 제104조가 적용되지 않는다.","src":"기출 2023-15 | 기출 2024-15"},{"x":"급부와 반대급부가 현저히 균형을 잃은 법률행위는 궁박, 경솔 또는 무경험으로 인해 이루어진 것으로 추정된다.","o":"추정되지 않는다.","src":"기출 2024-15 | 기출 2026-14"},{"x":"대물변제예약의 경우, 대차의 목적물가격과 대물변제의 목적물가격이 불균형한지 여부는 원칙적으로 대물변제 예약 당시를 표준으로 결정한다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2024-15"},{"x":"불공정한 법률행위에는 법정추인에 관한 법리가 적용될 수 있다.","o":"적용되지 않는다(추인으로도 유효로 될 수 없다). 무효행위의 전환 법리는 적용될 수 있다.","src":"기출 2026-14"},{"x":"공경매에 있어서도 불공정한 법률행위에 관한 민법 제104조가 적용된다.","o":"적용되지 않는다.","src":"기출 2024-15"},{"x":"양도세 회피를 목적으로 한 부동산에 관한 명의신탁약정은 반사회질서의 법률행위다.","o":"그 사유만으로 반사회질서 법률행위가 되지 않는다.","src":"기출 2021-15 | 기출 2023-14 | 기출 2024-13"},{"x":"강제집행을 면할 목적으로 부동산에 허위의 근저당권설정등기를 경료하는 행위는 반사회질서의 법률행위다.","o":"통정허위표시로 무효일 뿐 반사회질서가 아니다.","src":"기출 2021-15 | 기출 2025-13"},{"x":"도박채무의 변제를 위하여 채무자가 부동산 처분에 관하여 도박채권자에게 대리권을 수여한 행위는 반사회질서의 법률행위다.","o":"반사회질서의 법률행위에 해당하지 않는다.","src":"기출 2021-15"},{"x":"상대방 없는 단독행위로 공유지분의 포기ㆍ이사의 사임ㆍ계약의 해지가 해당한다.","o":"공유지분의 포기, 이사의 사임, 계약의 해지는 상대방 있는 단독행위다. 1인 설립자의 재단법인 설립행위만 상대방 없는 단독행위다.","src":"기출 2022-17 | 보충"},{"x":"매매계약은 현존하는 권리의 변동을 직접 일으키는 처분행위다.","o":"매매계약은 채권행위로 처분행위가 아니다.","src":"기출 2026-13"},{"x":"부담부증여는 준물권행위다.","o":"채권양도가 준물권행위다. 부담부증여는 채권행위다.","src":"기출 2025-12"}]},"의사표시(비진의표시ㆍ통정허위표시ㆍ착오ㆍ사기강박)":{"묶음":[{"머리":"진의 아닌 의사표시(비진의표시, 제107조)","줄":[{"t":"원칙: 의사표시는 표의자가 진의 아님을 알고 한 것이라도 효력이 있다.","src":"민법 제107조 제1항"},{"t":"예외: 상대방이 표의자의 진의 아님을 알았거나 알 수 있었을 경우에는 무효다. 무효는 선의의 제3자에게 대항하지 못한다.","src":"민법 제107조 | 기출 2025-20"},{"t":"무효를 주장하는 자가 상대방의 악의 또는 과실을 증명할 책임을 진다.","src":"기출 2021-17"},{"t":"대리권 남용의 경우에도 특별한 사정이 없는 한 진의 아닌 의사표시 규정이 유추적용될 수 있다. 대리인에 의한 법률행위에서 진의 여부는 대리인을 기준으로 판단한다.","src":"기출 2026-15 | 민법 제116조"},{"t":"진의 아닌 의사표시 규정은 상대방 있는 단독행위에도 적용된다.","src":"기출 2026-15"},{"t":"강박에 의하여 증여를 한 경우는 진의 아닌 의사표시가 아니다(증여의 의사가 있고 강박은 취소 사유).","src":"기출 2026-15"}]},{"머리":"통정허위표시(제108조)","줄":[{"t":"상대방과 통정한 허위의 의사표시는 무효다. 무효는 선의의 제3자에게 대항하지 못한다.","src":"민법 제108조"},{"t":"제3자: 선의이기만 하면 되고 과실이 있어도 보호된다(무과실 불요). 선의는 추정된다.","src":"민법 제108조 제2항 | 기출 2021-17 | 보충"},{"t":"허위표시 제3자에 해당하는 자: 허위 전세권에 저당권을 취득한 자, 가장매매 매수인으로부터 매매예약에 기한 가등기권을 취득한 자, 가장 근저당의 피담보채권을 가압류한 자, 가장 임대차보증금반환채권 양수인의 채권자로서 압류ㆍ추심명령을 받은 자, 가장채권 보유자의 파산관재인, 가장 전세권 설정계약에 의한 전세금반환채권을 가압류한 채권자, 허위 저당권 실행으로 소유권을 취득한 경락인.","src":"기출 2023-16 | 기출 2024-18 | 기출 2025-14 | 기출 2026-16"},{"t":"제3자가 아닌 자: 채권의 가장양수인으로부터 추심을 위하여 채권을 양수한 자(추심 목적 양수인), 가장소비대차에서 대주의 계약상 지위를 이전받은 자(기출 정답상 제3자 아님으로 처리).","src":"기출 2023-16 | 기출 2024-18"},{"t":"파산채무자의 가장채권에 관한 파산관재인은 제108조 제2항의 제3자에 해당한다.","src":"기출 2024-18 | 기출 2025-14"},{"t":"제3자가 악의이더라도 전득자가 선의이면 그 전득자에 대하여 통정허위표시의 무효를 주장할 수 없다.","src":"기출 2025-14"},{"t":"가장행위 아래 숨은 행위는 그 자체의 유효 요건을 갖추면 유효하다. 증여를 매매로 가장한 경우 내면적으로 의욕한 증여계약은 유효하다.","src":"기출 2025-14 | 보충"},{"t":"허위표시로 무효인 법률행위에 따른 법률효과를 침해하는 것처럼 보이는 채무불이행이 있어도 손해배상을 청구할 수 없다.","src":"기출 2025-14 | 기출 2026-20"},{"t":"허위표시에 의한 가장행위라도 사해행위 요건을 갖추면 채권자취소권의 대상이 된다.","src":"기출 2021-17 | 기출 2025-14 | 기출 2026-16"}]},{"머리":"착오로 인한 의사표시(제109조)","줄":[{"t":"요건: 법률행위 내용의 중요부분에 착오가 있을 때 취소할 수 있다. 그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다. 취소는 선의의 제3자에게 대항하지 못한다.","src":"민법 제109조"},{"t":"제109조 제1항은 임의규정이므로 당사자의 합의로 적용을 배제할 수 있다(강행규정 아님).","src":"기출 2021-19 | 기출 2022-21"},{"t":"중요부분의 착오는 착오로 표의자가 경제적 불이익을 입은 경우에 한한다. 경제적 불이익이 없거나 사후 사정변경으로 소멸하였다면 중요부분의 착오가 아니다.","src":"기출 2021-19 | 기출 2023-17 | 기출 2024-19"},{"t":"부동산 매매에서 시가에 관한 착오는 원칙적으로 법률행위 내용의 중요부분의 착오가 아니다.","src":"기출 2021-19 | 기출 2022-21 | 기출 2024-19"},{"t":"표의자에게 착오가 있었다는 사실 및 착오가 의사표시에 결정적 영향을 미쳤다는 점은 취소를 주장하는 표의자가 증명한다.","src":"기출 2021-19"},{"t":"표의자의 중대한 과실 증명책임은 취소를 저지하려는 상대방에게 있다.","src":"기출 2023-17 | 기출 2024-19"},{"t":"상대방이 표의자의 착오를 알고 이용한 경우에는 표의자에게 중대한 과실이 있어도 취소할 수 있다.","src":"기출 2022-21 | 기출 2023-17 | 기출 2025-16"},{"t":"동기의 착오: 동기가 표시되지 않았더라도 상대방에 의하여 유발된 동기의 착오는 취소할 수 있다(표시 요건 불요). 동기를 의사표시 내용으로 삼기로 하는 별도의 합의까지 필요한 것은 아니다.","src":"기출 2021-17 | 기출 2024-19 | 기출 2025-16"},{"t":"타인의 기망으로 동기의 착오가 발생한 경우 사기와 착오의 경합이 인정될 수 있다.","src":"기출 2023-18"},{"t":"매도인이 매매계약을 적법하게 해제한 후에도 매수인은 해제의 불이익을 면하기 위해 착오를 이유로 계약을 취소할 수 있다.","src":"기출 2021-18 | 기출 2022-21 | 기출 2023-17 | 기출 2024-19 | 기출 2025-16"},{"t":"하자담보책임이 성립하더라도 중요부분 착오가 있고 중과실이 없는 매수인은 착오를 이유로 계약을 취소할 수 있다(경합).","src":"기출 2022-21 | 기출 2025-16"},{"t":"물상보증인이 근저당권설정계약을 체결하는 경우 채무자의 동일성에 관한 착오는 중요부분의 착오다.","src":"기출 2025-16"},{"t":"출연재산이 재단법인의 기본재산인지 여부는 착오에 의한 출연행위의 취소에 영향을 주지 않는다.","src":"기출 2023-17"}]},{"머리":"사기ㆍ강박에 의한 의사표시(제110조)","줄":[{"t":"사기나 강박에 의한 의사표시는 취소할 수 있다.","src":"민법 제110조 제1항"},{"t":"제3자의 사기ㆍ강박: 상대방 있는 의사표시에 관하여 제3자가 사기나 강박을 행한 경우 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 취소할 수 있다.","src":"민법 제110조 제2항"},{"t":"사기ㆍ강박 취소는 선의의 제3자에게 대항하지 못한다. 사기를 이유로 취소를 주장하는 자 쪽에서 제3자의 악의를 증명한다(제3자는 선의로 추정).","src":"민법 제110조 제3항 | 기출 2024-20 | 보충(추정)"},{"t":"상대방과 동일시할 수 있는 자(예: 매수인의 대리인)의 사기는 제3자의 사기가 아니다. 상대방의 단순한 피용자는 제3자에 해당한다.","src":"기출 2022-18 | 기출 2023-18 | 기출 2024-20"},{"t":"매수인의 대리인이 매도인을 기망한 경우 매수인이 알 수 없었더라도 매도인은 사기를 이유로 취소할 수 있다.","src":"기출 2024-20"},{"t":"고지의무가 없다면 침묵 등 부작위는 기망행위가 아니다. 목적물의 시가를 묵비하여 알리지 않은 것은 특별한 사정이 없는 한 기망이 아니다.","src":"기출 2021-17 | 기출 2022-18 | 기출 2023-18 | 기출 2024-20 | 기출 2026-17"},{"t":"기망행위가 불법행위를 구성하면 사기 취소 없이도 불법행위 손해배상을 청구할 수 있다. 제3자의 사기도 같다. 취소로 인한 부당이득반환청구권과 손해배상청구권은 경합한다.","src":"기출 2022-18 | 기출 2023-18 | 기출 2026-17"},{"t":"사기에 기한 취소권과 매도인의 하자담보책임이 경합하는 경우 기망당한 매수인은 사기를 이유로 취소할 수 있다.","src":"기출 2024-20"},{"t":"강박에 의하여 의사결정의 자유가 완전히 박탈된 상태에서 이루어진 의사표시는 무효다(취소 아님).","src":"기출 2022-18 | 기출 2024-20 | 기출 2026-17"},{"t":"강박이 되려면 해악의 고지가 있어야 한다. 해악의 고지 없이 단지 각서에 서명ㆍ날인할 것을 강력히 요구한 것만으로는 강박이 아니다.","src":"기출 2022-18 | 기출 2026-17"},{"t":"사기에 의한 매매계약의 취소는 상대방 있는 단독행위다.","src":"기출 2026-17"}]},{"머리":"의사표시의 효력발생(제111조~제113조)","줄":[{"t":"상대방 있는 의사표시는 상대방에게 도달한 때에 효력이 생긴다(도달주의).","src":"민법 제111조 제1항 | 기출 2025-17"},{"t":"발송 후 도달 전에 표의자가 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향이 없다.","src":"민법 제111조 제2항 | 기출 2023-19 | 기출 2025-17 | 기출 2026-21"},{"t":"도달은 상대방이 요지할 수 있는 상태(사회통념상 알 수 있는 객관적 상태)에 놓인 것으로 충분하다. 상대방이 내용을 알아야 하는 것이 아니다.","src":"기출 2025-17 | 보충"},{"t":"도달 후에는 상대방이 알기 전이라도 철회할 수 없다. 내용증명 우편물이 발송되고 반송되지 않았다면 특별한 사정이 없는 한 그 무렵 송달된 것으로 본다. 보통우편은 반송되지 않았다는 사정만으로 도달이 추정되지 않는다.","src":"기출 2023-19 | 기출 2026-21 | 보충(추정)"},{"t":"제한능력자에 대한 의사표시: 상대방이 의사표시를 받은 때 제한능력자이면 의사표시자는 의사표시로써 대항할 수 없다. 그 상대방의 법정대리인이 도달 사실을 안 후에는 그러하지 아니하다.","src":"민법 제112조 | 기출 2025-17"},{"t":"공시송달: 표의자가 과실 없이 상대방 또는 그 소재를 알지 못하는 경우 민사소송법 공시송달 규정에 의하여 송달할 수 있다.","src":"민법 제113조 | 기출 2025-17 | 기출 2026-21"}]}],"함정":[{"x":"허위표시의 당사자는 선의의 제3자에게 과실이 있다면 의사표시의 무효를 그 제3자에게 주장할 수 있다.","o":"선의이면 과실이 있어도 대항하지 못한다.","src":"민법 제108조 제2항 | 기출 2021-17"},{"x":"착오로 인한 의사표시의 취소에 관한 민법 제109조 제1항은 강행규정이므로 그 적용을 배제하는 甲과 乙의 약정은 무효이다.","o":"임의규정이므로 배제 약정은 유효하다.","src":"기출 2021-19 | 기출 2022-21"},{"x":"X토지의 시가에 대한 착오는 특별한 사정이 없는 한 법률행위의 중요부분에 대한 착오에 해당한다.","o":"원칙적으로 중요부분의 착오가 아니다.","src":"기출 2021-19 | 기출 2024-19"},{"x":"착오로 인한 甲의 불이익이 사후에 사정변경으로 소멸되었더라도 甲은 착오를 이유로 매매계약을 취소할 수 있다.","o":"경제적 불이익이 소멸되었다면 취소할 수 없다.","src":"기출 2021-19"},{"x":"어떤 해악의 고지가 없이 단지 각서에 서명ㆍ날인할 것을 강력히 요구한 것만으로도 강박에 해당한다.","o":"해악의 고지가 없으면 강박이 아니다.","src":"기출 2022-18 | 기출 2026-17"},{"x":"물건의 하자로 매도인의 하자담보책임이 성립하는 경우, 매수인은 매매계약 내용의 중요부분에 착오가 있더라도 그 계약을 취소할 수 없다.","o":"하자담보책임과 상관없이 착오 취소가 가능하다.","src":"기출 2022-21"},{"x":"매도인이 매매계약을 적법하게 해제한 경우, 매수인은 착오를 이유로 그 계약을 취소할 수 없다.","o":"해제 후에도 착오를 이유로 취소할 수 있다.","src":"기출 2023-17 | 기출 2024-19"},{"x":"상대방의 피용자는 제3자에 의한 사기에 관한 민법 제110조 제2항에서 정한 제3자에 해당하지 않는다.","o":"단순 피용자는 제3자에 해당한다. 상대방과 동일시할 수 있는 자는 제3자가 아니다.","src":"기출 2023-18"},{"x":"격지자 간의 계약은 승낙의 통지가 도달한 때 성립한다.","o":"승낙의 통지를 발송한 때 성립한다(제531조 발신주의).","src":"기출 2023-19 | 기출 2021-34 | 민법 제531조(원문 미확인)"},{"x":"사원총회의 소집은 특별한 사정이 없는 한 1주간 전에 그 통지가 도달하여야 한다.","o":"1주간 전에 통지를 발하면 된다.","src":"민법 제71조 | 기출 2023-19"},{"x":"의사표시를 보통우편으로 발송한 경우, 그 우편이 반송되지 않는 한 의사표시는 도달된 것으로 추정된다.","o":"보통우편은 반송되지 않았다는 사정만으로 도달이 추정되지 않는다(내용증명은 달리 본다).","src":"기출 2023-19 | 기출 2026-21 | 보충(추정)"},{"x":"의사표시가 상대방에게 도달한 후에도 상대방이 이를 알기 전이라면 특별한 사정이 없는 한 그 의사표시를 철회할 수 있다.","o":"도달 후에는 철회할 수 없다.","src":"민법 제111조 | 기출 2023-19"},{"x":"甲이 乙에 의하여 유발된 동기의 착오로 매매계약을 체결한 경우, 甲은 체결 당시 그 동기를 표시한 경우에 한하여 그 계약을 취소할 수 있다.","o":"상대방이 유발한 동기 착오는 동기를 표시하지 않았어도 취소할 수 있다.","src":"기출 2024-19"},{"x":"법률행위 내용의 중요부분의 착오가 되기 위해서는 특별한 사정이 없는 한 착오에 빠진 甲이 그로 인하여 경제적 불이익을 입어야 하는 것이 아니다.","o":"경제적 불이익을 입어야 한다.","src":"기출 2023-17 | 기출 2024-19"},{"x":"乙이 甲의 중도금 지급채무 불이행을 이유로 매매계약을 적법하게 해제한 경우, 甲은 그 계약내용에 착오가 있었더라도 이를 이유로 취소권을 행사할 여지가 없다.","o":"해제 후에도 착오 취소권을 행사할 수 있다.","src":"기출 2024-19"},{"x":"양수인의 사기로 의사표시를 한 부동산의 양도인이 제3자에 대하여 사기에 의한 의사표시의 취소를 주장하는 경우, 제3자는 특별한 사정이 없는 한 자신의 선의를 증명해야 한다.","o":"제3자는 선의로 추정되므로 취소를 주장하는 쪽이 제3자의 악의를 증명한다.","src":"기출 2024-20 | 보충(추정)"},{"x":"파산채무자가 상대방과 통정허위표시를 통하여 가장채권을 보유하고 있다가 파산이 선고된 경우, 파산관재인은 민법 제108조 제2항의 제3자에 해당하지 않는다.","o":"파산관재인은 제3자에 해당한다.","src":"기출 2025-14"},{"x":"동기의 착오가 법률행위의 내용의 중요부분의 착오에 해당함을 이유로 표의자가 법률행위를 취소하려면 당사자들 사이에 별도로 그 동기를 의사표시의 내용으로 삼기로 하는 합의가 있어야만 한다.","o":"별도의 합의까지는 필요하지 않다.","src":"기출 2025-16"},{"x":"의사표시가 상대방에게 도달한 것으로 인정되기 위해서는 상대방이 그 의사표시의 내용을 알아야 한다.","o":"요지할 수 있는 상태에 놓이면 도달이다.","src":"기출 2025-17"},{"x":"강박에 의하여 증여를 한 경우, 증여의 의사가 있더라도 그 증여는 진의 아닌 의사표시에 해당한다.","o":"진의 아닌 의사표시에 해당하지 않는다(강박은 취소 사유).","src":"기출 2026-15"},{"x":"진의 아닌 의사표시는 원칙적으로 무효이나 상대방이 표의자의 진의 아님을 알 수 있었을 때에는 유효하다.","o":"원칙적으로 유효하고, 상대방이 알았거나 알 수 있었을 때 무효다.","src":"민법 제107조 | 기출 2026-15"},{"x":"대리인에 의한 법률행위의 경우, 진의 아닌 의사표시인지는 원칙적으로 본인을 기준으로 판단하여야 한다.","o":"대리인을 기준으로 판단한다.","src":"민법 제116조 | 기출 2026-15"},{"x":"진의 아닌 의사표시에 관한 규정은 상대방 있는 단독행위에는 적용되지 않는다.","o":"적용된다.","src":"기출 2026-15"},{"x":"의사표시자가 그 통지를 발송한 후 도달 전에 사망하면 그 의사표시는 효력을 잃는다.","o":"효력에 영향을 미치지 않는다.","src":"민법 제111조 제2항 | 기출 2026-21"},{"x":"채권의 가장양수인으로부터 추심을 위하여 채권을 양수한 자는 허위표시의 제3자에 해당한다(2023-16 정답 선지).","o":"추심 목적 양수인은 제3자가 아니다.","src":"기출 2023-16"},{"x":"甲과 丙 사이의 허위 저당권설정행위는 반사회질서의 법률행위에 해당한다(2026-16 ㄱ).","o":"반사회질서의 법률행위가 아니다. 채권자취소권의 대상은 된다.","src":"기출 2026-16"}]},"대리":{"묶음":[{"머리":"대리행위의 효력과 하자","줄":[{"t":"현명(顯名): 대리인이 권한 내에서 본인을 위한 것임을 표시한 의사표시는 직접 본인에게 효력이 생긴다. 대리인에게 대한 제3자의 의사표시에도 준용한다.","src":"민법 제114조"},{"t":"본인을 위한 것임을 표시하지 않은 때: 자기를 위한 것으로 본다. 단 상대방이 대리인으로서 한 것임을 알았거나 알 수 있었을 때에는 본인에게 효력이 생긴다.","src":"민법 제115조"},{"t":"대리행위의 하자: 의사의 흠결, 사기, 강박 또는 선의ㆍ과실 여부는 대리인을 표준으로 결정한다. 특정한 법률행위를 위임한 경우 대리인이 본인의 지시에 좇아 행위한 때 본인은 자기가 안 사정이나 과실로 알지 못한 사정에 관하여 대리인의 부지를 주장하지 못한다.","src":"민법 제116조 | 기출 2026-15"},{"t":"대리인은 행위능력자임을 요하지 않는다. 미성년자ㆍ피한정후견인도 임의대리인이 될 수 있다.","src":"민법 제117조 | 기출 2022-4 | 기출 2025-5 | 기출 2025-18"},{"t":"대리권의 범위(권한을 정하지 않은 대리인): ① 보존행위 ② 대리의 목적인 물건이나 권리의 성질을 변하지 아니하는 범위에서 이용 또는 개량하는 행위.","src":"민법 제118조 | 기출 2025-18"},{"t":"수인의 대리인: 각자가 본인을 대리한다. 법률 또는 수권행위에 다른 정함이 있으면 그에 따른다.","src":"민법 제119조 | 기출 2025-18"},{"t":"자기계약ㆍ쌍방대리 금지: 본인의 허락이 없으면 자기와 법률행위를 하거나 동일한 법률행위에 당사자 쌍방을 대리하지 못한다. 단 채무의 이행은 할 수 있다.","src":"민법 제124조"},{"t":"민법상 조합의 대리는 조합원 전원의 성명을 표시할 필요가 없고 조합 이름으로 대리행위를 할 수 있다.","src":"기출 2024-14 | 보충"},{"t":"매매계약 체결 대리권을 수여받은 대리인이 대금을 수령한 경우 본인에게 전달하지 않아도 상대방의 대금지급의무는 소멸한다.","src":"기출 2024-14"},{"t":"매매계약의 체결과 이행에 관하여 포괄적 대리권을 받은 대리인은 특별한 사정이 없는 한 대금지급기일을 연기해 줄 권한도 가진다.","src":"기출 2024-14 | 기출 2026-18"},{"t":"대여금 영수권한만을 위임받은 대리인이 그 채무의 일부를 면제하려면 본인의 특별수권이 필요하다.","src":"기출 2024-14"},{"t":"매매계약을 체결할 권한을 수여받은 대리인이라도 특별한 사정이 없는 한 그 계약을 해제할 권한은 없다.","src":"기출 2022-23"},{"t":"계약체결에 관한 대리권을 수여받은 대리인이 취소권을 행사하려면 특별한 사정이 없는 한 취소권 행사에 관한 본인의 수권행위가 있어야 한다.","src":"기출 2021-18"},{"t":"채권양도의 통지는 양도인이 해야 하나, 양수인이 양도인의 대리인으로서 통지에 관한 위임을 받았다면 양수인에 의한 통지도 유효하다.","src":"기출 2023-34 | 기출 2026-18"}]},{"머리":"복대리","줄":[{"t":"임의대리인의 복임권: 본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다.","src":"민법 제120조 | 기출 2023-10 | 기출 2025-18 | 기출 2026-18"},{"t":"임의대리인의 책임: 복대리인을 선임한 때 본인에 대하여 선임감독에 관한 책임이 있다. 본인의 지명에 의해 선임한 경우에는 복대리인의 부적임 또는 불성실함을 알고도 본인에게 통지하거나 해임하기를 태만한 때에 한하여 책임이 있다.","src":"민법 제121조 | 기출 2023-10"},{"t":"법정대리인의 복임권: 자기 책임으로 복대리인을 선임할 수 있다. 부득이한 사유로 선임한 때에는 제121조 제1항의 선임감독 책임만 있다.","src":"민법 제122조"},{"t":"복대리인의 권한: 그 권한 내에서 본인(대리인이 아님)을 대리한다. 본인이나 제3자에 대하여 대리인과 동일한 권리의무가 있다.","src":"민법 제123조 | 기출 2025-18"},{"t":"복대리권의 소멸: 본인의 사망, 대리인의 사망ㆍ성년후견 개시ㆍ파산, 복대리인의 사망ㆍ성년후견 개시ㆍ파산, 대리인의 대리권 소멸. 본인의 특정후견 개시는 소멸사유가 아니다.","src":"민법 제127조 | 기출 2022-22 | 보충"}]},{"머리":"대리권의 소멸","줄":[{"t":"소멸사유(법정): ① 본인의 사망 ② 대리인의 사망, 성년후견의 개시 또는 파산.","src":"민법 제127조"},{"t":"임의대리의 종료: 위 사유 외에 수권행위의 원인된 법률관계의 종료에 의하여 소멸한다. 법률관계 종료 전 본인이 수권행위를 철회한 경우도 같다. 원인된 법률관계가 기간만료로 종료되면 그 시점에 대리권도 소멸한다.","src":"민법 제128조 | 기출 2024-14"}]},{"머리":"표현대리","줄":[{"t":"대리권수여의 표시에 의한 표현대리(제125조): 제3자에 대하여 타인에게 대리권을 수여함을 표시한 자는 그 대리권 범위 내의 행위에 대하여 책임이 있다. 제3자가 대리권 없음을 알았거나 알 수 있었을 때에는 그러하지 아니하다.","src":"민법 제125조 | 기출 2022-23"},{"t":"사회통념상 대리권을 추단할 수 있는 직함이나 명칭 등의 사용을 승낙한 경우에는 대리권 수여의 표시가 있는 것으로 볼 수 있다.","src":"기출 2023-20"},{"t":"권한을 넘은 표현대리(제126조): 대리인이 그 권한 외의 법률행위를 한 경우 제3자가 그 권한이 있다고 믿을 만한 정당한 이유가 있는 때 본인은 책임이 있다.","src":"민법 제126조 | 기출 2024-16"},{"t":"기본대리권이 될 수 있는 것: 복대리인의 권한, 등기신청의 대리권, 사실혼 부부의 일상가사대리권. 법정대리의 경우에도 권한을 넘은 표현대리 규정이 적용된다.","src":"기출 2021-20 | 기출 2022-23 | 기출 2023-20 | 기출 2024-16"},{"t":"대리권 소멸 후의 표현대리(제129조): 대리권의 소멸은 선의의 제3자에게 대항하지 못한다. 단 제3자가 과실로 그 사실을 알지 못한 때에는 그러하지 아니하다. 법정대리의 경우에도 성립하며, 대리인이 대리권 소멸 후 복대리인을 선임해 대리행위를 하게 한 경우에도 성립할 수 있다.","src":"민법 제129조 | 기출 2021-20 | 기출 2022-23"},{"t":"표현대리가 성립해도 무권대리가 유권대리로 전환되는 것이 아니다. 상대방에게 과실이 있어도 과실상계 법리를 유추적용하여 본인의 책임을 감경할 수 없다.","src":"기출 2021-20 | 기출 2023-20 | 기출 2024-16"},{"t":"대리인의 권한을 넘는 행위가 범죄를 구성하는 경우에도 권한을 넘은 표현대리의 법리가 적용될 수 있다. 대리행위 자체가 강행법규 위반으로 무효이면 표현대리가 성립하지 않는다.","src":"기출 2023-20 | 기출 2024-16 | 기출 2026-20"},{"t":"유권대리의 주장에는 표현대리의 주장이 포함되어 있지 않다(별개 주장).","src":"기출 2023-20"},{"t":"무권대리행위에 대하여 본인이 이의를 제기하지 않고 장기간 방치한 사실만으로는 추인이 있다고 볼 수 없다.","src":"기출 2021-20"}]},{"머리":"무권대리","줄":[{"t":"효력: 대리권 없는 자가 타인의 대리인으로 한 계약은 본인이 추인하지 아니하면 본인에 대하여 효력이 없다.","src":"민법 제130조"},{"t":"상대방의 최고권: 상당한 기간을 정하여 본인에게 추인 여부의 확답을 최고할 수 있다. 본인이 그 기간 내에 확답을 발하지 아니하면 추인을 거절한 것으로 본다. 최고권은 상대방의 선의ㆍ악의를 묻지 않는다.","src":"민법 제131조 | 기출 2026-19"},{"t":"추인ㆍ거절의 상대방: 상대방에 대하여 하지 아니하면 그 상대방에 대항하지 못한다. 상대방이 그 사실을 안 때에는 그러하지 아니하다.","src":"민법 제132조 | 기출 2025-19 | 기출 2026-19"},{"t":"추인의 효력: 다른 의사표시가 없으면 계약 시에 소급하여 효력이 생긴다. 제3자의 권리를 해하지 못한다.","src":"민법 제133조"},{"t":"상대방의 철회권: 본인의 추인이 있을 때까지 본인이나 그 대리인에 대하여 철회할 수 있다. 계약 당시 상대방이 대리권 없음을 안 때에는 철회할 수 없다(선의만 철회). 악의라는 사실은 철회를 다투는 본인이 증명한다.","src":"민법 제134조 | 기출 2025-19 | 기출 2026-19"},{"t":"본인이 무권대리인에게 추인한 경우 상대방이 그 사실을 알 때까지는 상대방이 철회할 수 있다.","src":"민법 제132조ㆍ제134조 | 기출 2023-21 | 기출 2025-19"},{"t":"무권대리인의 책임: 대리권을 증명하지 못하고 본인의 추인을 받지 못한 경우 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다. 상대방이 대리권 없음을 알았거나 알 수 있었을 때, 또는 무권대리인이 제한능력자일 때에는 적용하지 아니한다.","src":"민법 제135조 | 기출 2025-19"},{"t":"무권대리행위가 제3자의 위법행위로 야기된 경우에도 무권대리인의 책임은 귀책사유와 무관하게(무과실책임) 인정된다.","src":"기출 2022-23 | 기출 2023-21"},{"t":"무권대리인이 본인을 단독상속한 경우 본인의 지위에서 추인거절권을 행사하는 것은 신의칙상 허용되지 않는다.","src":"기출 2023-21 | 기출 2025-19"},{"t":"상대방이 무권대리인에게 가지는 계약의 이행 또는 손해배상청구권의 소멸시효는 상대방이 이를 선택할 수 있는 때(대리권 증명 불능ㆍ추인 거절 시)부터 진행한다.","src":"기출 2023-21"},{"t":"단독행위의 무권대리: 행위 당시 상대방이 대리권 없는 행위에 동의하거나 대리권을 다투지 아니한 때에 한하여 위 규정을 준용한다.","src":"민법 제136조"},{"t":"이중매매에서 제2매수인이 매도인의 배임행위에 적극 가담한 경우 제1매수인은 반사회질서를 이유로 제2매매의 무효를 주장할 수 있다. 제2매수인으로부터 전득한 자가 선의여도 등기는 유효해지지 않는다(절대적 무효).","src":"기출 2021-21 | 기출 2025-13"}]}],"함정":[{"x":"표현대리가 성립하는 경우, 상대방에게 과실이 있다면 과실상계의 법리가 유추적용되어 본인의 책임이 경감될 수 있다.","o":"과실상계 법리를 유추적용할 수 없다.","src":"기출 2021-20 | 기출 2023-20 | 기출 2024-16"},{"x":"丁이 甲의 배임행위에 적극 가담한 사정을 丙이 모른다면, 丙 명의로 경료된 소유권이전등기는 유효하다.","o":"반사회질서 법률행위는 절대적 무효다. 선의의 전득자도 보호되지 않는다.","src":"기출 2021-21"},{"x":"무권대리행위가 제3자의 위법행위로 야기된 경우에는 무권대리인에게 귀책사유가 있어야 민법 제135조에 따른 무권대리인의 상대방에 대한 책임이 인정된다.","o":"귀책사유가 없어도 책임을 진다(무과실책임).","src":"민법 제135조 | 기출 2022-23 | 기출 2023-21"},{"x":"丙은 甲의 지명이나 승낙 기타 부득이한 사유가 없더라도 복대리인을 선임할 수 있다.","o":"임의대리인은 본인의 승낙이나 부득이한 사유가 있어야 선임할 수 있다.","src":"민법 제120조 | 기출 2023-10"},{"x":"만약 甲의 지명에 따라 丙을 선임한 경우, 乙은 甲에게 그 부적임을 알고 통지나 해임을 하지 않더라도 책임이 없다.","o":"부적임을 알고 통지나 해임을 태만한 때에는 책임이 있다.","src":"민법 제121조 제2항 | 기출 2023-10"},{"x":"사회통념상 대리권을 추단할 수 있는 직함이나 명칭 등의 사용을 승낙한 경우라도 특별한 사정이 없는 한 대리권 수여의 표시가 있는 것으로 볼 수는 없다.","o":"대리권 수여의 표시가 있는 것으로 볼 수 있다.","src":"기출 2023-20"},{"x":"복대리인의 권한은 권한을 넘은 표현대리의 기본대리권이 될 수 없다.","o":"기본대리권이 될 수 있다.","src":"기출 2023-20"},{"x":"대리행위가 강행법규에 반하여 무효인 경우에도 표현대리가 성립할 수 있다.","o":"성립할 수 없다.","src":"기출 2023-20 | 기출 2026-20"},{"x":"유권대리에 관한 주장에는 표현대리의 주장이 포함되어 있다고 볼 수 있다.","o":"포함되어 있지 않다.","src":"기출 2023-20"},{"x":"乙의 무권대리행위가 제3자의 위법행위로 야기된 경우, 乙은 과실이 없으므로 丙에게 무권대리행위로 인한 책임을 지지 않는다.","o":"과실이 없어도 책임을 진다.","src":"기출 2023-21"},{"x":"민법상 조합은 법인격이 없으므로 조합대리의 경우에는 반드시 조합원 전원의 성명을 표시하여 대리행위를 하여야 한다.","o":"조합 이름만 표시해도 된다.","src":"기출 2024-14 | 보충"},{"x":"대리인의 권한을 넘는 행위가 범죄를 구성하는 경우에는 권한을 넘는 표현대리의 법리는 적용될 여지가 없다.","o":"적용될 수 있다.","src":"기출 2024-16"},{"x":"복대리인은 그 권한 내에서 자신을 선임한 대리인을 대리한다.","o":"복대리인은 본인을 대리한다.","src":"민법 제123조 | 기출 2025-18"},{"x":"丙이 계약 당시에 乙에게 대리권이 없음을 알았던 경우, 丙은 계약을 철회할 수 있다.","o":"악의의 상대방은 철회할 수 없다.","src":"민법 제134조 | 기출 2025-19"},{"x":"甲이 추인하지 않은 경우, 계약 당시에 무권대리 사실을 알았던 丙은 乙에게 손해배상을 청구할 수 있다.","o":"악의(또는 과실)의 상대방은 무권대리인에게 책임을 물을 수 없다.","src":"민법 제135조 제2항 | 기출 2025-19"},{"x":"대리행위 당시에 乙이 제한능력자인 경우, 甲으로부터 추인받지 못한 丙은 乙에게 계약의 이행을 청구할 수 있다.","o":"제한능력자인 무권대리인에게는 책임을 물을 수 없다.","src":"민법 제135조 제2항 | 기출 2025-19"},{"x":"乙이 甲을 단독 상속한 경우, 乙은 특별한 사정이 없는 한 본인의 지위에서 추인거절권을 행사할 수 있다.","o":"신의칙상 추인거절권을 행사할 수 없다.","src":"기출 2025-19 | 기출 2023-21"},{"x":"채권양도의 통지는 양도인이 해야 하므로 양수인이 양도인의 대리인으로서 채권양도의 통지에 관한 위임을 받았더라도 양수인에 의한 양도통지는 효력이 없다.","o":"양도인의 대리인으로서 한 통지는 유효하다.","src":"기출 2023-34 | 기출 2026-18"},{"x":"계약 체결 당시 甲의 무권대리에 대하여 악의인 丙은 乙에 대하여 추인 여부의 확답을 최고할 수 없다.","o":"악의여도 최고할 수 있다.","src":"민법 제131조 | 기출 2026-19"},{"x":"甲의 무권대리행위가 있음을 乙이 알지 못한 상태에서 이루어진 乙의 甲에 대한 추인은 효력이 있다.","o":"출제 오답(바른 수치 미확인). 본인이 무권대리인에게 추인한 경우 상대방이 안 때까지는 상대방에 대항하지 못한다(제132조).","src":"기출 2026-19"},{"x":"계약 체결 당시 甲의 무권대리에 대하여 악의인 丙은 甲에 대하여 계약을 철회할 수 있다.","o":"악의의 상대방은 철회할 수 없다.","src":"민법 제134조 | 기출 2026-19"},{"x":"乙이 甲에 대하여 무권대리행위를 추인한 경우에는 丙이 그 추인 사실을 알지 못하더라도 乙은 丙에게 추인의 효과를 주장할 수 있다.","o":"상대방이 그 사실을 알기 전에는 추인의 효과를 주장하지 못한다.","src":"민법 제132조 | 기출 2026-19"},{"x":"복대리권의 소멸사유로 본인의 특정후견의 개시가 있다.","o":"본인의 특정후견 개시는 소멸사유가 아니다. 본인의 사망, 대리인의 사망ㆍ성년후견 개시ㆍ파산이 소멸사유다.","src":"민법 제127조 | 기출 2022-22"}]},"무효와 취소":{"묶음":[{"머리":"일부무효ㆍ무효행위의 전환ㆍ무효행위의 추인","줄":[{"t":"일부무효: 법률행위의 일부분이 무효인 때에는 그 전부를 무효로 한다. 단 그 무효부분이 없더라도 법률행위를 하였을 것이라고 인정될 때에는 나머지 부분은 무효가 되지 아니한다.","src":"민법 제137조 | 기출 2022-12 | 기출 2025-20"},{"t":"제137조는 당사자의 합의로 그 적용을 배제할 수 있다.","src":"기출 2022-12"},{"t":"무효행위의 전환: 무효인 법률행위가 다른 법률행위의 요건을 구비하고 당사자가 그 무효를 알았더라면 다른 법률행위를 하는 것을 의욕하였으리라고 인정될 때 다른 법률행위로서 효력을 가진다. 불공정한 법률행위에도 적용될 수 있다.","src":"민법 제138조 | 기출 2022-19 | 기출 2026-14"},{"t":"무효행위의 추인: 무효인 법률행위는 추인하여도 효력이 생기지 않는다. 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다(소급효 없음).","src":"민법 제139조"},{"t":"무효인 가등기를 유효한 등기로 전용하기로 약정한 경우 그 가등기는 약정 시부터 유효하고, 등기 시로 소급하여 유효하게 되는 것은 아니다.","src":"기출 2022-12 | 기출 2025-20 | 보충(추정)"},{"t":"불공정한 법률행위로서 무효인 법률행위는 추인에 의하여 유효로 될 수 없다.","src":"기출 2025-20"},{"t":"무권리자의 처분행위에 대한 권리자의 추인의 의사표시는 무권리자나 그 상대방 어느 쪽에 하여도 무방하다.","src":"기출 2023-22"},{"t":"비진의 의사표시의 무효는 선의의 제3자에게 대항할 수 없다.","src":"민법 제107조 제2항 | 기출 2025-20"},{"t":"집합채권의 양도가 양도금지특약 위반으로 무효인 경우 채무자는 일부 개별 채권을 특정하여 추인할 수 있다.","src":"기출 2023-22"},{"t":"토지거래허가구역 내 토지 매매계약: 처음부터 허가를 배제하는 내용의 계약이거나 당사자 쌍방이 허가신청협력의무의 이행거절 의사를 상대방에게 명백히 표시한 경우 확정적 무효다.","src":"기출 2023-22 | 기출 2025-20"},{"t":"토지거래허가 전 계약은 유동적 무효 상태이며, 일방이 허가절차에 협력할 의무를 이행하지 않아도 상대방은 계약을 해제할 수 없다.","src":"기출 2026-35 | 기출 2022-36"},{"t":"강행법규 위반으로 무효임을 알면서 법률행위를 한 자가 그 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반하지 않는다.","src":"기출 2025-3 | 기출 2026-20"},{"t":"전세목적물의 사용ㆍ수익 권능을 배제하고 채권담보만을 위해 설정한 전세권설정등기는 무효다.","src":"기출 2025-30 | 기출 2026-20"},{"t":"공유자 중 1인이 다른 공유자의 동의 없이 공유 토지의 특정 부분을 매도하여 타인 명의로 이전등기를 마친 경우, 그 등기는 그 공유자의 지분 범위에서는 유효하다(전부 무효 아님).","src":"기출 2024-28 | 기출 2026-20"}]},{"머리":"취소권자ㆍ취소의 방법ㆍ효과","줄":[{"t":"취소권자: 제한능력자, 착오로 인하거나 사기ㆍ강박에 의하여 의사표시를 한 자, 그의 대리인 또는 승계인만이 취소할 수 있다.","src":"민법 제140조"},{"t":"취소의 효과: 취소된 법률행위는 처음부터 무효로 본다. 제한능력자는 받은 이익이 현존하는 한도에서 상환할 책임이 있다.","src":"민법 제141조 | 기출 2025-21"},{"t":"취소의 상대방: 취소할 수 있는 법률행위의 상대방이 확정한 경우에는 그 상대방에 대한 의사표시로 하여야 한다.","src":"민법 제142조 | 기출 2022-12 | 기출 2025-21"},{"t":"대리인이 취소권을 행사하려면 특별한 사정이 없는 한 취소권 행사에 관한 본인의 수권행위가 있어야 한다. 대리권만으로는 부족하다.","src":"기출 2021-18"},{"t":"일부취소: 가분적인 법률행위의 일부에만 취소사유가 있고 나머지를 유지하려는 당사자의 가정적 의사가 있는 경우 일부만의 취소도 가능하다.","src":"기출 2021-18"},{"t":"취소할 수 있는 법률행위를 취소한 후에도 무효행위 추인의 요건을 갖추면 다시 추인할 수 있다(새로운 법률행위로 봄).","src":"민법 제139조 | 기출 2021-18 | 기출 2023-22"},{"t":"해제와 취소는 별개다: 매도인이 매매계약을 적법하게 해제한 뒤에도 매수인은 착오를 이유로 취소할 수 있다.","src":"기출 2021-18"}]},{"머리":"추인","줄":[{"t":"추인의 방법ㆍ효과: 취소할 수 있는 법률행위는 제140조의 취소권자가 추인할 수 있고 추인 후에는 취소하지 못한다. 추인의 상대방은 취소와 같다(제142조 준용).","src":"민법 제143조 | 기출 2025-21"},{"t":"추인의 요건: 취소의 원인이 소멸된 후에 하여야 효력이 있다. 법정대리인 또는 후견인이 추인하는 경우에는 적용하지 아니한다.","src":"민법 제144조 | 기출 2022-12"},{"t":"법정대리인이 제한능력자의 법률행위를 추인한 후에는 제한능력을 이유로 취소하지 못한다.","src":"기출 2022-12"},{"t":"추인은 추인권자가 그 행위가 취소할 수 있는 것임을 알고 하여야 한다.","src":"기출 2023-22"},{"t":"법정추인 사유(6가지): ① 전부나 일부의 이행 ② 이행의 청구 ③ 경개 ④ 담보의 제공 ⑤ 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도 ⑥ 강제집행. 추인할 수 있는 후에 해야 하며 이의를 보류하면 추인한 것으로 보지 않는다.","src":"민법 제145조 | 기출 2021-18 | 기출 2024-17"},{"t":"계약의 해제는 법정추인 사유가 아니다.","src":"민법 제145조 | 기출 2024-17"},{"t":"미성년자가 행위능력자가 된 후 이의를 보류함이 없이 법률행위에 따라 이행한 때에는 추인한 것으로 본다.","src":"민법 제145조 | 기출 2025-21"},{"t":"취소할 수 있는 법률행위를 추인한 취소권자는 특별한 사정이 없는 한 다시 취소할 수 없다.","src":"민법 제143조 | 기출 2025-21"}]},{"머리":"취소권의 소멸","줄":[{"t":"취소권은 추인할 수 있는 날로부터 3년 내에, 법률행위를 한 날로부터 10년 내에 행사하여야 한다(둘 중 먼저 도래하는 기간).","src":"민법 제146조 | 기출 2025-21"},{"t":"추인할 수 있는 날부터 3년이 경과하면 법률행위일부터 10년이 지나지 않았어도 취소할 수 없다.","src":"민법 제146조 | 기출 2025-21"}]}],"함정":[{"x":"취소할 수 있는 법률행위를 취소한 경우, 무효행위의 추인요건을 갖추더라도 다시 추인할 수 없다.","o":"무효행위 추인 요건을 갖추면 다시 추인할 수 있다.","src":"민법 제139조 | 기출 2021-18 | 기출 2023-22"},{"x":"무효인 가등기를 유효한 등기로 전용하기로 약정한 경우, 그 가등기는 등기시로 소급하여 유효한 등기로 된다.","o":"소급하지 않고 약정 시부터 유효하다.","src":"기출 2022-12 | 기출 2025-20 | 보충(추정)"},{"x":"집합채권의 양도가 양도금지특약을 위반하여 무효인 경우, 채무자는 일부 개별 채권을 특정하여 추인할 수 없다.","o":"채무자는 일부 개별 채권을 특정하여 추인할 수 있다.","src":"기출 2023-22"},{"x":"추인할 수 있는 날로부터 3년이 경과하였지만 법률행위를 한 날로부터 10년이 경과하지 않았다면, 취소권자는 그 법률행위를 취소할 수 있다.","o":"추인할 수 있는 날부터 3년이 경과하면 취소할 수 없다.","src":"민법 제146조 | 기출 2025-21"},{"x":"전세목적물에 대한 사용ㆍ수익 권능을 배제하고 채권담보만을 위해 설정한 전세권설정등기도 유효하다.","o":"무효다.","src":"기출 2026-20"},{"x":"공유자 중 1인이 다른 공유자의 동의없이 공유 토지를 매도하여 타인 명의로 소유권이전등기가 마쳐졌다면 그 등기는 전부 무효이다.","o":"그 공유자의 지분 범위에서는 유효하다.","src":"기출 2024-28 | 기출 2026-20"},{"x":"대리행위가 강행법규에 위반하여 무효인 경우에도 표현대리가 성립할 수 있다.","o":"성립할 수 없다.","src":"기출 2026-20"},{"x":"법령에 위반되어 무효임을 알면서 법률행위를 한 자가 강행법규 위반을 이유로 그 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반한다.","o":"신의칙에 반하지 않는다.","src":"기출 2026-20"},{"x":"계약의 해제는 취소권자의 이의 보류 없는 행위로서 법정추인 사유에 해당한다.","o":"해제는 법정추인 사유가 아니다. 경개ㆍ담보제공ㆍ이행ㆍ권리 양도는 해당한다.","src":"민법 제145조 | 기출 2024-17"}]},"조건과 기한":{"묶음":[{"머리":"조건의 효과와 성질","줄":[{"t":"조건성취의 효과: 정지조건 있는 법률행위는 조건이 성취한 때로부터 효력이 생긴다. 해제조건 있는 법률행위는 조건이 성취한 때로부터 효력을 잃는다.","src":"민법 제147조 제1항ㆍ제2항 | 기출 2024-21 | 기출 2022-13"},{"t":"당사자가 조건성취의 효력을 그 성취 전에 소급하게 할 의사를 표시한 때에는 그 의사에 의한다(소급 특약은 유효).","src":"민법 제147조 제3항 | 기출 2021-22"},{"t":"조건은 의사표시의 일반원칙에 따라 조건의사와 그 표시가 필요하다. 조건의사가 외부로 표시되지 않으면 조건부 법률행위로 인정되지 않는다.","src":"기출 2021-22 | 기출 2023-23 | 기출 2026-22"},{"t":"법률행위에 정지조건이 붙어 있다는 사실(조건의 존재)은 그 법률효과의 발생을 다투려는 자가 증명하여야 한다.","src":"기출 2021-22 | 기출 2022-13 | 기출 2023-23 | 기출 2026-22"},{"t":"상계의 의사표시에는 조건이나 기한을 붙일 수 없다.","src":"기출 2021-22 | 기출 2026-22 | 민법 제493조(원문 미확인)"}]},{"머리":"조건부 권리의 보호","줄":[{"t":"조건부권리의 침해금지: 조건 있는 법률행위의 당사자는 조건의 성부가 미정한 동안에 조건의 성취로 인하여 생길 상대방의 이익을 해하지 못한다.","src":"민법 제148조"},{"t":"조건부권리의 처분: 조건의 성취가 미정한 권리의무는 일반규정에 의하여 처분, 상속, 보존 또는 담보로 할 수 있다.","src":"민법 제149조 | 기출 2022-13 | 기출 2025-22 | 기출 2026-22"},{"t":"반신의행위: 조건의 성취로 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때 상대방은 그 조건이 성취한 것으로 주장할 수 있다(주장할 수 있는 것이지 방해 시점에 당연히 성취로 의제되는 것이 아니다). 조건의 성취로 이익을 받을 당사자가 신의성실에 반하여 조건을 성취시킨 때에는 상대방은 성취하지 아니한 것으로 주장할 수 있다.","src":"민법 제150조 | 기출 2023-23"}]},{"머리":"불법조건ㆍ기성조건ㆍ불능조건","줄":[{"t":"불법조건: 조건이 선량한 풍속 기타 사회질서에 위반한 것인 때 그 법률행위는 무효로 한다. 조건의 내용 자체가 불법이어서 무효이면 조건부 법률행위 전부가 무효다.","src":"민법 제151조 제1항 | 기출 2024-21 | 기출 2025-22 | 기출 2026-22"},{"t":"기성조건: 조건이 법률행위 당시 이미 성취한 것이면, 정지조건이면 조건 없는 법률행위로 하고, 해제조건이면 그 법률행위는 무효로 한다.","src":"민법 제151조 제2항"},{"t":"불능조건: 조건이 법률행위 당시 이미 성취할 수 없는 것이면, 해제조건이면 조건 없는 법률행위로 하고, 정지조건이면 그 법률행위는 무효로 한다.","src":"민법 제151조 제3항 | 기출 2022-13 | 기출 2025-22"}]},{"머리":"기한","줄":[{"t":"기한도래의 효과: 시기(始期) 있는 법률행위는 기한이 도래한 때로부터 효력이 생긴다. 종기(終期) 있는 법률행위는 기한이 도래한 때로부터 효력을 잃는다.","src":"민법 제152조 | 기출 2024-21"},{"t":"기한의 이익: 기한은 채무자의 이익을 위한 것으로 추정한다. 기한의 이익은 포기할 수 있으나 상대방의 이익을 해하지 못한다.","src":"민법 제153조 | 기출 2022-13 | 기출 2024-21 | 기출 2025-22"},{"t":"기한부 권리의 보호ㆍ처분: 제148조와 제149조를 기한 있는 법률행위에 준용한다.","src":"민법 제154조"},{"t":"불확정한 사실이 발생한 때를 이행기한으로 정한 경우, 그 사실의 발생이 불가능하게 된 때에도 기한이 도래한 것으로 본다.","src":"기출 2021-22"},{"t":"기한이익 상실의 특약은 특별한 사정이 없는 한 형성권적 기한이익 상실 특약(채권자의 청구 필요)으로 추정한다.","src":"기출 2023-23 | 기출 2025-22"},{"t":"보증채무에서 주채무자의 기한이익 포기는 보증인에게 효력이 미치지 않는다.","src":"기출 2023-23"},{"t":"확정기한부 채무는 기한이 도래한 때부터 지체책임을 진다. 불확정기한부 채무는 채무자가 기한이 도래함을 안 때부터 지체책임이 있다.","src":"기출 2024-34 | 기출 2025-35 | 민법 제387조(원문 미확인)"}]}],"함정":[{"x":"당사자가 조건성취의 효력을 그 성취전에 소급하게 할 의사를 표시한 경우, 그 의사표시는 무효이다.","o":"그 의사에 의한다(유효).","src":"민법 제147조 제3항 | 기출 2021-22"},{"x":"특별한 사정이 없는 한 기한의 이익은 이를 포기할 수 없다.","o":"포기할 수 있다. 다만 상대방의 이익을 해하지 못한다.","src":"민법 제153조 | 기출 2022-13"},{"x":"정지조건있는 법률행위는 조건이 성취한 때로부터 그 효력을 잃는다.","o":"정지조건은 성취한 때부터 효력이 생긴다. 효력을 잃는 것은 해제조건이다.","src":"민법 제147조 | 기출 2022-13"},{"x":"조건의 성취가 미정한 권리는 일반규정에 의하여 담보로 할 수 없다.","o":"처분, 상속, 보존 또는 담보로 할 수 있다.","src":"민법 제149조 | 기출 2022-13"},{"x":"법률행위에 어떤 조건이 붙어 있었는지 여부는 그 조건의 부존재를 주장하는 자가 이를 증명해야 한다.","o":"법률효과의 발생을 다투려는 자(조건의 존재를 주장하는 자)가 증명한다.","src":"기출 2022-13 | 기출 2023-23"},{"x":"조건의 성취로 인하여 불이익을 받을 당사자가 신의칙에 반하여 조건의 성취를 방해한 경우, 그러한 행위가 있었던 시점에 조건은 성취된 것으로 의제된다.","o":"상대방이 조건이 성취한 것으로 주장할 수 있다.","src":"민법 제150조 제1항 | 기출 2023-23"},{"x":"시기(始期)있는 법률행위는 그 기한이 도래한 때로부터 그 효력이 소멸한다.","o":"시기는 도래한 때부터 효력이 생기고, 종기가 도래하면 효력이 소멸한다.","src":"민법 제152조 | 기출 2024-21"},{"x":"조건이 법률행위의 당시에 이미 성취할 수 없는 것인 경우, 그 조건이 해제조건이면 그 법률행위는 무효로 한다.","o":"해제조건이면 조건 없는 법률행위가 되고, 정지조건이면 무효다.","src":"민법 제151조 제3항 | 기출 2025-22"},{"x":"조건은 법률행위의 부관이므로 조건을 붙이고자 하는 의사가 외부에 표시되지 않더라도 조건이 된다.","o":"조건의사가 외부로 표시되어야 조건이 된다.","src":"기출 2026-22 | 기출 2021-22"}]},"소멸시효":{"묶음":[{"머리":"소멸시효기간","줄":[{"t":"일반기간: 채권은 10년, 채권 및 소유권 이외의 재산권은 20년간 행사하지 않으면 소멸시효가 완성한다. 소유권은 소멸시효에 걸리지 않는다.","src":"민법 제162조 | 기출 2024-22"},{"t":"지역권은 20년간 행사하지 않으면 시효로 소멸한다. 불계속지역권도 소멸시효에 걸린다.","src":"민법 제162조 제2항 | 기출 2021-23 | 기출 2023-25 | 기출 2024-22"},{"t":"소유권에 기한 물권적 청구권은 소멸시효의 대상이 아니다.","src":"기출 2021-27 | 기출 2023-24 | 기출 2025-27"},{"t":"3년의 단기소멸시효(제163조 7개 호): ① 이자, 부양료, 급료, 사용료 기타 1년 이내의 기간으로 정한 금전 또는 물건의 지급을 목적으로 한 채권 ② 의사ㆍ조산사ㆍ간호사ㆍ약사의 치료ㆍ근로ㆍ조제에 관한 채권 ③ 도급받은 자ㆍ기사 기타 공사의 설계 또는 감독에 종사하는 자의 공사에 관한 채권 ④ 변호사ㆍ변리사ㆍ공증인ㆍ공인회계사ㆍ법무사에 대한 직무상 보관한 서류의 반환을 청구하는 채권 ⑤ 변호사 등의 직무에 관한 채권 ⑥ 생산자 및 상인이 판매한 생산물 및 상품의 대가 ⑦ 수공업자 및 제조자의 업무에 관한 채권.","src":"민법 제163조"},{"t":"1년의 단기소멸시효(제164조 4개 호): ① 여관ㆍ음식점ㆍ대석ㆍ오락장의 숙박료, 음식료, 대석료, 입장료, 소비물의 대가 및 체당금 ② 의복ㆍ침구ㆍ장구 기타 동산의 사용료 ③ 노역인ㆍ연예인의 임금 및 공급한 물건의 대금 ④ 학생 및 수업자의 교육ㆍ의식ㆍ유숙에 관한 교주ㆍ숙주ㆍ교사의 채권.","src":"민법 제164조"},{"t":"3년 단기시효가 적용되는 예: 매월 1개월 단위로 지급되는 집합건물 관리비채권, 도급받은 공사의 공사대금채권, 상인이 판매한 상품의 대가채권, 공사대금채권을 담보하기 위한 수급인의 저당권설정청구권(공사대금채권과 같이 3년).","src":"기출 2022-14 | 기출 2024-22 | 기출 2026-24 | 보충(추정)"},{"t":"3년 단기시효가 적용되지 않는 예: 금전채무의 이행지체로 발생하는 지연손해금, 1년 이내의 정기로 지급하기로 한 것이 아닌 이자채권.","src":"기출 2024-22 | 기출 2026-24"},{"t":"확정채권: 판결에 의하여 확정된 채권은 단기의 소멸시효에 해당하는 것이라도 10년으로 한다. 파산절차ㆍ재판상 화해ㆍ조정 등 판결과 동일한 효력이 있는 것으로 확정된 채권도 같다(지급명령 확정 포함). 판결 확정 당시 변제기가 도래하지 않은 채권에는 적용하지 않는다.","src":"민법 제165조 | 기출 2025-23"}]},{"머리":"기산점","줄":[{"t":"소멸시효는 권리를 행사할 수 있는 때로부터 진행한다. 부작위를 목적으로 하는 채권은 위반행위를 한 때부터 진행한다(계약체결 시부터가 아님).","src":"민법 제166조 | 기출 2022-14"},{"t":"소멸시효는 그 기산일에 소급하여 효력이 생긴다.","src":"민법 제167조"},{"t":"당사자가 본래의 기산일과 다른 기산일을 주장하는 경우 법원은 변론주의에 따라 당사자가 주장하는 기산일을 기준으로 계산하여야 한다.","src":"기출 2022-14 | 보충(추정)"},{"t":"정지조건부 채권(권리)은 조건이 성취된 때부터 시효가 진행한다(성취 전에는 진행하지 않음).","src":"기출 2021-23 | 기출 2026-23"},{"t":"선택채권은 선택권을 행사할 수 있을 때부터 진행한다.","src":"기출 2026-23"},{"t":"채무불이행으로 인한 손해배상청구권은 특별한 사정이 없는 한 채무를 불이행한 때부터 진행한다.","src":"기출 2026-23"},{"t":"확정기한부 채무의 기한 도래 후 기한을 유예하기로 합의한 경우 변경된 이행기가 도래한 때부터 시효가 다시 진행한다.","src":"기출 2026-23"},{"t":"부당이득반환채무는 성립한 때부터 소멸시효가 진행한다(채권자가 이행을 청구한 때가 기산점이 아님).","src":"기출 2026-23 | 보충(추정)"},{"t":"건물이 완공되기 전에는 건물에 관한 소유권이전등기청구권의 시효가 진행하지 않는다.","src":"기출 2021-23 | 기출 2025-23"},{"t":"매수인이 목적 부동산을 인도받아 계속 점유하는 경우 소유권이전등기청구권의 소멸시효는 진행하지 않는다. 점유를 승계시켜 타인에게 처분한 경우에도 같다. 이 청구권은 권리의 성질상 양도가 제한되고 양도에 채무자의 승낙이나 동의가 필요하다.","src":"기출 2022-26 | 기출 2025-23"},{"t":"공유관계가 존속하는 한 공유물분할청구권은 독립하여 소멸시효에 걸리지 않는다.","src":"기출 2021-23"},{"t":"근저당권설정약정에 의한 근저당권설정등기청구권은 피담보채권과 별개로 소멸시효에 걸린다.","src":"기출 2022-14 | 보충(추정)"},{"t":"사실상 권리의 존재나 권리행사 가능성을 알지 못하였다는 사유는 특별한 사정이 없는 한 소멸시효 진행을 방해하지 않는다.","src":"기출 2023-24"},{"t":"하자담보책임에 기한 매수인의 손해배상청구권은 제척기간 규정이 있어도 소멸시효의 적용이 배제되지 않는다. 매도인의 담보책임 권리행사기간(제척기간) 예: 타인 권리 일부 취득불능 선의 매수인은 안 날부터, 악의는 계약한 날부터 1년(제573조), 하자담보 안 날부터 6월(제582조).","src":"기출 2023-24 | 민법 제573조 | 민법 제582조"}]},{"머리":"중단","줄":[{"t":"중단사유 3가지: ① 청구 ② 압류 또는 가압류ㆍ가처분 ③ 승인.","src":"민법 제168조"},{"t":"중단의 효력은 당사자 및 그 승계인 간에만 효력이 있다(상대적 효력).","src":"민법 제169조 | 기출 2021-24"},{"t":"재판상 청구는 소송의 각하ㆍ기각ㆍ취하의 경우 중단 효력이 없다. 그 경우 6월 내에 재판상 청구, 파산절차참가, 압류ㆍ가압류ㆍ가처분을 하면 최초의 재판상 청구로 중단된 것으로 본다.","src":"민법 제170조"},{"t":"파산절차참가는 채권자가 취소하거나 청구가 각하되면 중단 효력이 없다. 지급명령은 채권자가 법정기간 내 가집행신청을 하지 않아 효력을 잃으면 중단 효력이 없다. 지급명령신청은 재판상 청구에 포함된다.","src":"민법 제171조 | 민법 제172조 | 기출 2022-15"},{"t":"화해를 위한 소환은 상대방이 출석하지 않거나 화해가 성립되지 않으면 1월 내에 소를 제기하지 않는 한 중단 효력이 없다. 임의출석도 같다.","src":"민법 제173조"},{"t":"최고는 6월 내에 재판상 청구, 파산절차참가, 화해를 위한 소환, 임의출석, 압류ㆍ가압류ㆍ가처분을 하지 않으면 시효중단 효력이 없다(내용증명 이행청구도 최고).","src":"민법 제174조 | 기출 2024-23"},{"t":"압류ㆍ가압류ㆍ가처분은 권리자의 청구에 의하거나 법률 규정에 따르지 않아 취소된 때 중단 효력이 없다. 시효의 이익을 받은 자에 대하여 하지 아니한 때에는 그에게 통지한 후가 아니면 중단 효력이 없다.","src":"민법 제175조 | 민법 제176조"},{"t":"물상보증인 소유 부동산에 대한 압류는 주채무자에게 통지하여야 주채무자에 대하여 시효중단의 효력이 생긴다.","src":"민법 제176조 | 기출 2021-24"},{"t":"가압류는 시효중단 사유이며 그 효력은 가압류의 집행보전의 효력이 존속하는 동안 계속된다. 취득시효에서는 부동산에 대한 압류ㆍ가압류가 취득시효 중단사유가 아니다.","src":"기출 2021-24 | 기출 2022-15 | 기출 2023-28 | 기출 2025-23 | 기출 2026-27"},{"t":"승인: 시효중단의 효력 있는 승인에는 상대방의 권리에 관한 처분의 능력이나 권한 있음을 요하지 않는다. 승인은 의사표시가 아니라 관념의 통지이며 묵시적으로도 할 수 있다.","src":"민법 제177조 | 기출 2022-15 | 기출 2024-24"},{"t":"중단 후 진행: 중단까지 경과한 기간은 산입하지 않고 중단사유가 종료한 때부터 새로 진행한다. 재판상 청구로 중단된 시효는 재판이 확정된 때부터 새로 진행한다.","src":"민법 제178조 | 기출 2022-15"},{"t":"시효 진행이 개시되기 전의 승인은 시효중단의 효력이 없다.","src":"기출 2025-23 | 보충(추정)"},{"t":"채무자가 담보 목적의 가등기를 설정해 주는 것은 채무의 승인에 해당하나, 가등기가 계속되는 동안 시효가 진행하지 않는다는 뜻은 아니다.","src":"기출 2024-24 | 보충(추정)"},{"t":"시효완성 전 채무의 일부 변제는 채무 승인의 효력은 있으나 채무 전부에 관한 시효이익 포기의 효력은 없다.","src":"기출 2024-24 | 보충(추정)"}]},{"머리":"정지","줄":[{"t":"제한능력자: 기간만료 전 6개월 내에 제한능력자에게 법정대리인이 없는 경우 그가 능력자가 되거나 법정대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 않는다.","src":"민법 제179조"},{"t":"재산을 관리하는 아버지ㆍ어머니ㆍ후견인에 대한 제한능력자의 권리는 능력자가 되거나 후임 법정대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 않는다.","src":"민법 제180조 제1항 | 기출 2021-24 | 기출 2026-18"},{"t":"부부 중 한쪽이 다른 쪽에 대하여 가지는 권리는 혼인관계가 종료된 때부터 6개월 내에는 시효가 완성되지 않는다.","src":"민법 제180조 제2항 | 기출 2021-24"},{"t":"상속재산에 관한 권리: 상속인의 확정, 관리인의 선임 또는 파산선고가 있는 때부터 6월 내에는 시효가 완성하지 않는다.","src":"민법 제181조"},{"t":"천재 기타 사변으로 중단할 수 없을 때에는 그 사유가 종료한 때부터 1월 내에는 시효가 완성하지 않는다.","src":"민법 제182조"},{"t":"요역지가 수인의 공유인 경우 그 1인에 의한 지역권 소멸시효의 중단 또는 정지는 다른 공유자를 위하여 효력이 있다.","src":"민법 제296조"},{"t":"유치권의 행사는 피담보채권의 소멸시효의 진행에 영향을 미치지 않는다.","src":"민법 제326조 | 기출 2022-32 | 기출 2025-31"}]},{"머리":"시효의 효과와 이익의 포기","줄":[{"t":"소멸시효의 이익은 미리 포기하지 못한다. 소멸시효는 법률행위로 배제ㆍ연장ㆍ가중할 수 없으나 단축 또는 경감할 수 있다.","src":"민법 제184조 | 기출 2022-14"},{"t":"주된 권리의 소멸시효가 완성한 때에는 종속된 권리에 그 효력이 미친다.","src":"민법 제183조 | 기출 2023-2 | 기출 2026-8"},{"t":"시효완성 후 소멸시효가 완성된 채권도 완성 전에 상계할 수 있었던 것이면 채권자는 상계할 수 있다.","src":"민법 제495조 | 기출 2025-24"},{"t":"시효완성 후 채무를 승인하였다고 곧바로 시효이익을 포기한 것으로 간주되지는 않는다(시효완성 사실을 알고 한 것으로 추정되는 정도).","src":"기출 2021-23 | 보충(추정)"},{"t":"소멸시효 이익의 포기는 시효완성의 이익을 받을 당사자가 해야 한다. 당사자나 대리인이 아닌 제3자가 한 포기는 이익을 받을 자에게 효력이 없다. 가분채무의 일부에 대하여도 포기할 수 있다.","src":"기출 2025-24"},{"t":"소유권이전등기청구권의 소멸시효기간이 지난 사실을 알고 있는 등기의무자가 소유권이전등기를 해 주기로 약정한 경우 특별한 사정이 없는 한 시효이익의 포기로 본다.","src":"기출 2025-24"},{"t":"후순위 담보권자는 선순위 담보권의 피담보채권의 시효소멸로 직접 이익을 받는 자가 아니므로 그 피담보채권의 소멸시효 완성을 주장할 수 없다.","src":"기출 2025-24"},{"t":"저당권으로 담보한 채권이 시효 완성으로 소멸하면 저당권도 소멸한다. 나대지의 담보가치 유지를 위한 무상 지상권도 피담보채권이 시효로 소멸하면 소멸한다.","src":"기출 2023-30 | 기출 2025-32"},{"t":"취득시효와 소멸시효의 비교: 취득시효 완성의 효력은 점유개시 시로 소급한다.","src":"기출 2023-25"},{"t":"불법행위로 인한 손해배상청구권은 피해자나 법정대리인이 손해 및 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년 내에 행사하지 않으면 소멸한다.","src":"민법 제766조"}]}],"함정":[{"x":"소멸시효 완성 후에 채무승인이 있었다면, 곧바로 소멸시효 이익의 포기가 있은 것으로 간주된다.","o":"곧바로 포기로 간주되지 않는다.","src":"기출 2021-23"},{"x":"물상보증인 소유의 부동산에 대한 압류는 그 통지와 관계없이 주채무자에 대하여 시효중단의 효력이 생긴다.","o":"주채무자에게 통지한 후에 효력이 생긴다.","src":"민법 제176조 | 기출 2021-24"},{"x":"소멸시효의 이익은 미리 포기할 수 있다.","o":"미리 포기하지 못한다.","src":"민법 제184조 | 기출 2022-14"},{"x":"부작위를 목적으로 하는 채권의 소멸시효는 계약체결시부터 진행한다.","o":"위반행위를 한 때부터 진행한다.","src":"민법 제166조 제2항 | 기출 2022-14"},{"x":"근저당권설정약정에 의한 근저당권설정등기청구권은 그 피담보채권이 될 채권과 별개로 소멸시효에 걸리지 않는다.","o":"별개로 소멸시효에 걸린다.","src":"기출 2022-14 | 보충(추정)"},{"x":"당사자가 본래의 소멸시효 기산일과 다른 기산일을 주장하는 경우, 법원은 원칙적으로 본래의 소멸시효 기산일을 기준으로 소멸시효를 계산해야 한다.","o":"당사자가 주장하는 기산일을 기준으로 계산한다.","src":"기출 2022-14 | 보충(추정)"},{"x":"승인으로 인한 시효중단의 효력은 그 승인의 통지가 상대방에게 발신된 때에 발생한다.","o":"도달한 때에 발생한다(출제 오답).","src":"기출 2022-15 | 보충(추정)"},{"x":"채권 및 소유권은 10년간 행사하지 아니하면 소멸시효가 완성한다.","o":"소유권은 소멸시효에 걸리지 않는다.","src":"민법 제162조 | 기출 2024-22"},{"x":"소멸시효 중단사유인 채무의 승인은 의사표시에 해당한다.","o":"관념의 통지다.","src":"기출 2024-24"},{"x":"소멸시효 이익의 포기사유인 채무의 묵시적 승인은 관념의 통지에 해당한다.","o":"시효이익의 포기는 의사표시다.","src":"기출 2024-24 | 보충(추정)"},{"x":"시효완성 전에 채무의 일부를 변제한 경우에는 그 수액에 관하여 다툼이 없는 한 채무 승인의 효력이 있어 채무 전부에 관하여 소멸시효 이익 포기의 효력이 발생한다.","o":"시효 완성 전이므로 시효이익 포기의 효력은 없다.","src":"기출 2024-24 | 보충(추정)"},{"x":"채무자가 담보 목적의 가등기를 설정하여 주는 것은 채무의 승인에 해당하므로, 그 가등기가 계속되고 있는 동안 그 피담보채권에 대한 소멸시효는 진행하지 않는다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2024-24"},{"x":"소멸시효의 진행이 개시되기 전에 채무자가 승인한 경우, 그 승인에 따라 채권의 소멸시효는 중단된다.","o":"진행 개시 전의 승인은 중단 효력이 없다.","src":"기출 2025-23 | 보충(추정)"},{"x":"후순위 담보권자는 선순위 담보권의 피담보채권의 시효소멸로 직접 이익을 받는 자에 해당하기 때문에 그 피담보채권의 소멸시효 완성을 주장할 수 있다.","o":"직접 이익을 받는 자가 아니어서 주장할 수 없다.","src":"기출 2025-24"},{"x":"부당이득반환채무는 기한의 정함이 없는 채무로서 채권자가 이행을 청구한 때 변제기가 도래하므로 이때부터 소멸시효가 진행한다.","o":"성립한 때부터 진행한다.","src":"기출 2026-23 | 보충(추정)"},{"x":"하자담보책임에 기한 토지 매수인의 손해배상청구권은 제척기간에 걸리므로 소멸시효의 적용이 배제된다.","o":"소멸시효 적용이 배제되지 않는다.","src":"기출 2023-24"},{"x":"금전채무의 이행지체로 발생한 3개월 분의 지연손해금채권은 3년의 단기소멸시효에 걸린다(2026-24 선지 3).","o":"지연손해금은 3년 단기시효가 적용되지 않는다.","src":"기출 2024-22 | 기출 2026-24"}]},"물권법 총론ㆍ물권의 변동(등기 포함)":{"묶음":[{"머리":"물권법정주의와 물권의 객체","줄":[{"t":"물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다. 여기서 ‘법률’에는 규칙이나 지방자치단체의 조례가 포함되지 않는다.","src":"민법 제185조 | 기출 2021-27"},{"t":"온천에 관한 권리는 독립한 물권이 아니다(관습상 물권 아님).","src":"기출 2021-27 | 기출 2025-11"},{"t":"일물일권주의: 특정할 수 있는 집합물(예: 양만장 내 뱀장어 전부)에는 1개의 양도담보권을 설정할 수 있다.","src":"기출 2021-27"},{"t":"사용ㆍ수익권능이 영구적ㆍ대세적으로 포기된 소유권은 특별한 사정이 없는 한 허용될 수 없다.","src":"기출 2021-27"},{"t":"소유권에 기한 물권적 청구권은 소멸시효의 대상이 아니다.","src":"기출 2021-27 | 기출 2023-24 | 기출 2025-27"}]},{"머리":"부동산물권변동","줄":[{"t":"법률행위로 인한 부동산 물권의 득실변경은 등기하여야 효력이 생긴다(성립요건주의). 등기는 효력발생요건이지 효력존속요건이 아니다.","src":"민법 제186조 | 기출 2023-26 | 기출 2025-25"},{"t":"법률의 규정에 의한 부동산 물권 취득(상속, 공용징수, 판결, 경매 기타)은 등기를 요하지 않는다. 그러나 등기를 하지 않으면 처분하지 못한다.","src":"민법 제187조"},{"t":"물권에 관한 등기가 원인 없이 말소되어도 물권의 효력에는 영향이 없다.","src":"기출 2025-25"},{"t":"소유권이전등기명의자는 그 전소유자에 대하여 적법한 등기원인에 의해 소유권을 취득한 것으로 추정된다(등기의 추정력).","src":"기출 2025-25"},{"t":"사망자 명의로 신청하여 이루어진 소유권이전등기는 특별한 사정이 없는 한 원인무효 등기다.","src":"기출 2025-25"},{"t":"동일인 명의로 소유권보존등기가 중복으로 된 경우 특별한 사정이 없는 한 후행 등기가 무효다.","src":"기출 2023-26"},{"t":"소유자의 대리인으로부터 토지를 적법하게 매수하였다면, 이전등기가 위조서류로 마쳐졌더라도 실체관계에 부합하면 등기는 유효하다.","src":"기출 2023-26 | 보충(추정)"},{"t":"무효등기의 유용에 관한 합의는 명시적이 아니어도 묵시적으로 가능하다. 유용 합의 시부터 유효하다.","src":"기출 2023-26 | 기출 2022-12 | 보충(추정)"},{"t":"매매계약이 합의해제된 후 매도인의 등기말소청구권은 소유권에 기한 물권적 청구권이다(채권적 청구권 아님).","src":"기출 2023-26 | 보충(추정)"},{"t":"등기한 토지임차권은 제3자에게 대항할 수 있다. 임차권등기를 하지 않았다고 해서 제3자에게 전혀 대항하지 못하는 것은 아니다(건물 등기 등 별도 대항요건 인정).","src":"민법 제621조(원문 미확인) | 기출 2025-25 | 기출 2022-37"}]},{"머리":"동산물권변동과 혼동","줄":[{"t":"동산 물권의 양도는 인도하여야 효력이 생긴다. 양수인이 이미 점유한 때에는 의사표시만으로 효력이 생긴다(간이인도).","src":"민법 제188조"},{"t":"점유개정: 양도인이 점유를 계속하는 때에는 양수인이 인도받은 것으로 본다. 목적물반환청구권의 양도: 제3자가 점유한 동산은 반환청구권을 양도함으로써 인도한 것으로 본다.","src":"민법 제189조 | 민법 제190조"},{"t":"선의취득: 평온ㆍ공연하게 동산을 양수한 자가 선의이며 과실 없이 점유한 경우 양도인이 정당한 소유자가 아닌 때에도 즉시 소유권을 취득한다. 도품ㆍ유실물은 피해자 또는 유실자가 도난 또는 유실한 날부터 2년 내에 반환을 청구할 수 있다(금전은 제외).","src":"민법 제249조 | 민법 제250조 | 기출 2021-31"},{"t":"혼동: 동일한 물건에 대한 소유권과 다른 물권이 동일한 사람에게 귀속한 때 다른 물권은 소멸한다. 그 물권이 제3자의 권리의 목적이 된 때에는 소멸하지 않는다. 점유권에는 적용하지 않는다.","src":"민법 제191조 | 기출 2026-28"}]},{"머리":"원시취득과 승계취득","줄":[{"t":"원시취득의 예: 건물의 신축, 유실물의 습득(제253조), 무주물의 선점(제252조), 취득시효 완성 후 등기에 의한 소유권 취득, 선의취득.","src":"기출 2022-24 | 기출 2023-13 | 민법 제252조 | 민법 제253조"},{"t":"승계취득(원시취득 아님)의 예: 근저당권 실행을 위한 경매에 의한 소유권 취득, 금원을 대여하면서 채무자 소유 건물에 저당권을 설정받은 경우(설정적 승계).","src":"기출 2022-24 | 기출 2023-13"},{"t":"무주의 동산을 소유의 의사로 점유한 자는 소유권을 취득한다(무주의 부동산은 국유). 유실물은 공고 후 6개월 내 소유자가 권리를 주장하지 않으면 습득자가 소유권을 취득한다. 매장물은 1년 내.","src":"민법 제252조 | 민법 제253조 | 민법 제254조"},{"t":"무주물선점에 의한 소유권 취득은 자주점유인 경우에 인정된다.","src":"기출 2024-26"}]},{"머리":"등기청구권","줄":[{"t":"채권적 청구권인 등기청구권: 매매계약에 기한 매수인의 소유권이전등기청구권, 점유취득시효 완성자의 소유자에 대한 소유권이전등기청구권, 민법 제621조에 의한 임차인의 임대인에 대한 임차권설정등기청구권.","src":"기출 2021-28"},{"t":"물권적 청구권인 등기청구권: 위조서류에 의해 마쳐진 소유권이전등기에 대한 소유자의 말소등기청구권.","src":"기출 2021-28"},{"t":"부동산매매로 인한 소유권이전등기청구권은 특별한 사정이 없는 한 권리의 성질상 양도가 제한되고 양도에 채무자의 승낙이나 동의를 요한다. 양도통지만으로는 채무자에게 대항할 수 없다.","src":"기출 2022-26 | 기출 2026-26"}]},{"머리":"중간생략등기","줄":[{"t":"중간생략등기의 합의가 있어도 중간 매수인 乙의 최초 매도인 甲에 대한 소유권이전등기청구권은 소멸하지 않는다. 甲의 乙에 대한 등기의무도 소멸하지 않는다.","src":"기출 2022-25 | 기출 2026-26"},{"t":"중간생략등기 합의 후 甲과 乙이 매매대금을 인상하기로 약정한 경우 甲은 인상된 대금이 지급되지 않았음을 이유로 丙 명의 이전등기의무의 이행을 거절할 수 있다.","src":"기출 2022-25"},{"t":"토지거래허가구역 내 토지에서 丙이 자신과 甲을 매매 당사자로 하는 토지거래허가를 받아 자신 앞으로 이전등기를 마쳤더라도 그 등기는 무효다.","src":"기출 2022-25"},{"t":"중간생략등기 합의가 없으면 최종 매수인 丙은 乙을 대위하여 甲에게 직접 자신에게 이전등기를 청구할 수 없다(甲의 동의 필요).","src":"기출 2026-26 | 보충(추정)"}]},{"머리":"가등기","줄":[{"t":"가등기 효력: 본등기의 순위 보전 효력만 있다. 본등기가 마쳐져도 물권변동의 효력은 본등기 시에 발생하며 가등기한 때로 소급하지 않는다.","src":"기출 2024-25 | 보충(추정)"},{"t":"가등기가 있다고 해서 소유권이전등기를 청구할 어떤 법률관계가 있다고 추정되지 않는다.","src":"기출 2024-25 | 기출 2025-25"},{"t":"가등기된 소유권이전등기청구권은 타인에게 양도할 수 있다(양도하려면 부기등기).","src":"기출 2024-25 | 보충(추정)"},{"t":"가등기 후 제3자에게 소유권이전등기가 이루어진 경우 가등기권리자는 가등기 당시의 소유명의인에게 본등기를 청구하고 현재 소유명의인에게는 본등기 승낙을 구한다.","src":"기출 2024-25 | 보충(추정)"},{"t":"가등기권리자는 가등기에 기하여 무효인 중복된 소유권보존등기의 말소를 구할 수 없다.","src":"기출 2024-25"},{"t":"담보가등기: 가등기담보법상 채권자가 담보권을 실행하여 소유권을 취득하려면 채권의 변제기 후에 청산금 평가액을 채무자등에게 통지하고, 통지가 도달한 날부터 2개월(청산기간)이 지나야 한다. 청산금이 없다고 인정되는 경우에도 그 뜻을 통지하여야 한다.","src":"가등기담보 등에 관한 법률 제3조"},{"t":"청산금 = 통지 당시 담보목적부동산의 가액 - 채권액. 소유권이전등기를 마친 경우는 청산기간 후 청산금을 지급한 때 소유권을 취득하고, 담보가등기를 마친 경우는 청산기간이 지나야 본등기를 청구할 수 있다. 청산금 지급채무와 소유권이전등기ㆍ인도채무는 동시이행 관계다.","src":"가등기담보 등에 관한 법률 제4조"},{"t":"청산 규정에 어긋나는 특약으로 채무자등에게 불리한 것은 무효다. 단 청산기간이 지난 후의 특약으로 제3자의 권리를 침해하지 않는 것은 유효하다.","src":"가등기담보 등에 관한 법률 제4조 제4항"},{"t":"채무자등: 채무자, 담보가등기목적 부동산의 물상보증인, 담보가등기 후 소유권을 취득한 제3자.","src":"가등기담보 등에 관한 법률 제2조 제2호"},{"t":"법정지상권: 토지와 건물이 동일한 소유자에 속하는 경우 그 토지나 건물에 대하여 담보가등기에 따른 본등기가 행하여진 때 건물 소유를 목적으로 지상권이 설정된 것으로 본다(존속기간과 지료는 법원이 정함). 담보가등기가 된 나대지에 소유자가 건물을 신축한 후 본등기가 되어 소유자가 달라진 경우 관습상 법정지상권은 성립하지 않는다.","src":"가등기담보 등에 관한 법률 제10조 | 기출 2021-26 | 보충(추정)"},{"t":"채무자등은 청산금채권을 변제받을 때까지 채무액을 지급하고 소유권이전등기의 말소를 청구할 수 있다. 단 변제기가 지난 때부터 10년이 지나거나 선의의 제3자가 소유권을 취득한 경우는 제외.","src":"가등기담보 등에 관한 법률 제11조"},{"t":"담보가등기권리자는 선택에 따라 담보권을 실행하거나 경매를 청구할 수 있다. 우선변제는 담보가등기를 저당권으로 보고 가등기를 마친 때 설정등기가 된 것으로 본다. 경매에서 담보가등기권리는 매각으로 소멸한다.","src":"가등기담보 등에 관한 법률 제12조 | 제13조 | 제15조"}]},{"머리":"부동산 실권리자명의 등기에 관한 법률","줄":[{"t":"명의신탁약정은 무효다. 명의신탁약정에 따른 등기로 이루어진 부동산 물권변동도 무효다. 이 무효는 제3자에게 대항하지 못한다.","src":"부동산 실권리자명의 등기에 관한 법률 제4조 제1항ㆍ제3항"},{"t":"예외(계약명의신탁): 부동산 물권을 취득하기 위한 계약에서 명의수탁자가 당사자가 되고 상대방 당사자가 명의신탁약정이 있다는 사실을 알지 못한 경우에는 물권변동이 유효하다.","src":"부동산 실권리자명의 등기에 관한 법률 제4조 제2항"},{"t":"명의신탁약정에서 제외되는 경우: 채무변제 담보를 위한 이전ㆍ가등기, 부동산의 위치와 면적을 특정한 구분소유적 공유 등기, 신탁재산인 사실을 등기한 경우.","src":"부동산 실권리자명의 등기에 관한 법률 제2조 제1호"},{"t":"과징금: 명의신탁자에게 부동산 가액의 100분의 30의 범위에서 부과한다. 벌칙: 명의신탁자는 5년 이하 징역 또는 2억원 이하 벌금, 명의수탁자는 3년 이하 징역 또는 1억원 이하 벌금.","src":"부동산 실권리자명의 등기에 관한 법률 제5조 | 제7조"},{"t":"특례: 종중 보유 부동산을 종중 외의 자 명의로 등기, 배우자 명의 등기, 종교단체 산하 조직의 부동산을 종교단체 명의로 등기한 경우로서 조세 포탈ㆍ강제집행 면탈ㆍ법령상 제한 회피 목적이 아니면 제4조~제7조를 적용하지 않는다.","src":"부동산 실권리자명의 등기에 관한 법률 제8조"},{"t":"계약명의신탁에서 명의신탁자가 부동산을 점유하는 경우 특별한 사정이 없는 한 타주점유다.","src":"기출 2023-27"},{"t":"무효인 명의신탁약정에 의해 명의수탁자 명의 등기가 마쳐진 경우는 불법원인급여에 해당하지 않는다.","src":"기출 2026-39"},{"t":"양도소득세 회피를 목적으로 한 명의신탁약정은 이 법에 의하여 무효가 될 뿐 반사회질서 법률행위가 아니다.","src":"기출 2021-15 | 부동산 실권리자명의 등기에 관한 법률 제4조"}]},{"머리":"물권적 청구권","줄":[{"t":"소유물반환청구권: 소유자는 그 소유에 속한 물건을 점유한 자에 대하여 반환을 청구할 수 있다. 점유자가 점유할 권리가 있으면 반환을 거부할 수 있다.","src":"민법 제213조"},{"t":"소유물방해제거ㆍ방해예방청구권: 소유권을 방해하는 자에 대하여 방해의 제거를 청구할 수 있고, 방해할 염려 있는 행위를 하는 자에 대하여 예방이나 손해배상의 담보를 청구할 수 있다.","src":"민법 제214조 | 기출 2024-27"},{"t":"방해배제청구에서 방해는 현재에도 지속되고 있는 침해를 의미한다. 방해배제는 현재 계속되고 있는 방해의 원인을 제거하는 것을 내용으로 한다.","src":"기출 2025-27 | 기출 2026-25"},{"t":"지상권을 설정한 토지소유자도 불법점유자에 대하여 물권적 청구권을 행사할 수 있다.","src":"기출 2024-27 | 기출 2026-25"},{"t":"현실적으로 점유하고 있지 않은 불법점유자(점유를 이전한 자)를 상대로는 소유물의 인도를 청구할 수 없다.","src":"기출 2024-27 | 기출 2025-27"},{"t":"소유권을 상실한 전소유자는 제3자인 불법점유자에 대하여 소유권에 기한 물권적 청구권을 행사할 수 없다.","src":"기출 2024-27"},{"t":"지역권자는 방해제거ㆍ방해예방을 청구할 수 있으나 승역지의 반환청구는 할 수 없다.","src":"민법 제301조(원문 미확인) | 기출 2024-27"},{"t":"소유권이전등기를 마치지 않은 매수인(미등기 건물의 매수인 포함)은 직접 소유권에 기한 방해제거ㆍ반환청구를 할 수 없다.","src":"기출 2025-27 | 기출 2026-25"},{"t":"건물소유자가 건물의 소유를 통해 타인 소유 토지 전부를 불법점유하는 경우 토지소유자는 건물소유자에게 건물철거를 청구할 수 있다.","src":"기출 2025-27"},{"t":"저당권자는 저당목적물에서 임의로 분리ㆍ반출된 물건을 자신에게 반환하라고 청구할 수 없다(원래 장소로의 반환을 청구).","src":"기출 2026-25 | 보충(추정)"},{"t":"점유물방해제거청구권(제205조 제2항)의 1년은 제척기간으로서 출소기간이다.","src":"민법 제205조 | 기출 2026-25"}]}],"함정":[{"x":"일물일권주의 원칙상 특정 양만장 내의 뱀장어들 전부에 대해서는 1개의 양도담보권을 설정할 수 없다.","o":"특정할 수 있는 집합물에 1개의 양도담보권을 설정할 수 있다.","src":"기출 2021-27"},{"x":"부동산 공유자가 자기 지분을 포기한 경우, 그 지분은 이전등기 없이도 다른 공유자에게 각 지분의 비율로 귀속된다.","o":"이전등기를 하여야 귀속된다.","src":"민법 제267조(원문 미확인) | 기출 2023-25 | 기출 2025-28"},{"x":"등기는 물권의 효력발생요건이자 효력존속요건에 해당한다.","o":"효력발생요건이다. 효력존속요건이 아니다.","src":"기출 2023-26 | 기출 2025-25"},{"x":"매도인이 매수인에게 소유권이전등기를 마친 후 매매계약의 합의해제에 따른 매도인의 등기말소청구권의 법적 성질은 채권적 청구권이다.","o":"물권적 청구권이다.","src":"기출 2023-26 | 보충(추정)"},{"x":"소유자의 대리인으로부터 토지를 적법하게 매수하였더라도 소유권이전등기가 위조된 서류에 의하여 마쳐졌다면 그 등기는 무효이다.","o":"실체관계에 부합하는 등기는 유효하다.","src":"기출 2023-26 | 보충(추정)"},{"x":"무효등기의 유용에 관한 합의는 반드시 명시적으로 이루어져야 한다.","o":"묵시적으로도 가능하다.","src":"기출 2023-26 | 보충(추정)"},{"x":"소유권이전등기청구권 보전을 위한 가등기가 있는 경우, 소유권이전등기를 청구할 어떤 법률관계가 있다고 추정된다.","o":"추정되지 않는다.","src":"기출 2024-25 | 기출 2025-25"},{"x":"가등기된 소유권이전등기청구권은 타인에게 양도될 수 없다.","o":"양도할 수 있다.","src":"기출 2024-25 | 보충(추정)"},{"x":"가등기에 기하여 본등기가 마쳐진 경우, 본등기에 의한 물권변동의 효력은 가등기한 때로 소급하여 발생한다.","o":"본등기 시에 발생한다. 가등기는 순위 보전 효력만 있다.","src":"기출 2024-25 | 보충(추정)"},{"x":"가등기 후에 제3자에게 소유권이전등기가 이루어진 경우, 가등기권리자는 가등기 당시의 소유명의인이 아니라 현재의 소유명의인에게 본등기를 청구하여야 한다.","o":"가등기 당시의 소유명의인에게 본등기를 청구한다.","src":"기출 2024-25 | 보충(추정)"},{"x":"지상권을 설정한 토지소유권자는 그 토지에 대한 불법점유자에 대하여 물권적 청구권을 행사할 수 없다.","o":"행사할 수 있다.","src":"기출 2024-27 | 기출 2026-25"},{"x":"점유를 상실하여 현실적으로 점유하고 있지 아니한 불법점유자에 대하여 소유자는 그 소유물의 인도를 청구할 수 있다.","o":"청구할 수 없다.","src":"기출 2024-27 | 기출 2025-27"},{"x":"소유권을 상실한 전(前)소유자가 그 물건의 양수인에게 인도의무를 부담하는 경우, 제3자인 불법점유자에 대하여 소유권에 기한 물권적 청구권을 행사할 수 있다.","o":"행사할 수 없다.","src":"기출 2024-27"},{"x":"지역권자는 지역권의 행사를 방해하는 자에게 승역지의 반환청구를 할 수 있다.","o":"반환청구권은 없고 방해제거ㆍ방해예방만 청구할 수 있다.","src":"기출 2024-27"},{"x":"불법점유자가 물건을 다른 사람에게 인도하여 현실적으로 점유를 하고 있지 않더라도 소유자는 그 불법점유자를 상대로 그 소유물의 인도청구를 할 수 있다.","o":"청구할 수 없다.","src":"기출 2025-27"},{"x":"저당권자는 저당목적물에서 임의로 분리ㆍ반출된 물건을 자신에게 반환할 것을 청구할 수 있다.","o":"원래 자리로의 반환을 청구할 수 있을 뿐이다.","src":"기출 2026-25 | 보충(추정)"},{"x":"甲ㆍ乙ㆍ丙 사이에 중간생략등기의 합의가 있는 경우, 甲의 乙에 대한 등기의무는 소멸한다(2022-25 ㄱ, 2026-26 ㄱ).","o":"소멸하지 않는다.","src":"기출 2022-25 | 기출 2026-26"},{"x":"甲ㆍ乙ㆍ丙 사이에 중간생략등기의 합의가 없더라도, 丙은 乙을 대위하여 甲을 상대로 직접 자신에게 소유권이전등기를 할 것을 청구할 수 있다(2026-26 ㄴ).","o":"합의가 없으면 청구할 수 없다.","src":"기출 2026-26 | 보충(추정)"},{"x":"乙이 甲에게 갖는 소유권이전등기청구권을 丙에게 양도한 경우, 乙의 甲에 대한 그 등기청구권의 양도 통지만으로도 丙은 甲에게 대항할 수 있다(2026-26 ㄷ).","o":"양도에 채무자의 동의나 승낙이 필요하다.","src":"기출 2022-26 | 기출 2026-26"},{"x":"근저당권 실행을 위한 경매에 의한 소유권 취득은 원시취득이다(2022-24 선지 5 - 원시취득이 아닌 것으로 출제).","o":"승계취득이다.","src":"기출 2022-24"},{"x":"금원을 대여하면서 채무자 소유의 건물에 저당권을 설정받은 경우는 권리의 원시취득이다(2023-13 ㄴ).","o":"설정적 승계취득이다.","src":"기출 2023-13"}]},"점유권ㆍ소유권(취득시효ㆍ공유ㆍ상린관계)":{"묶음":[{"머리":"점유권의 취득과 소멸","줄":[{"t":"점유권의 취득: 물건을 사실상 지배하는 자는 점유권이 있다. 사실상의 지배를 상실하면 소멸한다. 단 점유회수의 소(제204조)로 점유를 회수한 때에는 소멸하지 않는다.","src":"민법 제192조"},{"t":"점유권은 상속인에게 이전된다. 점유권의 양도는 점유물의 인도로 효력이 생긴다(간이인도, 점유개정, 목적물반환청구권 양도 준용).","src":"민법 제193조 | 민법 제196조"},{"t":"간접점유: 지상권ㆍ전세권ㆍ질권ㆍ사용대차ㆍ임대차ㆍ임치 기타의 관계로 타인으로 하여금 물건을 점유하게 한 자는 간접으로 점유권이 있다. 점유매개관계가 있어야 한다.","src":"민법 제194조 | 기출 2023-27"},{"t":"점유보조자: 가사상ㆍ영업상 기타 유사한 관계에 의하여 타인의 지시를 받아 물건을 사실상 지배하는 때에는 그 타인만을 점유자로 한다.","src":"민법 제195조"},{"t":"준점유: 점유권 규정은 재산권을 사실상 행사하는 경우에 준용한다.","src":"민법 제210조"}]},{"머리":"점유의 태양과 추정","줄":[{"t":"점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정한다. 선의의 점유자라도 본권에 관한 소에 패소한 때에는 소가 제기된 때부터 악의의 점유자로 본다.","src":"민법 제197조"},{"t":"전후 양시에 점유한 사실이 있으면 점유는 계속한 것으로 추정한다.","src":"민법 제198조"},{"t":"점유의 승계: 점유자의 승계인은 자기의 점유만을 주장하거나 자기의 점유와 전점유자의 점유를 아울러 주장할 수 있다. 아울러 주장하면 하자도 계승한다.","src":"민법 제199조 | 기출 2022-27"},{"t":"매매 등으로 점유를 승계한 경우 전 점유자의 점유가 타주점유여도 현 점유자가 자기의 점유만을 주장하면 현 점유자의 점유는 자주점유로 추정된다.","src":"기출 2022-27"},{"t":"점유자가 행사하는 권리는 적법하게 보유한 것으로 추정한다.","src":"민법 제200조"},{"t":"자주점유: 소유자와 동일한 지배를 사실상 행사하려는 의사(사실상 소유할 의사)를 가지고 하는 점유. 점유취득의 원인이 된 권원의 성질이나 점유와 관계있는 모든 사정에 의하여 외형적ㆍ객관적으로 결정한다.","src":"기출 2022-27 | 기출 2024-26 | 기출 2025-26"},{"t":"자주점유의 추정: 점유자가 주장한 매매 등 점유권원이 인정되지 않는다는 사유만으로는 번복되지 않는다. 국가나 지방자치단체가 점유하는 경우에도 적용된다.","src":"기출 2021-25 | 기출 2022-27 | 기출 2025-26"},{"t":"매매계약이 무효가 되는 사정을 알지 못하고 부동산을 매수한 자의 점유는 후일 매매가 무효로 되어도 자주점유가 타주점유로 변하지 않는다.","src":"기출 2024-26"},{"t":"타주점유의 예: 타인의 물건을 관리하기 위한 점유, 계약명의신탁의 명의신탁자 점유, 공유자 1인이 공유부동산 전부를 점유할 때 다른 공유자 지분비율 범위의 점유, 무허가건물 부지가 타인 소유임을 알면서 건물만 매수한 자의 그 부지 점유.","src":"기출 2023-27 | 기출 2024-26 | 기출 2025-26"},{"t":"타주점유자가 자기 명의로 소유권보존등기나 이전등기를 마친 것만으로는 소유의 의사를 표시한 것이 아니므로 자주점유로 전환되지 않는다. 점유시킨 자에 대한 소유의사 표시 또는 새 권원이 있어야 한다.","src":"기출 2024-26 | 기출 2025-26"}]},{"머리":"점유자와 회복자의 관계","줄":[{"t":"과실: 선의의 점유자는 점유물의 과실을 취득한다. 악의의 점유자는 수취한 과실을 반환하고 소비ㆍ훼손하거나 수취하지 못한 경우 그 대가를 보상한다. 폭력 또는 은비에 의한 점유자에 준용한다.","src":"민법 제201조"},{"t":"책임: 점유물이 점유자의 책임 있는 사유로 멸실ㆍ훼손된 때 악의의 점유자는 손해 전부를 배상하고, 선의의 점유자는 이익이 현존하는 한도에서 배상한다. 소유의 의사가 없는 점유자(타주점유자)는 선의인 경우에도 손해 전부를 배상한다.","src":"민법 제202조 | 기출 2023-27"},{"t":"상환청구: 점유자가 점유물을 반환할 때 점유물을 보존하기 위하여 지출한 필요비 상환을 청구할 수 있다. 점유자가 과실을 취득한 경우 통상의 필요비는 청구하지 못한다. 유익비는 가액의 증가가 현존한 경우에 한하여 회복자의 선택에 좇아 지출금액이나 증가액의 상환을 청구할 수 있고, 법원은 회복자의 청구에 의하여 상당한 상환기간을 허여할 수 있다.","src":"민법 제203조"},{"t":"점유자의 유익비상환청구권은 형성권이 아니라 청구권이다.","src":"민법 제203조 | 기출 2021-4 | 기출 2024-2"}]},{"머리":"점유보호청구권(점유의 소)","줄":[{"t":"점유회수: 점유의 침탈을 당한 때 물건의 반환 및 손해배상을 청구할 수 있다. 침탈자의 특별승계인에 대하여는 행사하지 못하나 승계인이 악의이면 가능. 침탈을 당한 날부터 1년 내에 행사한다.","src":"민법 제204조"},{"t":"점유보유: 점유의 방해를 받은 때 방해의 제거 및 손해배상을 청구할 수 있다. 방해가 종료한 날부터 1년 내에 행사한다. 공사로 인한 방해는 공사착수 후 1년이 경과하거나 공사가 완성한 때에는 방해제거를 청구하지 못한다. 이 1년은 제척기간이며 출소기간이다.","src":"민법 제205조 | 기출 2026-25"},{"t":"점유보전: 방해를 받을 염려가 있는 때 방해의 예방 또는 손해배상의 담보를 청구할 수 있다.","src":"민법 제206조"},{"t":"간접점유자도 점유보호 청구권을 행사할 수 있다. 점유자가 침탈당한 경우 간접점유자는 점유자에게 반환할 것을 청구하거나 점유자가 받을 수 없거나 원하지 않으면 자기에게 반환할 것을 청구할 수 있다.","src":"민법 제207조"},{"t":"점유권에 기인한 소와 본권에 기인한 소는 서로 영향을 미치지 않는다. 점유권에 기인한 소는 본권에 관한 이유로 재판하지 못한다.","src":"민법 제208조"},{"t":"자력구제: 점유자는 부정한 침탈 또는 방해에 대하여 자력으로 방위할 수 있다. 침탈된 물건이 부동산이면 침탈 후 직시 가해자를 배제하여 탈환할 수 있고, 동산이면 현장에서 또는 추적하여 탈환할 수 있다.","src":"민법 제209조"}]},{"머리":"소유권의 범위","줄":[{"t":"소유권의 내용: 소유자는 법률의 범위 내에서 소유물을 사용, 수익, 처분할 권리가 있다.","src":"민법 제211조"},{"t":"토지소유권의 범위: 정당한 이익 있는 범위 내에서 토지의 상하에 미친다. 지중의 지하수는 포함된다. 지상권자가 식재한 수목, 완성된 미등기건물, 바다는 토지소유권의 범위에 포함되지 않는다.","src":"민법 제212조 | 기출 2021-5"},{"t":"건물의 구분소유: 수인이 한 채의 건물을 구분하여 각각 일부분을 소유한 때 건물과 그 부속물 중 공용하는 부분은 공유로 추정한다. 공용부분의 보존 비용 기타 부담은 각자의 소유부분의 가액에 비례하여 분담한다.","src":"민법 제215조"},{"t":"미등기건물을 양수하여 사실상의 처분권을 가진 자는 토지소유자에 대하여 건물부지의 점유ㆍ사용에 따른 부당이득반환의무를 진다. 건물에 유치권을 행사하는 자는 건물 부지를 점유하는 자에 해당하지 않는다.","src":"기출 2023-27"}]},{"머리":"상린관계","줄":[{"t":"인지사용청구권: 경계나 그 근방에서 담 또는 건물을 축조ㆍ수선하기 위하여 필요한 범위 내에서 이웃 토지의 사용을 청구할 수 있다. 이웃 사람의 승낙이 없으면 주거에 들어가지 못한다. 손해가 있으면 보상을 청구할 수 있다.","src":"민법 제216조"},{"t":"매연 등 방해금지: 토지소유자는 매연, 열기체, 액체, 음향, 진동 기타 유사한 것으로 이웃 토지의 사용을 방해하거나 이웃 거주자의 생활에 고통을 주지 않도록 적당한 조처를 할 의무가 있다. 이웃 거주자는 이웃 토지의 통상의 용도에 적당한 것이면 인용할 의무가 있다.","src":"민법 제217조"},{"t":"소음이 사회통념상 수인한도를 넘지 않으면 소유권에 기하여 소음피해의 제거를 청구할 수 없다.","src":"민법 제217조 | 기출 2025-29"},{"t":"수도 등 시설권: 타인의 토지를 통과하지 않으면 필요한 수도ㆍ소수관ㆍ가스관ㆍ전선 등을 시설할 수 없거나 과다한 비용을 요하는 경우 타인의 토지를 통과해 시설할 수 있다. 손해가 가장 적은 장소와 방법을 선택하고 요청에 의해 손해를 보상한다. 사정 변경 시 타토지 소유자는 시설변경을 청구할 수 있고 비용은 토지소유자가 부담한다.","src":"민법 제218조"},{"t":"주위토지통행권: 공로와의 사이에 용도에 필요한 통로가 없는 경우 주위토지를 통행하거나 통로를 개설할 수 있다. 손해가 가장 적은 장소와 방법을 선택하고 통행지 소유자의 손해를 보상하여야 한다.","src":"민법 제219조"},{"t":"분할ㆍ일부양도로 공로에 통하지 못하게 된 토지의 소유자는 다른 분할자(양수인ㆍ양도인)의 토지를 통행할 수 있고 보상의 의무가 없다.","src":"민법 제220조 | 기출 2025-29"},{"t":"자연유수의 승수의무: 토지소유자는 이웃 토지로부터 자연히 흘러오는 물을 막지 못한다. 고지소유자는 이웃 저지에서 필요한 물을 정당한 사용범위를 넘어 막지 못한다. 승수의무에는 적극적으로 자연유수의 소통을 유지할 의무가 포함되지 않는다.","src":"민법 제221조 | 기출 2025-29"},{"t":"소통공사권: 흐르는 물이 저지에서 폐색된 때 고지소유자는 자비로 소통에 필요한 공사를 할 수 있다. 공작물의 파손ㆍ폐색으로 타인 토지에 손해 염려가 있으면 타인은 보수ㆍ소통ㆍ예방에 필요한 청구를 할 수 있다.","src":"민법 제222조 | 민법 제223조"},{"t":"처마물 시설의무: 처마물이 이웃에 직접 낙하하지 않도록 적당한 시설을 하여야 한다.","src":"민법 제225조"},{"t":"여수소통권: 고지소유자는 침수지 건조 또는 가용ㆍ농ㆍ공업용 여수를 소통하기 위하여 공로ㆍ공류 또는 하수도에 달하기까지 저지에 물을 통과하게 할 수 있다(손해 최소 + 보상).","src":"민법 제226조"},{"t":"유수용 공작물의 사용권: 소유지의 물을 소통하기 위하여 이웃 토지소유자가 시설한 공작물을 사용할 수 있다. 이익 비율로 설치ㆍ보존 비용을 분담한다. 여수급여청구권: 물을 얻기 곤란한 때 보상하고 여수의 급여를 청구할 수 있다.","src":"민법 제227조 | 민법 제228조"},{"t":"수류의 변경: 구거 기타 수류지의 소유자는 대안의 토지가 타인 소유이면 수로나 수류의 폭을 변경하지 못한다. 양안이 수류지 소유자의 소유이면 변경할 수 있으나 하류는 자연의 수로와 일치하여야 한다.","src":"민법 제229조"},{"t":"경계표ㆍ담의 설치: 인접 토지소유자는 공동비용으로 통상의 경계표나 담을 설치할 수 있다. 비용은 쌍방이 절반하여 부담하되 측량비용은 면적에 비례한다.","src":"민법 제237조"},{"t":"담의 특수시설권: 자기 비용으로 담의 재료를 통상보다 양호하게 하거나 높이를 높게 하거나 방화벽 기타 특수시설을 할 수 있다.","src":"민법 제238조"},{"t":"경계표ㆍ담ㆍ구거 등은 상린자의 공유로 추정한다. 상린자 일방의 단독비용으로 설치되었거나 담이 건물의 일부인 경우는 제외. 이 공유물에는 분할청구 금지 기간 규정이 적용되지 않고 분할을 청구하지 못한다.","src":"민법 제239조 | 민법 제268조 제3항 | 기출 2025-29"},{"t":"수지ㆍ목근 제거: 인접지 수목 가지가 경계를 넘으면 그 소유자에 대하여 가지의 제거를 청구할 수 있고, 응하지 않으면 청구자가 제거할 수 있다. 뿌리가 경계를 넘으면 임의로 제거할 수 있다.","src":"민법 제240조"},{"t":"심굴금지: 인접지의 지반이 붕괴할 정도로 자기 토지를 심굴하지 못한다. 충분한 방어공사를 한 때는 제외.","src":"민법 제241조"},{"t":"경계선 부근 건축: 특별한 관습이 없으면 경계로부터 반 미터 이상의 거리를 두어야 한다. 위반 시 건물의 변경이나 철거를 청구할 수 있으나 건축 착수 후 1년이 경과하거나 건물이 완성된 후에는 손해배상만 청구할 수 있다.","src":"민법 제242조"},{"t":"차면시설: 경계로부터 2미터 이내의 거리에서 이웃 주택의 내부를 관망할 수 있는 창이나 마루를 설치하는 경우 적당한 차면시설을 하여야 한다.","src":"민법 제243조"},{"t":"지하시설: 우물을 파거나 용수ㆍ하수ㆍ오물 저치 지하시설은 경계로부터 2미터 이상, 저수지ㆍ구거ㆍ지하실 공사는 경계로부터 그 깊이의 반 이상의 거리를 둔다.","src":"민법 제244조"}]},{"머리":"취득시효(점유취득시효)","줄":[{"t":"부동산 취득시효 ① 20년간 소유의 의사로 평온ㆍ공연하게 부동산을 점유하는 자는 등기함으로써 소유권을 취득한다. ② 부동산 소유자로 등기한 자가 10년간 소유의 의사로 평온ㆍ공연하게 선의이며 과실 없이 점유한 때 소유권을 취득한다(등기부취득시효).","src":"민법 제245조"},{"t":"동산 취득시효: 10년간 소유의 의사로 평온ㆍ공연하게 점유하면 소유권 취득. 선의이며 과실 없이 개시한 경우 5년.","src":"민법 제246조"},{"t":"취득시효의 효력은 점유를 개시한 때에 소급한다. 소멸시효 중단 규정이 준용된다. 소유권 이외의 재산권에도 준용한다.","src":"민법 제247조 | 민법 제248조 | 기출 2023-25"},{"t":"점유취득시효 완성자는 시효 완성 당시 소유자에 대하여 채권적 등기청구권을 가진다. 등기를 마치기 전에는 소유권을 취득하지 못한다.","src":"민법 제245조 | 기출 2023-28"},{"t":"1필의 토지의 일부에 대한 시효취득도 인정될 수 있다. 성명불상자의 소유물에 대해서도 시효취득이 인정된다.","src":"기출 2026-27"},{"t":"취득시효기간 중 계속해서 등기명의자가 동일한 경우 점유개시 후 임의의 시점을 시효기간의 기산점으로 삼을 수 있다.","src":"기출 2021-25 | 기출 2023-28"},{"t":"부동산에 대한 압류 또는 가압류는 취득시효의 중단사유가 아니다.","src":"기출 2023-28 | 기출 2026-27"},{"t":"시효완성 당시에는 일반재산이었으나 완성 후 행정재산으로 변경된 경우 국가를 상대로 시효완성을 원인으로 한 소유권이전등기를 청구할 수 없다.","src":"기출 2021-25 | 기출 2026-27"},{"t":"시효 완성 후 등기 전에 소유자가 저당권을 설정한 경우 시효완성자는 저당권의 부담 있는 소유권을 취득한다.","src":"기출 2021-25 | 보충(추정)"},{"t":"시효완성을 알고 있는 소유자가 부동산을 선의의 제3자에게 처분하여 이전등기를 마친 경우 소유자는 시효완성자에게 불법행위로 인한 손해배상책임을 진다(채무불이행 아님).","src":"기출 2021-25 | 기출 2023-28"},{"t":"시효완성 당시의 소유자는 시효완성자가 등기를 마치지 않았더라도 부동산의 점유로 인한 부당이득반환 청구나 불법점유임을 이유로 한 인도 청구를 할 수 없다. 시효완성자가 등기이전을 청구하더라도 점유로 인한 부당이득반환의무를 지지 않는다.","src":"기출 2022-28 | 기출 2023-28"},{"t":"시효이익의 포기는 특별한 사정이 없는 한 시효완성 당시의 진정한 소유자에 대하여 하여야 한다. 원인무효 등기의 등기부상 소유명의자에게 한 포기는 효력이 없다.","src":"기출 2022-28 | 기출 2026-27"},{"t":"점유자가 시효완성 후 점유를 상실하였더라도 시효이익의 포기로 볼 수 있는 경우가 아닌 한 이미 취득한 소유권이전등기청구권이 즉시 소멸하지 않는다.","src":"기출 2022-28"},{"t":"시효완성 당시의 점유자로부터 점유를 양수한 현 점유자는 전 점유자의 시효완성 효과를 주장하여 직접 자기에게 소유권이전등기를 청구할 수 없다(전 점유자의 청구권을 대위·양도받아야 함).","src":"기출 2022-28"}]},{"머리":"공유","줄":[{"t":"공유: 물건이 지분에 의하여 수인의 소유로 된 때. 공유자의 지분은 균등한 것으로 추정한다.","src":"민법 제262조 | 기출 2025-28"},{"t":"공유자는 그 지분을 처분할 수 있고(다른 공유자의 동의 불요) 공유물 전부를 지분의 비율로 사용ㆍ수익할 수 있다. 지분을 담보로 제공하는 데도 다른 공유자의 동의가 필요하지 않다.","src":"민법 제263조 | 기출 2024-28"},{"t":"공유물의 처분ㆍ변경은 다른 공유자의 동의가 있어야 한다. 관리에 관한 사항은 지분의 과반수로 결정한다. 보존행위는 각자 할 수 있다.","src":"민법 제264조 | 민법 제265조"},{"t":"공유물의 부담: 지분의 비율로 관리비용 기타 의무를 부담한다. 1년 이상 의무이행을 지체한 때 다른 공유자는 상당한 가액으로 그 지분을 매수할 수 있다.","src":"민법 제266조 | 기출 2024-28"},{"t":"지분포기 등: 공유자가 지분을 포기하거나 상속인 없이 사망한 때 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다. 부동산은 지분포기에 따른 다른 공유자 앞 이전등기를 하여야 귀속된다.","src":"민법 제267조 | 기출 2023-25 | 기출 2025-28"},{"t":"공유물분할청구: 공유자는 공유물의 분할을 청구할 수 있다. 5년 내의 기간으로 분할하지 않을 것을 약정할 수 있고, 갱신한 때 그 기간은 갱신한 날부터 5년을 넘지 못한다. 제215조, 제239조의 공유물에는 적용하지 않는다.","src":"민법 제268조"},{"t":"분할의 방법: 협의가 성립되지 않으면 법원에 분할을 청구할 수 있다. 현물로 분할할 수 없거나 분할로 현저히 가액이 감손될 염려가 있으면 법원은 경매를 명할 수 있다. 법원은 청구자가 요구한 분할방법에 구애받지 않고 지분 비율에 따라 합리적으로 분할할 수 있다.","src":"민법 제269조 | 기출 2023-29"},{"t":"분할로 인한 담보책임: 공유자는 다른 공유자가 분할로 취득한 물건에 대하여 지분 비율로 매도인과 동일한 담보책임이 있다.","src":"민법 제270조"},{"t":"공유물분할의 조정절차에서 협의에 의하여 조정조서가 작성되더라도 그 즉시 공유관계가 소멸하지는 않는다.","src":"기출 2023-25"},{"t":"공유물의 독점 사용: 공유자 중 1인이 협의 없이 공유물 전부를 독점 점유ㆍ사용하는 경우 다른 공유자는 자신의 공유지분권에 기초하여 방해배제를 청구할 수 있고 지분에 상응하는 부당이득반환을 청구할 수 있다. 보존행위로서 인도를 청구할 수는 없다.","src":"기출 2022-31"},{"t":"소수지분권자가 협의 없이 공유물 일부를 독점 사용하는 경우 다른 소수지분권자는 보존행위로서 공유물의 인도를 청구할 수 없다.","src":"기출 2023-29 | 기출 2024-28"},{"t":"공유물을 단독으로 점유하는 소수지분권자는 공유물관리를 위한 과반수지분권자의 공유물 인도청구를 공유물의 사용ㆍ수익권으로 거부할 수 없다.","src":"기출 2025-28"},{"t":"공유자들이 공유물의 무단점유자에게 가지는 차임 상당의 부당이득반환채권은 특별한 사정이 없는 한 가분채권이다(지분 비율로 각자 행사).","src":"기출 2023-29 | 기출 2024-28"},{"t":"공유자 1인이 공유물을 무단 임대하고 보증금을 수령한 경우 다른 공유자는 지분비율에 상응하는 임료 상당 부당이득의 반환을 청구할 수 있으나 보증금 자체의 지분 비율 반환을 청구할 수 있는 것은 아니다.","src":"기출 2023-29 | 보충(추정)"},{"t":"구분소유적 공유의 성립을 주장하는 자는 구분소유 약정의 대상이 되는 토지의 위치와 면적을 모두 증명하여야 한다.","src":"기출 2023-29"},{"t":"공유자 중 1인이 다른 공유자의 동의 없이 공유 토지의 특정부분을 매도하여 타인 명의로 이전등기가 마쳐졌다면 그 등기는 공유자의 지분 범위에서 유효하다.","src":"기출 2024-28"},{"t":"과반수 지분의 공유자로부터 사용ㆍ수익을 허락받은 제3자의 점유에 대해 소수지분권자는 부당이득반환을 청구할 수 없다.","src":"기출 2022-39"}]}],"함정":[{"x":"취득시효 완성 후 그로 인한 등기 전에 소유자가 저당권을 설정한 경우, 특별한 사정이 없는 한 시효완성자는 등기를 함으로써 저당권의 부담이 없는 소유권을 취득한다.","o":"저당권의 부담이 있는 소유권을 취득한다.","src":"기출 2021-25 | 보충(추정)"},{"x":"부동산의 점유자가 지적공부 등의 관리주체인 국가나 지방자치단체인 경우에는 자주점유로 추정되지 않는다.","o":"국가나 지방자치단체가 점유하는 경우에도 자주점유로 추정된다.","src":"기출 2022-27 | 기출 2025-26"},{"x":"시효완성자의 시효이익의 포기는 특별한 사정이 없는 한 시효완성 당시의 원인무효인 등기의 등기부상 소유명의자에게 하여도 그 효력이 있다.","o":"진정한 소유자에게 하여야 한다.","src":"기출 2022-28 | 기출 2026-27"},{"x":"선의의 타주점유자는 자신에게 책임있는 사유로 점유물이 멸실되더라도 현존이익의 범위에서만 손해배상책임을 진다.","o":"소유의 의사가 없는 점유자는 선의여도 손해 전부를 배상한다.","src":"민법 제202조 | 기출 2023-27"},{"x":"시효완성 후 그에 따른 소유권이전등기 전에 소유자가 부동산을 처분하면 시효완성자에 대하여 채무불이행책임을 진다.","o":"불법행위책임을 진다(선의 제3자가 이전등기를 마친 경우).","src":"기출 2023-28 | 기출 2021-25"},{"x":"공유자 1인이 무단으로 공유물을 임대하고 보증금을 수령한 경우, 다른 공유자에게 지분비율에 상응하는 보증금액을 부당이득으로 반환하여야 한다.","o":"임료 상당 부당이득의 지분 비율 반환 문제이고, 보증금액의 지분 반환이 아니다.","src":"기출 2023-29 | 보충(추정)"},{"x":"공유자들이 공유물의 무단점유자에게 가지는 차임 상당의 부당이득반환채권은 특별한 사정이 없는 한 불가분채권에 해당한다.","o":"가분채권이다.","src":"기출 2023-29 | 기출 2024-28"},{"x":"공유물의 소수지분권자가 다른 공유자와 협의 없이 공유물의 일부를 독점적으로 사용하는 경우, 다른 소수지분권자는 공유물에 대한 보존행위로서 공유물의 인도를 청구할 수 있다.","o":"보존행위로서 인도를 청구할 수 없다.","src":"기출 2023-29 | 기출 2024-28"},{"x":"구분소유적 공유관계의 성립을 주장하는 자는 구분소유 약정의 대상이 되는 해당 토지의 위치를 증명하면 족하고, 그 면적까지 증명할 필요는 없다.","o":"위치와 면적을 모두 증명하여야 한다.","src":"기출 2023-29"},{"x":"매매계약이 무효가 되는 사정이 있음을 알지 못하고 부동산을 매수한 자의 점유는 후일 그 매매가 무효로 되면 그 점유의 성질이 타주점유로 변한다.","o":"자주점유가 유지된다.","src":"기출 2024-26"},{"x":"공유자 중 1인이 다른 공유자의 동의없이 그 공유 토지의 특정부분을 매도하여 타인 명의로 소유권이전등기가 마쳐졌다면 그 등기는 전부무효이다.","o":"공유자의 지분 범위에서 유효하다.","src":"기출 2024-28"},{"x":"타인의 물건을 관리하기 위하여 한 점유는 점유권원의 성질상 자주점유이다.","o":"타주점유다.","src":"기출 2025-26"},{"x":"토지 주변의 소음이 사회통념상 수인한도를 넘지 않은 경우에도 그 토지소유자는 소유권에 기하여 소음피해의 제거를 청구할 수 있다.","o":"수인한도를 넘어야 청구할 수 있다.","src":"기출 2025-29"},{"x":"토지소유자가 부담하는 자연유수의 승수의무(承水義務)에는 적극적으로 그 자연유수의 소통을 유지할 의무가 포함된다.","o":"포함되지 않는다.","src":"기출 2025-29"},{"x":"경계에 설치된 담이 상린자의 공유인 경우, 상린자는 공유를 이유로 공유물 분할을 청구할 수 있다(2025-29 ㄷ의 반대).","o":"공유물 분할을 청구하지 못한다(제268조 제3항).","src":"민법 제268조 | 기출 2025-29"},{"x":"취득시효 목적물이 가압류되면 취득시효의 진행은 중단된다.","o":"중단사유가 아니다.","src":"기출 2026-27"},{"x":"지상권자가 식재한 수목, 완성된 미등기건물, 바다는 토지소유권의 범위에 포함된다(2021-5 선지).","o":"지중의 지하수가 토지소유권의 범위에 포함된다.","src":"기출 2021-5"}]},"용익물권(지상권ㆍ지역권ㆍ전세권)":{"묶음":[{"머리":"지상권의 내용과 존속기간","줄":[{"t":"지상권: 타인의 토지에 건물 기타 공작물이나 수목을 소유하기 위하여 그 토지를 사용하는 권리다. 지료는 요소가 아니라 지료 없는 지상권도 인정된다.","src":"민법 제279조 | 기출 2024-29"},{"t":"약정 존속기간의 최단기: ① 석조ㆍ석회조ㆍ연와조 또는 이와 유사한 견고한 건물이나 수목의 소유 목적 30년 ② 그 외 건물 소유 목적 15년 ③ 건물 이외의 공작물 소유 목적 5년. 더 짧게 정하면 위 기간까지 연장된다.","src":"민법 제280조"},{"t":"존속기간을 정하지 않은 때: 위 최단존속기간으로 한다. 공작물의 종류와 구조를 정하지 않으면 제280조 제2호(15년)의 건물 소유 목적으로 본다.","src":"민법 제281조"},{"t":"석조 건물 소유를 목적으로 하는 지상권의 존속기간은 ‘최장 30년으로 제한’되는 것이 아니라 최단 30년이다.","src":"민법 제280조 | 기출 2026-28"},{"t":"기존 건물의 소유를 목적으로 설정된 지상권은 건물이 멸실되어도 소멸하지 않는다.","src":"기출 2026-28 | 보충(추정)"},{"t":"지상권의 양도ㆍ임대: 지상권자는 타인에게 그 권리를 양도하거나 존속기간 내에서 토지를 임대할 수 있다(설정자의 동의 불요). 지상권자는 지상물과 지상권을 분리하여 처분할 수 있다(지상권을 유보하고 지상물만 양도, 지상물을 유보하고 지상권만 양도 모두 가능).","src":"민법 제282조 | 기출 2021-26 | 기출 2024-29"},{"t":"지료증감청구권: 지료가 토지에 관한 조세 기타 부담의 증감이나 지가의 변동으로 상당하지 아니하게 된 때 당사자는 증감을 청구할 수 있다.","src":"민법 제286조"},{"t":"지상권소멸청구: 지상권자가 2년 이상의 지료를 지급하지 아니한 때 지상권설정자는 지상권의 소멸을 청구할 수 있다. 지상권이 저당권의 목적이거나 지상 건물ㆍ수목이 저당권의 목적인 경우 저당권자에게 통지한 후 상당한 기간이 경과해야 효력이 생긴다.","src":"민법 제287조 | 민법 제288조"},{"t":"강행규정: 제280조~제287조에 위반되는 계약으로 지상권자에게 불리한 것은 효력이 없다.","src":"민법 제289조"},{"t":"구분지상권: 지하 또는 지상의 공간을 상하의 범위를 정하여 ‘건물 기타 공작물’을 소유하기 위한 지상권의 목적으로 할 수 있다(수목 소유를 위한 구분지상권은 인정되지 않는다). 제3자가 토지를 사용ㆍ수익할 권리를 가진 때에도 그 권리자 및 그 권리를 목적으로 하는 권리를 가진 자 전원의 승낙이 있으면 설정할 수 있다(임차권이 설정된 토지에는 임차권자의 승낙 필요).","src":"민법 제289조의2 | 기출 2024-29 | 기출 2026-28"}]},{"머리":"지상권의 소멸","줄":[{"t":"갱신청구권ㆍ매수청구권: 지상권이 소멸한 경우 건물 기타 공작물이나 수목이 현존한 때 지상권자는 계약의 갱신을 청구할 수 있다(청구권). 설정자가 갱신을 원하지 않으면 지상권자는 상당한 가액으로 지상물의 매수를 청구할 수 있다(형성권).","src":"민법 제283조 | 기출 2026-28 | 기출 2021-4"},{"t":"지상권의 법정갱신은 인정되지 않는다. 갱신 시 존속기간은 갱신한 날부터 최단존속기간보다 단축하지 못한다.","src":"민법 제283조 | 민법 제284조 | 기출 2024-29"},{"t":"수거의무: 지상권이 소멸한 때 지상권자는 지상물을 수거하여 토지를 원상에 회복하여야 한다. 설정자가 상당한 가액을 제공하여 매수를 청구하면 지상권자는 정당한 이유 없이 거절하지 못한다.","src":"민법 제285조"},{"t":"지료연체를 이유로 한 지상권 소멸청구에 의해 지상권이 소멸한 경우 지상권자는 지상물매수청구권을 행사할 수 없다.","src":"기출 2021-26"},{"t":"지상권에 저당권을 설정해 준 지상권자가 토지를 매수해도 혼동으로 지상권이 소멸하지 않는다(제3자의 권리의 목적이므로).","src":"민법 제191조 제1항 | 기출 2026-28"},{"t":"나대지에 저당권을 설정하면서 담보가치 유지를 위해 설정한 무상의 지상권(담보지상권)은 피담보채권이 시효로 소멸하면 소멸한다. 제3자가 대지를 무단점유한 것만으로 지상권자는 특별한 사정이 없는 한 손해배상을 청구할 수 없다.","src":"기출 2021-26 | 기출 2023-30"},{"t":"지상권 설정계약은 채권행위이므로 토지소유자가 아닌 자도 체결할 수 있다(처분권한은 설정등기 단계의 문제).","src":"기출 2023-30 | 보충(추정)"},{"t":"분묘기지권을 시효로 취득한 자는 토지소유자가 지료를 청구한 날부터 지료지급의무가 있다.","src":"기출 2023-30"}]},{"머리":"법정지상권ㆍ관습법상 법정지상권","줄":[{"t":"저당권 실행에 의한 법정지상권: 저당물의 경매로 토지와 지상 건물이 다른 소유자에 속하게 된 때 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 지료는 당사자의 청구에 의하여 법원이 정한다.","src":"민법 제366조"},{"t":"전세권의 법정지상권: 대지와 건물이 동일한 소유자에 속하는 경우 건물에 전세권을 설정한 때 대지 소유권의 특별승계인은 전세권설정자에 대하여 지상권을 설정한 것으로 본다. 지료는 당사자 청구에 의하여 법원이 정한다. 대지소유자는 대지를 임대하거나 지상권ㆍ전세권을 설정하지 못한다.","src":"민법 제305조 | 기출 2022-30"},{"t":"법정지상권을 취득한 건물소유자가 설정등기 없이 건물을 양도하는 경우 특별한 사정이 없는 한 토지소유자는 건물 양수인에 대하여 건물철거를 청구할 수 없다.","src":"기출 2021-26"},{"t":"관습법상 법정지상권이 인정되지 않는 경우: 토지와 건물을 함께 매도하였으나 토지에 대해서만 소유권이전등기가 된 때 매도인인 건물소유자, 매매로 소유자를 달리하게 되었으나 건물의 소유를 위하여 토지에 임대차계약을 체결한 경우, 담보가등기가 마쳐진 나대지에 소유자가 건물을 신축한 후 본등기가 되어 소유자가 달라진 경우.","src":"기출 2021-26 | 기출 2023-30"}]},{"머리":"지역권","줄":[{"t":"지역권: 일정한 목적을 위하여 타인의 토지를 자기 토지의 편익에 이용하는 권리다.","src":"민법 제291조"},{"t":"부종성: 지역권은 요역지 소유권에 부종하여 이전하며 요역지에 대한 소유권 이외의 권리의 목적이 된다. 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다.","src":"민법 제292조 | 기출 2026-29"},{"t":"불가분성: 토지공유자의 1인은 지분에 관하여 그 토지를 위한 지역권 또는 그 토지가 부담한 지역권을 소멸하게 하지 못한다. 토지의 분할이나 일부양도의 경우 지역권은 요역지의 각 부분을 위하여 또는 승역지의 각 부분에 존속한다.","src":"민법 제293조 | 기출 2026-29"},{"t":"취득시효: 지역권은 계속되고 표현된 것에 한하여 시효취득할 수 있다. 공유자의 1인이 지역권을 취득한 때 다른 공유자도 이를 취득한다. 점유취득시효 중단은 지역권을 행사하는 모든 공유자에 대한 사유가 아니면 효력이 없다.","src":"민법 제294조 | 민법 제295조 | 기출 2026-29"},{"t":"소멸시효: 20년간 행사하지 않으면 소멸한다. 요역지 공유자 1인에 의한 소멸시효의 중단ㆍ정지는 다른 공유자를 위하여 효력이 있다.","src":"민법 제162조 제2항 | 민법 제296조 | 기출 2023-25"},{"t":"용수지역권: 용수승역지의 수량이 요역지 및 승역지의 수요에 부족한 때 먼저 가용에 공급하고 다른 용도에 공급한다. 승역지에 수개의 용수지역권이 설정될 수 있고 후순위 지역권자는 선순위 지역권자의 용수를 방해하지 못한다.","src":"민법 제297조 | 기출 2026-29"},{"t":"승역지 소유자의 의무: 계약으로 자기 비용으로 공작물의 설치ㆍ수선 의무를 부담한 때 특별승계인도 그 의무를 부담한다. 위기(委棄)로 부담을 면할 수 있다. 공작물을 지역권 행사를 방해하지 않는 범위에서 사용할 수 있고 수익 비율로 비용을 분담한다.","src":"민법 제298조 | 민법 제299조 | 민법 제300조"},{"t":"지역권자의 물권적 청구권: 방해제거ㆍ방해예방 청구(제214조 준용)는 가능하나 승역지의 반환청구는 할 수 없다.","src":"민법 제301조 | 기출 2024-27"},{"t":"특수지역권: 어느 지역 주민이 집합체의 관계로 타인의 토지에서 초목ㆍ야생물ㆍ토사의 채취, 방목 기타 수익을 하는 권리에 지역권 규정을 준용한다.","src":"민법 제302조"},{"t":"1필의 토지의 일부에 대해서도 지역권을 설정할 수 있다.","src":"기출 2025-11"}]},{"머리":"전세권의 성립과 내용","줄":[{"t":"전세권의 내용: 전세금을 지급하고 타인의 부동산을 점유하여 그 부동산의 용도에 좇아 사용ㆍ수익하며, 그 부동산 전부에 대하여 후순위권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있다. 용익물권적 성격과 담보물권적 성격을 겸비한다. 농경지는 전세권의 목적으로 하지 못한다.","src":"민법 제303조 | 기출 2021-30"},{"t":"전세권은 건물뿐 아니라 토지에도 설정할 수 있다(농경지 제외). 1필 토지의 일부에도 설정할 수 있다.","src":"민법 제303조 | 기출 2021-30 | 기출 2022-10"},{"t":"전세목적물의 인도는 전세권의 성립요건이 아니다.","src":"기출 2024-30 | 기출 2025-30 | 기출 2026-30"},{"t":"기존 채권(임차보증금반환채권 등)으로 전세금의 지급에 갈음할 수 있다(전세금은 현실로 수수될 필요가 없다).","src":"기출 2021-30 | 기출 2024-30"},{"t":"전세목적물의 사용ㆍ수익 권능을 배제하고 채권담보만을 위해 설정한 전세권설정등기는 무효다.","src":"기출 2025-30 | 기출 2026-20"},{"t":"전세권의 존속기간이 시작되기 전에 마친 전세권설정등기는 특별한 사정이 없는 한 유효한 것으로 추정된다.","src":"기출 2026-30"},{"t":"존속기간: 10년을 넘지 못한다(10년 초과 약정은 10년으로 단축). 건물에 대한 전세권을 1년 미만으로 정하면 1년. 갱신할 수 있고 갱신 기간도 갱신한 날로부터 10년을 넘지 못한다.","src":"민법 제312조 제1항~제3항"},{"t":"법정갱신: 건물 전세권설정자가 존속기간 만료 전 6월부터 1월까지 사이에 갱신거절 통지 또는 조건 변경 통지를 하지 않으면 만료된 때에 전전세권과 동일한 조건으로 다시 전세권을 설정한 것으로 본다. 이 경우 존속기간은 정함이 없는 것으로 본다. 법정갱신에는 등기를 요하지 않는다.","src":"민법 제312조 제4항 | 기출 2026-30"},{"t":"존속기간을 약정하지 않은 때: 각 당사자는 언제든지 상대방에 대하여 전세권의 소멸을 통고할 수 있고, 상대방이 통고를 받은 날부터 6월이 경과하면 전세권이 소멸한다.","src":"민법 제313조 | 기출 2026-30"},{"t":"전세금 증감청구권: 조세ㆍ공과금 기타 부담의 증감이나 경제사정의 변동으로 전세금이 상당하지 아니하게 된 때 당사자는 장래에 대하여 증감을 청구할 수 있다. 증액은 대통령령이 정하는 기준에 따른 비율을 초과하지 못한다.","src":"민법 제312조의2"},{"t":"전세권자의 유지ㆍ수선의무: 목적물의 현상을 유지하고 통상의 관리에 속한 수선을 하여야 한다.","src":"민법 제309조 | 기출 2025-30 | 기출 2026-30"},{"t":"유익비 상환청구: 전세권자가 목적물을 개량하기 위하여 지출한 유익비는 가액의 증가가 현존한 경우에 한하여 소유자의 선택에 좇아 지출액이나 증가액의 상환을 청구할 수 있고, 법원은 소유자 청구로 상환기간을 허여할 수 있다.","src":"민법 제310조"},{"t":"소멸청구: 전세권자가 설정계약 또는 목적물의 성질에 의하여 정하여진 용법으로 사용ㆍ수익하지 않으면 전세권설정자는 전세권의 소멸을 청구할 수 있고 원상회복 또는 손해배상을 청구할 수 있다.","src":"민법 제311조"},{"t":"건물의 전세권의 효력: 타인의 토지에 있는 건물에 전세권을 설정한 때 전세권의 효력은 그 건물의 소유를 목적으로 한 지상권 또는 임차권에 미친다. 전세권설정자는 전세권자의 동의 없이 지상권 또는 임차권을 소멸하게 하는 행위를 하지 못한다.","src":"민법 제304조"}]},{"머리":"전세권의 양도ㆍ전전세ㆍ소멸","줄":[{"t":"전세권자는 전세권을 타인에게 양도 또는 담보로 제공할 수 있고 존속기간 내에서 목적물을 전전세 또는 임대할 수 있다. 설정행위로 금지한 때는 제외. 즉 설정자의 동의 없이 양도할 수 있다.","src":"민법 제306조 | 기출 2025-30"},{"t":"전세권양수인은 전세권설정자에 대하여 전세권양도인과 동일한 권리의무가 있다. 전전세 또는 임대한 경우 전세권자는 하지 않았으면 면할 수 있는 불가항력으로 인한 손해에 대하여도 책임을 진다.","src":"민법 제307조 | 민법 제308조"},{"t":"전세권 존속 중에는 전세권을 존속시키면서 전세금반환채권만을 분리하여 확정적으로 양도하는 것은 허용되지 않는다.","src":"기출 2022-30 | 기출 2024-30"},{"t":"전세권이 갱신 없이 존속기간이 만료되면 전세권의 용익물권적 권능은 전세권설정등기의 말소 없이도 당연히 소멸한다. 토지전세계약이 종료되면 그 계약을 원인으로 한 전세권설정등기 절차 이행청구권도 소멸한다.","src":"기출 2022-30 | 기출 2024-30 | 기출 2025-30"},{"t":"전세권 존속 중 목적물의 소유권이 이전되면 신 소유자가 전세권설정자의 지위를 승계하여 전세금반환의무를 부담한다. 구 소유자는 부담하지 않는다.","src":"기출 2022-30 | 기출 2024-30"},{"t":"불가항력으로 인한 멸실: 전세권의 목적물이 불가항력으로 멸실된 부분의 전세권은 소멸한다. 잔존부분으로 목적을 달성할 수 없는 때 전세권 전부의 소멸을 통고하고 전세금 반환을 청구할 수 있다. 전세권자 책임 있는 사유로 멸실되면 손해를 배상하고 설정자는 전세금으로 충당한다.","src":"민법 제314조 | 민법 제315조"},{"t":"원상회복ㆍ부속물 매수청구: 존속기간 만료로 소멸한 때 전세권자는 원상회복하고 부속시킨 물건을 수거할 수 있다. 설정자가 부속물 매수를 청구하면 정당한 이유 없이 거절하지 못한다. 설정자 동의를 얻어 부속시킨 물건이나 설정자로부터 매수한 물건은 전세권자가 매수를 청구할 수 있다.","src":"민법 제316조"},{"t":"전세권이 소멸한 때: 전세권설정자는 전세권자로부터 목적물의 인도 및 전세권설정등기 말소등기에 필요한 서류를 교부받는 동시에 전세금을 반환한다(동시이행).","src":"민법 제317조"},{"t":"경매청구: 전세권설정자가 전세금의 반환을 지체한 때 전세권자는 민사집행법에 따라 목적물의 경매를 청구할 수 있다.","src":"민법 제318조"},{"t":"토지임차인의 건물 기타 공작물 매수청구권에 관한 제643조는 토지의 전세권에도 유추적용될 수 있다.","src":"기출 2022-30"},{"t":"전세권 관련 준용: 제213조, 제214조, 제216조~제244조(소유권 및 상린관계 규정)를 전세권자 간 또는 전세권자와 인지소유자 및 지상권자 간에 준용한다.","src":"민법 제319조"}]}],"함정":[{"x":"담보가등기가 마쳐진 나대지에 그 소유자가 건물을 신축한 후 그 가등기에 기한 본등기가 경료되어 대지와 건물의 소유자가 달라진 경우, 특별한 사정이 없는 한 관습상 법정지상권이 성립된다.","o":"관습상 법정지상권이 성립하지 않는다.","src":"기출 2021-26"},{"x":"전세권은 건물에 한하여 설정할 수 있다.","o":"토지에도 설정할 수 있다(농경지 제외).","src":"민법 제303조 | 기출 2021-30"},{"x":"전세권이 성립한 후 그 소멸 전에 전세목적물의 소유권이 이전된 경우, 목적물의 구(舊) 소유자는 전세권이 소멸하는 때에 전세권자에 대하여 전세금 반환의무를 부담한다.","o":"신 소유자가 전세금반환의무를 부담한다.","src":"기출 2022-30 | 기출 2024-30"},{"x":"지상권의 설정은 처분행위이므로 토지소유자가 아니어서 처분권한이 없는 자는 지상권 설정계약을 체결할 수 없다.","o":"처분권한 없이도 계약(채권행위)은 체결할 수 있다.","src":"기출 2023-30 | 보충(추정)"},{"x":"전세목적물의 인도는 전세권의 성립요건이다.","o":"성립요건이 아니다.","src":"기출 2024-30 | 기출 2025-30"},{"x":"전세권이 존속하는 동안 전세권을 존속시키기로 하면서 전세금반환채권만을 전세권과 분리하여 확정적으로 양도하는 것은 허용된다.","o":"허용되지 않는다.","src":"기출 2022-30 | 기출 2024-30"},{"x":"전세권이 존속하는 동안 목적물의 소유권이 이전되는 경우, 전세권자와 구 소유자 간의 전세권 관계가 신 소유자에게 이전되는 것은 아니다.","o":"신 소유자에게 이전된다.","src":"기출 2024-30"},{"x":"전세금은 현실적으로 수수되어야 하므로 임차보증금채권으로 전세금 지급에 갈음할 수 없다.","o":"기존 채권으로 갈음할 수 있다.","src":"기출 2021-30 | 기출 2024-30"},{"x":"전세권자는 특별한 사정이 없는 한 전세권설정자의 동의 없이 전세권을 타인에게 양도할 수 없다.","o":"동의 없이 양도할 수 있다.","src":"민법 제306조 | 기출 2025-30"},{"x":"지상권자의 지상권갱신청구권은 형성권이다.","o":"청구권이다. 지상물매수청구권이 형성권이다.","src":"민법 제283조 | 기출 2026-28"},{"x":"기존건물의 소유를 목적으로 설정된 지상권은 그 건물이 멸실되면 소멸한다.","o":"건물이 멸실되어도 소멸하지 않는다.","src":"기출 2026-28 | 보충(추정)"},{"x":"지상권에 저당권을 설정해 준 지상권자가 지상권의 목적인 토지를 매수하면 지상권은 혼동으로 소멸한다.","o":"제3자의 권리의 목적이므로 혼동으로 소멸하지 않는다.","src":"민법 제191조 | 기출 2026-28"},{"x":"석조 건물의 소유를 목적으로 하는 지상권의 존속기간은 최장 30년으로 제한된다.","o":"최단 30년이다.","src":"민법 제280조 | 기출 2026-28"},{"x":"요역지의 공유자 1인은 지분에 관하여 그 토지를 위한 지역권을 소멸시킬 수 있다.","o":"소멸하게 하지 못한다.","src":"민법 제293조 | 기출 2026-29"},{"x":"건물전세권이 법정갱신된 경우, 전세권자는 이를 등기해야 제3자에 대항할 수 있다.","o":"법정갱신은 등기 없이도 대항할 수 있다.","src":"민법 제312조 제4항 | 기출 2026-30"},{"x":"지상물과 지상권의 분리처분, 지료 없는 지상권, 지상권의 법정갱신, 수목의 소유를 위한 구분지상권이 모두 인정된다(2024-29).","o":"법정갱신과 수목 소유를 위한 구분지상권은 인정되지 않는다.","src":"기출 2024-29"}]},"담보물권(유치권ㆍ질권ㆍ저당권)":{"묶음":[{"머리":"유치권의 성립","줄":[{"t":"내용: 타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우 변제를 받을 때까지 유치할 권리가 있다. 점유가 불법행위로 인한 경우에는 적용하지 않는다.","src":"민법 제320조 | 기출 2022-32 | 기출 2026-31"},{"t":"유치권은 법정담보물권이나 당사자가 유치권배제특약으로 성립을 배제할 수 있다. 배제특약 있으면 다른 요건을 갖춰도 성립하지 않는다. 배제특약의 효력은 특약 상대방뿐 아니라 누구든지 주장할 수 있고, 배제특약에는 조건을 붙일 수 있다.","src":"기출 2022-32 | 기출 2023-31 | 기출 2025-31 | 기출 2026-31"},{"t":"채권자가 채무자를 직접점유자로 하여 유치물을 간접점유하는 경우 유치권은 성립하지 않는다.","src":"기출 2022-32 | 기출 2025-31"},{"t":"유치권이 성립하지 않는 경우: 신축건물의 소유권이 수급인에게 있는 경우의 공사대금 채권, 부동산 매도인의 매매대금 채권(매수인에 대한 유치권 행사 불가), 임대차보증금반환채권(임차건물에 관하여 생긴 채권이 아님), 불법행위로 인한 점유.","src":"기출 2023-31 | 기출 2026-31"},{"t":"완성된 주택을 도급인이 원시취득한 경우 수급인은 보수를 지급받을 때까지 그 주택에 유치권을 행사할 수 있다.","src":"기출 2021-36"},{"t":"분할이 가능한 토지의 일부에도 유치권이 성립할 수 있다.","src":"기출 2021-32"},{"t":"건물에 대하여 유치권을 행사하는 자는 건물의 부지를 점유하는 자에 해당하지 않는다.","src":"기출 2023-27"}]},{"머리":"유치권의 효력과 소멸","줄":[{"t":"불가분성: 유치권자는 채권 전부의 변제를 받을 때까지 유치물 전부에 대하여 권리를 행사할 수 있다. 목적물이 분할 가능하거나 수개의 물건인 경우에도 적용된다.","src":"민법 제321조 | 기출 2023-31"},{"t":"경매와 간이변제충당: 유치권자는 변제를 받기 위해 유치물을 경매할 수 있으나(우선변제는 받지 못함), 정당한 이유가 있으면 감정인 평가에 의하여 직접 변제에 충당할 것을 법원에 청구할 수 있고 미리 채무자에게 통지하여야 한다.","src":"민법 제322조 | 기출 2021-32 | 기출 2024-31 | 기출 2026-31"},{"t":"간이변제충당 허가가 있으면 유치물의 소유권은 허가(확정)에 의해 이전하며 등기를 하여야 소유권이 이전되는 것이 아니다.","src":"민법 제322조 | 기출 2021-32 | 보충(추정)"},{"t":"과실수취권: 유치물의 과실을 수취하여 다른 채권보다 먼저 변제에 충당할 수 있다. 과실이 금전이 아니면 경매하여야 한다. 과실은 이자에 먼저 충당하고 잉여는 원본에 충당한다.","src":"민법 제323조"},{"t":"선관의무: 선량한 관리자의 주의로 점유한다. 채무자의 승낙 없이 유치물을 사용ㆍ대여ㆍ담보제공하지 못한다(보존에 필요한 사용 제외). 위반 시 채무자는 소멸을 청구할 수 있다. 소유자 승낙 없이 임대한 경우 임차인의 점유는 소유자에게 대항할 수 없다.","src":"민법 제324조 | 기출 2026-31"},{"t":"상환청구: 필요비는 소유자에게 상환을 청구하고, 유익비는 가액 증가가 현존한 경우에 한하여 소유자의 선택에 좇아 지출액이나 증가액의 상환을 청구한다(법원이 상환기간 허여 가능).","src":"민법 제325조"},{"t":"유치권의 행사는 피담보채권의 소멸시효의 진행에 영향을 미치지 않는다.","src":"민법 제326조 | 기출 2022-32 | 기출 2025-31"},{"t":"타담보 제공: 채무자는 상당한 담보를 제공하고 유치권의 소멸을 청구할 수 있다. 유치물 소유자(채무자가 아닌 자)도 가능하다.","src":"민법 제327조 | 기출 2023-31 | 기출 2025-31"},{"t":"점유상실: 유치권은 점유의 상실로 소멸한다. 점유를 침탈당한 경우 점유회수의 소를 제기해 승소하여 점유를 회복해야 유치권이 되살아난다(소 제기만으로 회복되는 것이 아님). 점유 침탈로 인한 유치권 소멸을 원인으로 한 손해배상청구권은 침탈일부터 1년 내에 행사할 필요가 없다.","src":"민법 제328조 | 기출 2024-31"},{"t":"유치권자의 항변: 소유자의 소유물반환청구에 대하여 유치권을 항변하면 법원은 상환이행판결(채권 변제와 동시에 인도)을 한다.","src":"기출 2024-31"},{"t":"유치권에는 물상대위성이 없다. 피담보채권의 양도와 목적물의 인도가 있으면 유치권은 이전된다.","src":"기출 2021-32"}]},{"머리":"질권","줄":[{"t":"동산질권의 내용: 채권의 담보로 채무자 또는 제3자가 제공한 동산을 점유하고 다른 채권자보다 자기 채권의 우선변제를 받을 권리가 있다. 설정은 질권자에게 목적물을 인도함으로써 효력이 생긴다(요물계약).","src":"민법 제329조 | 민법 제330조"},{"t":"양도할 수 없는 물건은 질권의 목적이 되지 못한다. 질권자는 설정자로 하여금 질물을 점유하게 하지 못한다(대리점유 금지).","src":"민법 제331조 | 민법 제332조"},{"t":"순위는 설정의 선후에 의한다. 피담보채권의 범위: 원본, 이자, 위약금, 질권실행비용, 질물보존비용, 채무불이행 또는 질물의 하자로 인한 손해배상(다른 약정 있으면 그에 의함).","src":"민법 제333조 | 민법 제334조"},{"t":"유치적 효력: 변제를 받을 때까지 질물을 유치할 수 있으나 우선권 있는 채권자에게 대항하지 못한다. 전질: 자기의 책임으로 질물을 전질할 수 있고 불가항력 손해에도 책임을 진다. 전질의 대항요건: 채무자에게 통지하거나 채무자가 승낙.","src":"민법 제335조 | 민법 제336조 | 민법 제337조"},{"t":"실행: 질권자는 질물을 경매할 수 있고, 정당한 이유가 있으면 감정자 평가에 의한 직접 변제충당을 법원에 청구할 수 있다(미리 채무자 및 질권설정자에게 통지).","src":"민법 제338조"},{"t":"유질계약 금지: 질권설정자는 채무변제기 전의 계약으로 질권자에게 변제에 갈음하여 질물의 소유권을 취득하게 하거나 법률에 정한 방법에 의하지 않고 질물을 처분할 것을 약정하지 못한다.","src":"민법 제339조"},{"t":"질물로 변제받지 못한 부분의 채권에 한하여 채무자의 다른 재산으로부터 변제받을 수 있다.","src":"민법 제340조"},{"t":"물상보증인의 구상권: 타인의 채무를 담보하기 위한 질권설정자가 채무를 변제하거나 질권 실행으로 소유권을 잃은 때 보증채무 규정에 의하여 채무자에 대한 구상권이 있다(사후구상권만, 사전구상권 없음).","src":"민법 제341조 | 기출 2021-31"},{"t":"물상대위: 질물의 멸실ㆍ훼손 또는 공용징수로 설정자가 받을 금전 기타 물건에 대하여도 질권을 행사할 수 있고 지급 또는 인도 전에 압류하여야 한다.","src":"민법 제342조"},{"t":"준용: 선의취득(제249조~제251조)과 유치권 규정(제321조~제325조)을 동산질권에 준용한다.","src":"민법 제343조 | 기출 2021-31"},{"t":"권리질권의 목적: 재산권. 단 부동산의 사용ㆍ수익을 목적으로 하는 권리는 제외. 설정방법은 그 권리의 양도에 관한 방법에 의한다. 양도할 수 없는 채권은 질권의 목적이 될 수 없다.","src":"민법 제345조 | 민법 제346조 | 기출 2021-31"},{"t":"채권증서가 있는 때 질권설정은 증서를 질권자에게 교부함으로써 효력이 생긴다. 임대차보증금반환채권에 질권을 설정할 때 임대차계약서를 교부하지 않아도 채권질권은 성립한다(증서 교부가 필요한 채권증서가 아니므로).","src":"민법 제347조 | 기출 2021-31"},{"t":"저당권으로 담보한 채권을 질권의 목적으로 한 때: 저당권 등기에 질권의 부기등기를 하여야 그 효력이 저당권에 미친다(질권의 목적이 될 수 있음). 무담보 채권에 질권 설정 후 그 채권을 담보하기 위한 저당권이 설정되어도 같다.","src":"민법 제348조 | 기출 2023-33 | 보충(추정)"},{"t":"지명채권질권의 대항요건: 설정자가 제450조에 의하여 제3채무자에게 통지하거나 제3채무자가 승낙하여야 제3채무자 기타 제3자에게 대항할 수 있다.","src":"민법 제349조"},{"t":"질권설정자는 질권자의 동의 없이 질권의 목적된 권리를 소멸하게 하거나 질권자의 이익을 해하는 변경을 할 수 없다. 채권질권 설정자가 목적 채권을 양도하는 경우에는 질권자의 동의가 필요하지 않다.","src":"민법 제352조 | 기출 2021-31"},{"t":"질권자의 실행: 질권의 목적이 된 채권을 직접 청구할 수 있고, 금전이면 자기 채권 한도에서 직접 청구할 수 있다. 변제기가 질권자의 채권보다 먼저 도래한 때 제3채무자에게 변제금액의 공탁을 청구할 수 있다.","src":"민법 제353조"}]},{"머리":"저당권의 설정과 효력범위","줄":[{"t":"저당권의 내용: 채무자 또는 제3자가 점유를 이전하지 않고 채무의 담보로 제공한 부동산에 대하여 다른 채권자보다 자기 채권의 우선변제를 받을 권리.","src":"민법 제356조"},{"t":"저당권의 객체: 부동산, 지상권, 전세권, 등록된 자동차, 광업권, 등기된 입목. 지역권은 저당권의 객체가 될 수 없다.","src":"민법 제371조 | 기출 2022-29 | 기출 2023-32 | 보충"},{"t":"지상권 또는 전세권을 목적으로 저당권을 설정한 자는 저당권자의 동의 없이 지상권 또는 전세권을 소멸하게 하는 행위를 하지 못한다.","src":"민법 제371조"},{"t":"근저당: 그 담보할 채무의 최고액만을 정하고 채무의 확정을 장래에 보류하여 설정할 수 있다. 확정될 때까지의 채무의 소멸 또는 이전은 저당권에 영향을 미치지 않는다. 이자는 최고액 중에 산입한 것으로 본다.","src":"민법 제357조"},{"t":"근저당권 설정 후 피담보채권 확정 전에 설정자와 근저당권자의 합의로 채무자를 추가하는 데는 이해관계인의 승낙이 필요하지 않다.","src":"기출 2023-33"},{"t":"후순위 저당권자가 경매를 신청한 경우 선순위 근저당권의 피담보채무 확정시기는 매수인이 매각대금을 완납한 때다.","src":"기출 2021-29"},{"t":"효력이 미치는 범위: 저당부동산에 부합된 물건과 종물에 미친다(설정 후 부합된 물건 포함). 법률에 특별한 규정 또는 설정행위에 다른 약정이 있으면 제외.","src":"민법 제358조 | 기출 2021-29 | 기출 2026-7"},{"t":"건물에 대한 저당권의 효력은 특별한 사정이 없는 한 그 건물의 소유를 목적으로 하는 지상권에도 미친다.","src":"기출 2025-32 | 기출 2026-32"},{"t":"과실: 저당부동산에 대한 압류가 있은 후에 설정자가 수취한 과실 또는 수취할 수 있는 과실에 미친다. 저당권자가 그 부동산의 소유권ㆍ지상권ㆍ전세권을 취득한 제3자에 대하여는 압류한 사실을 통지한 후가 아니면 대항하지 못한다.","src":"민법 제359조 | 기출 2021-29"},{"t":"피담보채권의 범위: 원본, 이자, 위약금, 채무불이행으로 인한 손해배상, 저당권 실행비용. 지연배상은 원본의 이행기일을 경과한 후의 1년분에 한한다. 등기된 손해배상예정액은 범위에 속하고 등기된 금액을 초과하는 원본이나 저당물의 보존비용 등은 범위에 속하지 않는다.","src":"민법 제360조 | 기출 2024-32 | 기출 2026-32"},{"t":"특별한 사정이 없는 한 장래에 발생할 특정의 조건부 채권을 담보하기 위하여도 저당권을 설정할 수 있다.","src":"기출 2026-32"},{"t":"부종성: 저당권으로 담보한 채권이 시효 완성 기타 사유로 소멸하면 저당권도 소멸한다.","src":"민법 제369조 | 기출 2025-32"},{"t":"수반성ㆍ처분제한: 저당권은 그 담보한 채권과 분리하여 타인에게 양도하거나 다른 채권의 담보로 하지 못한다.","src":"민법 제361조 | 기출 2025-32 | 기출 2026-32"}]},{"머리":"저당권의 실행과 제3취득자","줄":[{"t":"저당권의 보충: 설정자의 책임 있는 사유로 저당물의 가액이 현저히 감소된 때 저당권자는 원상회복 또는 상당한 담보제공을 청구할 수 있다. 저당목적물을 권한 없이 멸실ㆍ훼손하거나 담보가치를 감소시키는 행위는 불법행위가 될 수 있다.","src":"민법 제362조 | 기출 2022-29"},{"t":"경매청구: 저당권자는 채권의 변제를 받기 위하여 저당물의 경매를 청구할 수 있다. 저당물의 소유권을 취득한 제3자도 경매인이 될 수 있다.","src":"민법 제363조 | 기출 2022-29 | 기출 2025-32"},{"t":"제3취득자의 변제: 저당부동산에 대하여 소유권ㆍ지상권ㆍ전세권을 취득한 제3자는 저당권자에게 담보된 채권을 변제하고 저당권의 소멸을 청구할 수 있다(설정자의 의사에 반해도 가능).","src":"민법 제364조 | 기출 2023-33"},{"t":"제3취득자의 비용상환: 보존ㆍ개량을 위하여 필요비 또는 유익비를 지출한 때 제203조에 의하여 경매대가에서 우선 상환받을 수 있다.","src":"민법 제367조"},{"t":"일괄경매: 토지를 목적으로 저당권을 설정한 후 설정자가 그 토지에 건물을 축조한 때 저당권자는 토지와 함께 그 건물에 대하여도 경매를 청구할 수 있다. 건물 경매대가에 대하여는 우선변제를 받을 권리가 없다. 저당권설정자로부터 용익권을 설정받은 자가 건물을 신축한 후 설정자가 그 건물 소유권을 취득한 경우에도 일괄경매를 청구할 수 있다.","src":"민법 제365조 | 기출 2021-29 | 기출 2023-33"},{"t":"법정지상권: 저당물의 경매로 토지와 지상 건물이 다른 소유자에 속한 경우 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 지료는 당사자의 청구에 의하여 법원이 정한다.","src":"민법 제366조"},{"t":"공동저당: 동일한 채권의 담보로 수개의 부동산에 저당권을 설정한 경우 경매대가를 동시에 배당하면 각 부동산의 경매대가에 비례하여 채권의 분담을 정한다. 일부 경매대가를 먼저 배당하면 그 대가에서 채권 전부의 변제를 받을 수 있고, 이 경우 그 부동산의 차순위저당권자는 선순위자가 다른 부동산의 경매대가에서 변제받을 수 있는 금액 한도에서 선순위자를 대위하여 저당권을 행사할 수 있다.","src":"민법 제368조"},{"t":"준용: 제214조(방해제거ㆍ예방청구), 제321조(불가분성), 제333조(순위), 제340조, 제341조(물상보증인 구상권), 제342조(물상대위)를 저당권에 준용한다.","src":"민법 제370조"},{"t":"저당권이 설정된 후 소유권이 제3자에게 이전된 경우 종전 소유자(설정자)도 피담보채권의 소멸을 이유로 저당권설정등기의 말소를 청구할 수 있다.","src":"기출 2021-29 | 기출 2026-32"}]}],"함정":[{"x":"저당목적물이 제3자에게 양도된 후 저당권자가 저당목적물을 압류만 하더라도 그 목적물의 과실에 관하여 그 제3취득자에게 대항할 수 있다.","o":"압류한 사실을 통지한 후가 아니면 대항하지 못한다.","src":"민법 제359조 | 기출 2021-29"},{"x":"타인의 채무를 담보하기 위하여 질권을 설정한 자는 채무자에 대한 사전구상권을 갖는다.","o":"사후구상권만 있다(변제하거나 소유권을 잃은 때).","src":"민법 제341조 | 기출 2021-31"},{"x":"유치부동산에 대하여 법원이 간이변제충당을 허가한 경우, 그 부동산에 대한 등기를 하여야 소유권이 이전된다.","o":"법률 규정에 의한 취득으로 등기 없이 소유권이 이전된다(출제 오답, 등기 불요).","src":"민법 제187조 | 민법 제322조 | 기출 2021-32 | 보충(추정)"},{"x":"지상권은 저당권의 목적으로 할 수 없다.","o":"지상권과 전세권도 저당권의 목적이 될 수 있다.","src":"민법 제371조 | 기출 2022-29"},{"x":"유치권배제특약에 따른 효력은 특약의 상대방만 주장할 수 있다.","o":"특약 상대방 외의 누구든지 주장할 수 있다.","src":"기출 2022-32 | 보충(추정)"},{"x":"유치권은 약정담보물권이므로 당사자의 약정으로 그 성립을 배제할 수 없다 / 유치권은 약정담보물권이다(2023-31).","o":"유치권은 법정담보물권이다. 배제특약은 가능하다.","src":"기출 2023-31"},{"x":"근저당권을 설정한 이후 피담보채권이 확정되기 전에 근저당설정자와 근저당권자의 합의로 채무자를 추가할 경우에는 특별한 사정이 없는 한, 이해관계인의 승낙을 받아야 한다.","o":"이해관계인의 승낙이 필요하지 않다.","src":"기출 2023-33"},{"x":"저당권으로 담보된 채권에 질권을 설정하였다면 특별한 사정이 없는 한, 저당권은 질권의 목적이 될 수 없다.","o":"질권의 목적이 된다(저당권 등기에 질권의 부기등기를 하면 효력이 저당권에 미침).","src":"민법 제348조 | 기출 2023-33"},{"x":"무담보채권에 질권이 설정된 이후 그 채권을 담보하기 위하여 저당권이 설정되었다면 특별한 사정이 없는 한, 저당권은 질권의 목적이 될 수 없다.","o":"질권의 목적이 될 수 있다.","src":"기출 2023-33 | 보충(추정)"},{"x":"저당부동산의 제3취득자는 저당권설정자의 의사에 반하여 피담보채무를 변제하고 저당권의 소멸을 청구할 수는 없다.","o":"의사에 반해도 변제하고 소멸을 청구할 수 있다.","src":"민법 제364조 | 기출 2023-33"},{"x":"乙이 X의 점유를 침탈당한 경우, 1년 내에 점유회수의 소를 제기하여 승소하면 점유를 회복하지 않더라도 유치권은 회복된다.","o":"점유를 회복해야 유치권이 회복된다.","src":"민법 제192조 제2항 | 민법 제328조 | 기출 2024-31"},{"x":"유치권 배제 특약에는 조건을 붙일 수 없다.","o":"조건을 붙일 수 있다.","src":"기출 2025-31 | 기출 2022-32"},{"x":"저당물의 소유권을 취득한 제3자는 그 저당물의 경매에서 경매인이 될 수 없다.","o":"경매인이 될 수 있다.","src":"민법 제363조 제2항 | 기출 2025-32"},{"x":"유치권자가 소유자의 승낙없이 유치물을 임대한 경우, 임차인의 점유는 소유자에게 대항할 수 있는 권원에 기한 점유에 해당한다.","o":"소유자에게 대항할 수 없다.","src":"민법 제324조 | 기출 2026-31"},{"x":"임대차보증금반환채권은 임차건물에 관하여 생긴 채권이므로 이를 피담보채권으로 하는 유치권이 성립할 수 있다.","o":"유치권이 성립하지 않는다.","src":"기출 2026-31"},{"x":"유치권 배제특약이 있더라도 다른 법정요건이 모두 충족되면 유치권이 성립한다.","o":"배제특약이 있으면 성립하지 않는다.","src":"기출 2026-31"},{"x":"채권자의 점유가 불법행위로 인한 경우에도 유치권이 성립한다.","o":"성립하지 않는다.","src":"민법 제320조 제2항 | 기출 2026-31"},{"x":"저당권이 설정된 후 그 부동산의 소유권이 제3자에게 이전된 경우, 저당권설정자인 종전 소유자는 피담보채권의 소멸을 이유로 저당권설정등기의 말소를 청구할 수 없다.","o":"종전 소유자도 말소를 청구할 수 있다.","src":"기출 2021-29 | 기출 2026-32"},{"x":"저당권의 객체가 될 수 있는 것에 지역권이 포함된다(2023-32 정답 3).","o":"지역권은 저당권의 객체가 될 수 없다. 광업권, 지상권, 전세권, 등기된 입목은 객체가 된다.","src":"기출 2023-32"},{"x":"저당권의 효력이 미치는 피담보채권의 범위에는 등기된 금액을 초과하는 원본, 저당물의 보존비용, 저당물의 하자로 인한 손해배상, 원본 이행기일 경과 후 1년분을 넘는 지연배상이 포함된다(2024-32 선지).","o":"등기된 손해배상예정액이 범위에 속한다. 나머지는 속하지 않는다.","src":"민법 제360조 | 기출 2024-32"}]},"채권의 목적과 효력":{"묶음":[{"머리":"채권의 목적","줄":[{"t":"채권의 목적: 금전으로 가액을 산정할 수 없는 것이라도 채권의 목적으로 할 수 있다.","src":"민법 제373조"},{"t":"특정물채권: 특정물의 인도가 채권의 목적인 때 채무자는 인도하기까지 선량한 관리자의 주의로 보존하여야 한다.","src":"민법 제374조"},{"t":"종류채권: 종류로만 지정하고 품질을 정할 수 없는 때 채무자는 중등품질의 물건으로 이행한다. 채무자가 이행에 필요한 행위를 완료하거나 채권자의 동의를 얻어 이행할 물건을 지정한 때 그때부터 그 물건이 채권의 목적물이 된다(특정).","src":"민법 제375조"},{"t":"금전채권: 어느 종류의 통화로 지급할 것인 경우 그 통화가 변제기에 강제통용력을 잃은 때 채무자는 다른 통화로 변제한다. 외화채권: 채무자는 자기가 선택한 그 나라의 각 종류의 통화로 변제할 수 있다. 채권액이 다른 나라 통화로 지정된 때 채무자는 지급할 때의 이행지 환금시가에 의하여 우리나라 통화로 변제할 수 있다.","src":"민법 제376조 | 민법 제377조 | 민법 제378조"},{"t":"법정이율: 이자 있는 채권의 이율은 다른 법률의 규정이나 약정이 없으면 연 5푼이다(민법 규정. 상행위는 상법상 연 6푼).","src":"민법 제379조 | 보충"}]},{"머리":"선택채권","줄":[{"t":"선택권자: 채권의 목적이 수개의 행위 중에서 선택에 좇아 확정될 경우 법률의 규정이나 약정이 없으면 선택권은 채무자에게 있다.","src":"민법 제380조"},{"t":"선택권의 이전: 선택권 행사의 기간이 있는데 선택권자가 그 기간 내에 선택하지 않으면 상대방은 상당한 기간을 정하여 선택을 최고할 수 있고, 그 기간 내에 선택하지 않으면 선택권은 상대방에게 있다(즉시 이전되는 것이 아니다). 기간이 없는 경우에는 채권의 기한 도래 후 같은 방식이다.","src":"민법 제381조"},{"t":"선택의 방법: 채권자나 채무자가 선택하는 경우 상대방에 대한 의사표시로 하며 상대방의 동의 없이 철회하지 못한다.","src":"민법 제382조"},{"t":"제3자의 선택권: 제3자가 선택하기로 하는 약정은 유효하다. 선택은 채무자 및 채권자에 대한 의사표시로 하며 채권자 및 채무자의 동의 없이 철회하지 못한다. 제3자가 선택할 수 없는 경우 선택권은 채무자에게 있다. 제3자가 선택하지 않는 경우 채권자나 채무자는 상당 기간을 정해 선택을 최고할 수 있고 그 기간 내에 선택하지 않으면 선택권은 채무자에게 있다.","src":"민법 제383조 | 민법 제384조 | 기출 2022-33"},{"t":"불능으로 인한 특정: 선택할 수개의 행위 중 처음부터 불능한 것이나 후에 이행불능이 된 것이 있으면 채권의 목적은 잔존한 것에 존재한다. 선택권 없는 당사자의 과실로 불능이 된 때는 적용하지 않는다.","src":"민법 제385조 | 기출 2022-33"},{"t":"선택의 소급효: 선택의 효력은 채권이 발생한 때에 소급한다. 제3자의 권리를 해하지 못한다.","src":"민법 제386조"},{"t":"선택채권의 소멸시효는 선택권을 행사할 수 있을 때부터 진행한다.","src":"기출 2026-23"}]},{"머리":"이행지체","줄":[{"t":"지체책임의 시기: ① 확정기한 있는 채무는 기한이 도래한 때부터 ② 불확정기한 있는 채무는 채무자가 기한이 도래함을 안 때부터 ③ 기한이 없는 채무는 이행청구를 받은 때부터 지체책임이 있다.","src":"민법 제387조 | 기출 2024-34 | 기출 2025-35"},{"t":"기한이익의 상실: 채무자가 담보를 손상ㆍ감소 또는 멸실하게 한 때, 또는 담보제공의 의무를 이행하지 않은 때 기한의 이익을 주장하지 못한다.","src":"민법 제388조"},{"t":"이행지체 중의 손해배상: 채무자는 자기에게 과실이 없는 경우에도 이행지체 중에 생긴 손해를 배상하여야 한다. 이행기에 이행하여도 손해를 면할 수 없는 경우는 제외.","src":"민법 제392조"},{"t":"이행지체와 전보배상: 채권자가 상당한 기간을 정하여 이행을 최고하여도 그 기간 내에 이행하지 않거나 지체 후의 이행이 채권자에게 이익이 없는 때 수령을 거절하고 이행에 갈음한 손해배상을 청구할 수 있다.","src":"민법 제395조"}]},{"머리":"강제이행","줄":[{"t":"강제이행: 채무자가 임의로 이행하지 않은 때 채권자는 강제이행을 법원에 청구할 수 있다. 채무의 성질이 강제이행을 허락하지 않는 때는 제외. 강제이행과 별도로 손해배상을 청구할 수 있다.","src":"민법 제389조 제1항ㆍ제4항"},{"t":"채무가 법률행위(의사표시)를 목적으로 한 때: 채무자의 의사표시에 갈음할 재판을 청구할 수 있다(채무자의 비용으로 제3자에게 하게 하는 것이 아니다).","src":"민법 제389조 제2항 | 기출 2024-34"},{"t":"채무자의 일신에 전속하지 않는 작위를 목적으로 한 때: 채무자의 비용으로 제3자에게 이를 하게 할 것을 법원에 청구할 수 있다. 부작위 채무 위반 시 채무자의 비용으로 위반한 것을 제각하고 장래에 대한 적당한 처분을 청구할 수 있다.","src":"민법 제389조 제2항ㆍ제3항"}]},{"머리":"채무불이행과 손해배상","줄":[{"t":"채무불이행책임: 채무자가 채무의 내용에 좇은 이행을 하지 아니한 때 채권자는 손해배상을 청구할 수 있다. 채무자의 고의나 과실 없이 이행할 수 없게 된 때에는 책임이 없다(귀책사유 필요).","src":"민법 제390조 | 기출 2024-34"},{"t":"이행보조자: 채무자의 법정대리인이 채무자를 위하여 이행하거나 채무자가 타인을 사용하여 이행하는 경우 법정대리인 또는 피용자의 고의나 과실은 채무자의 고의나 과실로 본다.","src":"민법 제391조 | 기출 2024-34 | 기출 2026-18"},{"t":"손해배상의 범위: 통상의 손해를 한도로 한다. 특별한 사정으로 인한 손해는 채무자가 그 사정을 알았거나 알 수 있었을 때에 한하여 배상책임이 있다.","src":"민법 제393조 | 기출 2024-34"},{"t":"손해배상의 방법: 다른 의사표시가 없으면 금전으로 배상한다.","src":"민법 제394조"},{"t":"과실상계: 채무불이행에 관하여 채권자에게 과실이 있는 때 법원은 손해배상의 책임 및 그 금액을 정함에 이를 참작하여야 한다(채무자의 주장이 없어도 직권으로 참작).","src":"민법 제396조 | 기출 2021-40"},{"t":"금전채무불이행: 손해배상액은 법정이율에 의한다. 법령의 제한에 위반하지 않는 약정이율이 있으면 그 이율에 의한다. 채권자는 손해의 증명을 요하지 않고 채무자는 과실 없음을 항변하지 못한다.","src":"민법 제397조 | 기출 2021-40"},{"t":"배상액의 예정: 당사자는 채무불이행에 관한 손해배상액을 예정할 수 있다. 예정액이 부당히 과다한 경우 법원은 적당히 감액할 수 있다. 이행의 청구나 계약의 해제에 영향을 미치지 않는다. 위약금의 약정은 손해배상액의 예정으로 추정한다.","src":"민법 제398조 | 기출 2021-40"},{"t":"지연손해배상액을 예정한 경우 채권자는 예정배상액의 청구와 함께 본래의 급부이행을 청구할 수 있다.","src":"민법 제398조 제3항 | 기출 2021-40"},{"t":"손해배상자의 대위: 채권자가 채권의 목적인 물건 또는 권리의 가액 ‘전부’를 손해배상으로 받은 때 채무자는 그 물건 또는 권리에 관하여 당연히 채권자를 대위한다(일부만 받은 경우에는 소유권을 취득하지 않는다).","src":"민법 제399조 | 기출 2021-40"},{"t":"계약을 채무불이행으로 해제하더라도 별도로 손해배상을 청구할 수 있다.","src":"민법 제551조(원문 미확인) | 기출 2021-40 | 기출 2023-36"},{"t":"이행불능: 채무자의 귀책사유 없이 목적물이 멸실되면 채무는 소멸하고 쌍무계약이면 위험부담(제537조)의 문제가 된다. 채권자 소유권이전청구권도 소멸한다.","src":"민법 제390조 | 기출 2026-33 | 보충"},{"t":"채무자의 채권자가 목적물에 대한 강제경매를 신청하여 절차가 진행 중이라는 사유만으로는 채무가 이행불능이 되지 않는다.","src":"기출 2026-33"},{"t":"채무자가 목적물을 보관시킨 제3자가 귀책사유 없이 이를 잃어버린 경우 채권자는 그 제3자에게 손해배상을 청구할 수 없다.","src":"기출 2026-33 | 보충(추정)"}]},{"머리":"채권자지체","줄":[{"t":"채권자지체: 채권자가 이행을 받을 수 없거나 받지 아니한 때 이행의 제공 있는 때부터 지체책임이 있다.","src":"민법 제400조"},{"t":"채권자지체 중 채무자의 책임: 고의 또는 중대한 과실이 없으면 불이행으로 인한 모든 책임이 없다. 이자 있는 채권이라도 이자를 지급할 의무가 없다. 목적물 보관 또는 변제 비용이 증가된 때 증가액은 채권자가 부담한다.","src":"민법 제401조 | 민법 제402조 | 민법 제403조"}]},{"머리":"채권자대위권과 채권자취소권","줄":[{"t":"채권자대위권: 채권자는 자기의 채권을 보전하기 위하여 채무자의 권리를 행사할 수 있다. 일신에 전속한 권리는 제외. 채권의 기한이 도래하기 전에는 법원의 허가 없이 행사하지 못하나 보전행위는 예외.","src":"민법 제404조"},{"t":"대위권 행사의 통지: 보전행위 이외의 권리를 행사한 때 채무자에게 통지하여야 한다. 채무자는 통지를 받은 후 그 권리를 처분하여도 채권자에게 대항하지 못한다.","src":"민법 제405조"},{"t":"채권자취소권: 채무자가 채권자를 해함을 알고 재산권을 목적으로 한 법률행위를 한 때 채권자는 그 취소 및 원상회복을 법원에 청구할 수 있다. 수익자나 전득자가 행위 또는 전득 당시 채권자를 해함을 알지 못한 경우는 제외. 취소원인을 안 날부터 1년, 법률행위 있은 날부터 5년 내에 제기한다.","src":"민법 제406조"},{"t":"취소와 원상회복은 모든 채권자의 이익을 위하여 효력이 있다. 통정허위표시로 무효인 법률행위도 채권자취소권의 대상이 될 수 있다.","src":"민법 제407조 | 기출 2021-17 | 기출 2025-14"}]}],"함정":[{"x":"채무불이행을 이유로 계약을 해제하면 별도로 손해배상을 청구하지 못한다.","o":"해제와 별도로 손해배상을 청구할 수 있다.","src":"민법 제551조(원문 미확인) | 기출 2021-40 | 기출 2023-36"},{"x":"채무불이행에 관해 채권자에게 과실이 있는 경우, 법원은 채무자의 주장에 의해 손해배상의 책임 및 그 금액을 정함에 이를 참작할 수 있다.","o":"법원은 직권으로 참작하여야 한다(채무자의 주장 불요).","src":"민법 제396조 | 기출 2021-40"},{"x":"채권자가 그 채권의 목적인 물건의 가액일부를 손해배상으로 받은 경우, 채무자는 그 물건의 소유권을 취득한다.","o":"가액 전부를 받은 때에 채무자가 당연히 채권자를 대위한다.","src":"민법 제399조 | 기출 2021-40"},{"x":"금전채무불이행의 경우, 채무자는 과실없음을 항변할 수 있다.","o":"과실 없음을 항변하지 못한다.","src":"민법 제397조 제2항 | 기출 2021-40"},{"x":"선택권에 관하여 법률의 규정이나 당사자의 약정이 없으면 선택권은 채권자에게 있다.","o":"채무자에게 있다.","src":"민법 제380조 | 기출 2022-33"},{"x":"선택권 행사의 기간이 있는 경우, 선택권자가 그 기간내에 선택권을 행사하지 않으면 즉시 상대방에게 선택권이 이전된다.","o":"상대방이 상당한 기간을 정해 최고하고 그 기간 내에도 선택하지 않아야 이전된다.","src":"민법 제381조 | 기출 2022-33"},{"x":"제3자가 선택권을 행사하기로 하는 당사자의 약정은 무효이다.","o":"유효하다.","src":"민법 제383조 | 기출 2022-33"},{"x":"선택채권의 소멸시효는 선택권을 행사한 때부터 진행한다.","o":"선택권을 행사할 수 있을 때부터 진행한다.","src":"기출 2022-33 | 기출 2026-23"},{"x":"채무가 채무자의 법률행위를 목적으로 한 경우, 채무자가 이를 이행하지 않으면 채권자는 채무자의 비용으로 제3자에게 이를 하게 할 것을 법원에 청구할 수 있다.","o":"채무자의 의사표시에 갈음할 재판을 청구할 수 있다.","src":"민법 제389조 제2항 | 기출 2024-34"},{"x":"X가 화재로 소실된 경우, 甲이 귀책사유 없음을 증명해도 乙의 X에 관한 甲에 대한 소유권이전청구권은 소멸하지 않는다.","o":"귀책사유 없이 이행불능이 되면 소멸한다.","src":"민법 제390조 | 기출 2026-33"},{"x":"X를 보관하던 甲의 친구 丁이 X를 귀책사유 없이 잃어버린 경우, 乙은 丁에게 손해배상을 청구할 수 있다.","o":"귀책사유가 없으므로 청구할 수 없다.","src":"기출 2026-33 | 보충(추정)"}]},"채권관계의 변경과 소멸(다수당사자의 채권관계ㆍ채권양도와 채무인수ㆍ변제ㆍ상계 등)":{"묶음":[{"머리":"분할채권관계ㆍ불가분채권채무","줄":[{"t":"분할채권관계: 채권자나 채무자가 수인인 경우 특별한 의사표시가 없으면 각 채권자 또는 채무자는 균등한 비율로 권리가 있고 의무를 부담한다(원칙).","src":"민법 제408조"},{"t":"불가분채권: 채권의 목적이 성질 또는 당사자의 의사표시에 의하여 불가분인 경우 각 채권자는 모든 채권자를 위하여 이행을 청구할 수 있고 채무자는 모든 채권자를 위하여 각 채권자에게 이행할 수 있다. 불가분채권자 중 1인의 행위나 1인에 관한 사항은 원칙적으로 다른 채권자에게 효력이 없다.","src":"민법 제409조 | 민법 제410조"},{"t":"불가분채무에는 연대채무 규정(제413조~제415조, 제422조, 제424조~제427조)과 제410조를 준용한다. 불가분채권이나 채무가 가분으로 변경된 때에는 각 채권자는 자기 부분만 청구하고 각 채무자는 자기 부담부분만 이행한다.","src":"민법 제411조 | 민법 제412조"},{"t":"기출 정답상 불가분채무에 해당하는 예: 건물을 공동으로 상속한 상속인들의 건물철거의무, 자동차를 공유하는 매도인들의 매수인에 대한 자동차인도의무, 임대목적물을 공유하는 공동임대인의 보증금반환채무, 공유 토지에 수목이 부합되어 이익을 얻은 토지공유자들의 제3자에 대한 부당이득반환채무.","src":"기출 2024-35"},{"t":"기출 정답상 불가분채무에 해당하지 않는 것으로 출제된 것: 공동임차인의 임대인에 대한 임차물반환의무.","src":"기출 2024-35 | 보충(추정)"}]},{"머리":"연대채무","줄":[{"t":"연대채무: 수인의 채무자가 채무 전부를 각자 이행할 의무가 있고 1인의 이행으로 다른 채무자도 의무를 면하는 채무.","src":"민법 제413조"},{"t":"채권자는 어느 연대채무자에 대하여 또는 동시나 순차로 모든 연대채무자에 대하여 채무의 전부나 일부의 이행을 청구할 수 있다.","src":"민법 제414조"},{"t":"절대적 효력 사유: 이행청구, 경개(모든 연대채무자의 이익을 위해 소멸), 상계(상계한 때 모든 연대채무자를 위해 소멸), 채권자지체. 부담부분에 한한 절대효: 면제, 혼동, 소멸시효 완성.","src":"민법 제416조~제422조"},{"t":"무효ㆍ취소: 어느 연대채무자에 대한 법률행위의 무효나 취소의 원인은 다른 연대채무자의 채무에 영향을 미치지 않는다. 그 외의 사항은 효력이 없다(상대적 효력의 원칙).","src":"민법 제415조 | 민법 제423조"},{"t":"부담부분은 균등한 것으로 추정한다.","src":"민법 제424조"},{"t":"구상권: 변제 기타 출재로 공동면책이 된 연대채무자는 다른 연대채무자의 부담부분에 대하여 구상권을 행사할 수 있다. 구상권에는 면책된 날 이후의 법정이자 및 피할 수 없는 비용 기타 손해배상을 포함한다.","src":"민법 제425조 | 기출 2023-35"},{"t":"구상요건으로서의 통지: 다른 연대채무자에게 통지하지 않고 면책된 경우 다른 연대채무자가 채권자에게 대항할 사유가 있었다면 부담부분에 한하여 대항할 수 있다. 통지하지 않아 다른 연대채무자가 선의로 유상의 면책행위를 하면 그의 면책행위가 유효하다.","src":"민법 제426조"},{"t":"상환무자력자의 부담부분은 구상권자 및 다른 자력 있는 채무자가 부담부분에 비례하여 분담한다. 구상권자에게 과실이 있으면 분담을 청구하지 못한다.","src":"민법 제427조"}]},{"머리":"보증채무","줄":[{"t":"보증채무의 내용: 보증인은 주채무자가 이행하지 아니하는 채무를 이행할 의무가 있다. 장래의 채무에 대하여도 보증할 수 있다.","src":"민법 제428조 | 기출 2023-35"},{"t":"보증의 방식: 보증의 의사가 보증인의 기명날인 또는 서명이 있는 서면으로 표시되어야 효력이 발생한다. 전자적 형태의 의사표시는 효력이 없다. 보증채무를 불리하게 변경하는 경우에도 같다. 이행한 한도에서는 방식 하자를 이유로 무효를 주장할 수 없다.","src":"민법 제428조의2"},{"t":"근보증: 불확정한 다수의 채무에 대해서도 보증할 수 있되 최고액을 서면으로 특정하여야 한다. 최고액을 특정하지 않은 보증계약은 효력이 없다.","src":"민법 제428조의3"},{"t":"보증채무의 범위: 주채무의 이자, 위약금, 손해배상 기타 주채무에 종속한 채무를 포함한다. 보증인은 그 보증채무에 관한 위약금 기타 손해배상액을 예정할 수 있다. 부담이 주채무의 목적이나 형태보다 중한 때에는 주채무의 한도로 감축한다.","src":"민법 제429조 | 민법 제430조 | 기출 2023-35 | 기출 2025-34"},{"t":"보증인의 조건: 채무자가 보증인을 세울 의무가 있는 경우 행위능력 및 변제자력이 있는 자여야 한다. 자력이 없게 되면 채권자는 변경을 청구할 수 있다. 채권자가 지명한 경우는 적용하지 않는다. 채무자는 다른 상당한 담보를 제공하여 보증인을 세울 의무를 면할 수 있다.","src":"민법 제431조 | 민법 제432조"},{"t":"주채무자의 항변: 보증인은 주채무자의 항변으로 채권자에게 대항할 수 있다. 주채무자의 항변포기는 보증인에게 효력이 없다.","src":"민법 제433조 | 기출 2025-34"},{"t":"보증인은 주채무자의 채권에 의한 상계로 채권자에게 대항할 수 있다. 주채무자가 채권자에 대하여 취소권ㆍ해제권ㆍ해지권이 있는 동안 보증인은 채무의 이행을 거절할 수 있다.","src":"민법 제434조 | 민법 제435조 | 기출 2025-34"},{"t":"채권자의 정보제공의무와 통지의무: 보증계약 체결 시 알고 있는 주채무자의 채무 관련 신용정보를 보증인에게 알려야 한다. 체결 후 주채무자가 3개월 이상 이행하지 않거나 이행기에 이행할 수 없음을 미리 알거나 신용정보에 중대한 변화를 알게 된 때 지체 없이 알려야 한다. 보증인의 청구가 있으면 주채무의 내용 및 이행 여부를 알려야 한다. 위반하여 손해를 입히면 법원은 보증채무를 감경 또는 면제할 수 있다.","src":"민법 제436조의2"},{"t":"최고ㆍ검색의 항변: 채권자가 보증인에게 이행을 청구한 때 보증인은 주채무자의 변제자력이 있는 사실 및 집행이 용이할 것을 증명하여 먼저 주채무자에게 청구할 것과 그 재산에 집행할 것을 항변할 수 있다. 연대보증인은 불가. 채권자의 해태로 변제받지 못한 경우 해태하지 않았으면 변제받았을 한도에서 보증인은 의무를 면한다.","src":"민법 제437조 | 민법 제438조"},{"t":"공동보증의 분별의 이익: 수인의 보증인이 각자의 행위로 보증채무를 부담한 경우에도 제408조(균등 분할)를 적용한다.","src":"민법 제439조"},{"t":"주채무자에 대한 시효의 중단은 보증인에 대하여 그 효력이 있다.","src":"민법 제440조 | 기출 2023-35 | 기출 2025-34"},{"t":"수탁보증인의 구상권: 과실 없이 변제 기타 출재로 주채무를 소멸시킨 때 구상권이 있고, 면책된 날 이후의 법정이자 및 피할 수 없는 비용 기타 손해배상을 포함한다.","src":"민법 제441조 | 기출 2023-35"},{"t":"수탁보증인의 사전구상권(4가지): ① 과실 없이 채권자에게 변제할 재판을 받은 때 ② 주채무자가 파산선고를 받은 경우 채권자가 파산재단에 가입하지 않은 때 ③ 채무의 이행기가 확정되지 않고 최장기도 확정할 수 없는 경우 보증계약 후 5년을 경과한 때 ④ 채무의 이행기가 도래한 때. 제4호의 경우 보증계약 후 채권자가 주채무자에게 허여한 기한으로 보증인에게 대항하지 못한다.","src":"민법 제442조"},{"t":"주채무자의 면책청구: 사전구상에 응하는 주채무자는 자기를 면책하게 하거나 담보 제공을 청구하거나, 배상할 금액을 공탁하거나 담보를 제공하거나 보증인을 면책하게 하여 배상의무를 면할 수 있다.","src":"민법 제443조"},{"t":"부탁 없는 보증인의 구상권: 주채무자의 부탁 없이 보증인이 된 자는 주채무자가 그 당시 이익을 받은 한도에서, 주채무자의 의사에 반하여 보증인이 된 자는 현존이익의 한도에서 배상받는다.","src":"민법 제444조"},{"t":"통지: 보증인이 주채무자에게 통지하지 않고 변제한 경우 주채무자가 채권자에게 대항할 수 있는 사유로 보증인에게 대항할 수 있다. 주채무자가 면책을 부탁받은 보증인에게 통지하지 않은 경우 보증인이 선의로 변제하면 보증인의 면책행위가 유효하다.","src":"민법 제445조 | 민법 제446조"},{"t":"연대채무자ㆍ불가분채무자를 위한 보증인은 다른 연대채무자나 불가분채무자에 대하여 그 부담부분에 한하여 구상권이 있다. 공동보증인 간 구상은 자기 부담부분을 넘은 변제를 한 때 제444조를 준용하고, 주채무가 불가분이거나 상호연대·주채무자와 연대인 경우 제425조~제427조를 준용한다.","src":"민법 제447조 | 민법 제448조"}]},{"머리":"채권양도","줄":[{"t":"채권의 양도성: 채권은 양도할 수 있다. 채권의 성질이 양도를 허용하지 않으면 제외. 당사자가 반대의 의사표시(양도금지특약)를 한 경우 양도하지 못하나, 그 의사표시로 선의의 제3자에게 대항하지 못한다.","src":"민법 제449조"},{"t":"양도금지특약을 위반하여 채권을 양도한 경우 양수인이 특약을 과실 없이 알지 못하였다면(중대한 과실이 없다면) 양도는 유효하다. 양수인이 경과실로 특약을 알지 못한 경우에도 양수금을 청구할 수 있다.","src":"민법 제449조 제2항 | 기출 2022-34 | 기출 2023-34"},{"t":"대항요건: 양도인이 채무자에게 통지하거나 채무자가 승낙하지 않으면 채무자 기타 제3자에게 대항하지 못한다. 통지나 승낙은 확정일자 있는 증서에 의하지 않으면 채무자 이외의 제3자에게 대항하지 못한다.","src":"민법 제450조"},{"t":"양도통지는 양도인이 하여야 하나 양수인이 양도인의 대리인(또는 사자)으로서 통지에 관한 위임을 받았다면 양수인에 의한 양도통지도 유효하다.","src":"기출 2023-34 | 기출 2026-18"},{"t":"승낙의 효과: 채무자가 이의를 보류하지 않고 승낙한 때 양도인에게 대항할 수 있는 사유로 양수인에게 대항하지 못한다. 양도인이 통지만 한 때 채무자는 통지를 받은 때까지 양도인에 대하여 생긴 사유로 양수인에게 대항할 수 있다(통지 전 일부 변제 등).","src":"민법 제451조 | 기출 2022-34"},{"t":"이의를 보류하지 않은 승낙을 하였더라도 승낙 전에 상계적상에 있는 반대채권이 있고 양수인이 이를 알고 있었다면 채무자는 양수인의 청구에 대하여 상계로 대항할 수 있다.","src":"기출 2023-34 | 보충(추정)"},{"t":"양도통지와 금반언: 양도인이 채무자에게 양도를 통지한 때 아직 양도하지 않았거나 양도가 무효인 경우에도 선의인 채무자는 양수인에게 대항할 수 있는 사유로 양도인에게 대항할 수 있다. 통지는 양수인의 동의가 없으면 철회하지 못한다.","src":"민법 제452조 | 기출 2022-34"}]},{"머리":"채무인수","줄":[{"t":"채권자와의 계약에 의한 채무인수: 제3자는 채권자와의 계약으로 채무를 인수하여 채무자의 채무를 면하게 할 수 있다. 채무의 성질이 인수를 허용하지 않으면 제외. 이해관계 없는 제3자는 채무자의 의사에 반하여 인수하지 못한다.","src":"민법 제453조"},{"t":"채무자와의 계약에 의한 채무인수: 채권자의 승낙에 의하여 효력이 생긴다. 승낙 또는 거절의 상대방은 채무자나 제3자다. 제3자나 채무자는 상당 기간을 정해 승낙 여부의 확답을 최고할 수 있고 채권자가 기간 내에 확답을 발송하지 않으면 거절한 것으로 본다.","src":"민법 제454조 | 민법 제455조"},{"t":"채권자의 승낙이 있을 때까지 당사자는 인수를 철회하거나 변경할 수 있다. 승낙은 다른 의사표시가 없으면 인수한 때로 소급하나 제3자의 권리를 침해하지 못한다.","src":"민법 제456조 | 민법 제457조"},{"t":"인수인은 전채무자의 항변사유로 채권자에게 대항할 수 있다. 전채무자의 채무에 대한 보증이나 제3자가 제공한 담보는 채무인수로 소멸한다. 보증인이나 제3자가 채무인수에 동의한 경우는 제외.","src":"민법 제458조 | 민법 제459조"}]},{"머리":"변제","줄":[{"t":"변제의 제공: 채무내용에 좇은 현실제공으로 하여야 한다. 채권자가 미리 변제받기를 거절하거나 채무의 이행에 채권자의 행위를 요하는 경우 변제준비의 완료를 통지하고 수령을 최고하면 된다. 변제의 제공은 그때부터 채무불이행의 책임을 면하게 한다(채권이 소멸하는 것은 아니다).","src":"민법 제460조 | 민법 제461조 | 기출 2026-34"},{"t":"특정물의 현상인도: 이행기의 현상대로 인도한다.","src":"민법 제462조"},{"t":"타인의 물건 인도: 채무의 변제로 타인의 물건을 인도한 채무자는 다시 유효한 변제를 하지 아니하면 그 물건의 반환을 청구하지 못한다. 채권자가 변제로 받은 물건을 선의로 소비하거나 타인에게 양도한 때 그 변제는 효력이 있다(채권 소멸). 그 전에는 소유자가 반환을 청구할 수 있다.","src":"민법 제463조 | 민법 제465조 | 기출 2021-39 | 기출 2026-34"},{"t":"대물변제: 채무자가 채권자의 승낙을 얻어 본래의 채무이행에 갈음하여 다른 급여를 한 때 변제와 같은 효력이 있다.","src":"민법 제466조"},{"t":"변제의 장소: 장소를 정하지 않은 때 특정물의 인도는 채권성립 당시 그 물건이 있던 장소, 그 외 채무는 채권자의 현주소(영업에 관한 채무는 현영업소).","src":"민법 제467조 | 기출 2025-33"},{"t":"변제기 전의 변제: 특별한 의사표시가 없으면 변제기 전이라도 할 수 있으나 상대방의 손해는 배상하여야 한다.","src":"민법 제468조"},{"t":"제3자의 변제: 제3자도 변제할 수 있다. 채무의 성질 또는 당사자 의사표시로 허용하지 않는 때는 제외. 이해관계 없는 제3자는 채무자의 의사에 반하여 변제하지 못한다.","src":"민법 제469조 | 기출 2021-39 | 기출 2025-33"},{"t":"수령권한: 채권의 준점유자에 대한 변제는 변제자가 선의이며 과실 없는 때에 한하여 효력이 있다. 영수증 소지자에 대한 변제는 권한이 없어도 효력이 있으나 변제자가 권한 없음을 알았거나 알 수 있었을 경우는 제외. 그 외 권한 없는 자에 대한 변제는 채권자가 이익을 받은 한도에서 효력.","src":"민법 제470조~제472조 | 기출 2021-39 | 기출 2025-33 | 기출 2026-34"},{"t":"변제비용은 다른 의사표시가 없으면 채무자 부담. 채권자의 주소이전 등으로 증가된 부분은 채권자 부담. 변제자는 영수증을 청구할 수 있고, 채무 전부를 변제한 때 채권증서의 반환을 청구할 수 있다.","src":"민법 제473조 | 민법 제474조 | 민법 제475조"},{"t":"채권증서의 반환은 변제가 먼저 이루어진 후의 문제이며 변제와 동시이행 관계가 아니다(변제가 선이행).","src":"민법 제475조 | 기출 2021-39 | 기출 2026-34 | 보충(추정)"},{"t":"변제충당: 지정충당(변제자 우선, 그다음 변제받는 자. 변제자가 즉시 이의하면 불가) → 법정충당 순서 ① 이행기 도래한 것 ② 변제이익이 많은 것 ③ 이행기가 먼저 도래한 것 ④ 채무액에 비례. 비용ㆍ이자ㆍ원본이 있으면 비용, 이자, 원본의 순서로 충당한다.","src":"민법 제476조 | 민법 제477조 | 민법 제479조 | 기출 2025-33"}]},{"머리":"변제자대위","줄":[{"t":"임의대위: 채무자를 위하여 변제한 자는 변제와 동시에 채권자의 승낙을 얻어 채권자를 대위할 수 있다. 법정대위: 변제할 정당한 이익이 있는 자는 변제로 당연히 채권자를 대위한다(채권자 승낙 불요).","src":"민법 제480조 | 민법 제481조 | 기출 2025-33"},{"t":"대위의 효과: 자기의 권리에 의하여 구상할 수 있는 범위에서 채권 및 담보에 관한 권리를 행사할 수 있다. 보증인은 미리 전세권이나 저당권의 등기에 대위를 부기하지 아니하면 그 부동산에 권리를 취득한 제3자에 대하여 채권자를 대위하지 못한다. 제3취득자는 보증인에 대하여 채권자를 대위하지 못한다.","src":"민법 제482조"},{"t":"일부대위: 변제한 가액에 비례하여 채권자와 함께 권리를 행사한다. 계약의 해지 또는 해제는 채권자만이 할 수 있다.","src":"민법 제483조"},{"t":"채권자의 담보상실ㆍ감소: 법정대위자가 있는 경우 채권자의 고의나 과실로 담보가 상실되거나 감소된 때 대위할 자는 상환받을 수 없는 한도에서 책임을 면한다.","src":"민법 제485조"}]},{"머리":"공탁","줄":[{"t":"변제공탁: 채권자가 변제를 받지 아니하거나 받을 수 없는 때(과실 없이 채권자를 알 수 없는 경우 포함) 변제자는 변제의 목적물을 공탁하여 채무를 면할 수 있다.","src":"민법 제487조"},{"t":"공탁은 채무이행지의 공탁소에 하고, 공탁자는 지체없이 채권자에게 공탁통지를 하여야 한다.","src":"민법 제488조"},{"t":"공탁물의 회수: 채권자가 공탁을 승인하거나 공탁소에 받기를 통고하거나 공탁유효의 판결이 확정되기까지는 회수할 수 있다. 질권 또는 저당권이 공탁으로 소멸한 때는 회수 불가.","src":"민법 제489조"},{"t":"자조매각: 목적물이 공탁에 부적당하거나 멸실ㆍ훼손의 염려가 있거나 과다한 비용이 드는 경우 법원의 허가를 얻어 경매·방매하여 대금을 공탁할 수 있다. 채권자의 상대의무이행과 동시에 변제할 경우 채권자는 의무이행을 하지 아니하면 공탁물을 수령하지 못한다.","src":"민법 제490조 | 민법 제491조"}]},{"머리":"상계","줄":[{"t":"상계의 요건: 쌍방이 서로 같은 종류를 목적으로 한 채무를 부담하고 쌍방 채무의 이행기가 도래한 때 대등액에 관하여 상계할 수 있다. 채무의 성질이 허용하지 않으면 제외. 당사자가 다른 의사를 표시한 경우 적용하지 않으나 선의의 제3자에게 대항하지 못한다.","src":"민법 제492조"},{"t":"상계의 방법: 상대방에 대한 의사표시로 하며 조건 또는 기한을 붙이지 못한다. 상계의 의사표시는 각 채무가 상계할 수 있는 때에 대등액에 관하여 소멸한 것으로 본다(소급효).","src":"민법 제493조 | 기출 2021-22 | 기출 2026-22"},{"t":"이행지를 달리하는 채무도 상계할 수 있으나 상계하는 당사자는 상대방에게 상계로 인한 손해를 배상하여야 한다.","src":"민법 제494조"},{"t":"소멸시효 완성된 채권도 완성 전에 상계할 수 있었던 것이면 채권자는 상계할 수 있다.","src":"민법 제495조 | 기출 2025-24"},{"t":"상계 금지: 고의의 불법행위로 인한 채무의 채무자는 상계로 채권자에게 대항하지 못한다. 압류금지채권을 수동채권으로 하는 상계 금지. 지급을 금지하는 명령을 받은 제3채무자는 그 후 취득한 채권에 의한 상계로 대항하지 못한다.","src":"민법 제496조 | 민법 제497조 | 민법 제498조"},{"t":"상계에는 변제충당 규정(제476조~제479조)을 준용한다.","src":"민법 제499조"}]},{"머리":"경개ㆍ면제ㆍ혼동","줄":[{"t":"경개: 당사자가 채무의 중요한 부분을 변경하는 계약을 한 때 구채무는 경개로 소멸한다. 채무자 변경 경개는 채권자와 신채무자 간 계약으로 하되 구채무자의 의사에 반하지 못한다. 채권자 변경 경개는 확정일자 있는 증서로 하지 않으면 제3자에게 대항하지 못한다.","src":"민법 제500조~제503조"},{"t":"신채무가 원인의 불법 또는 당사자가 알지 못한 사유로 성립하지 않거나 취소된 때 구채무는 소멸되지 않는다. 구채무의 담보는 목적 한도에서 신채무의 담보로 할 수 있으나 제3자 제공 담보는 승낙이 필요하다.","src":"민법 제504조 | 민법 제505조"},{"t":"면제: 채권자가 채무자에게 채무를 면제하는 의사표시를 한 때 채권은 소멸한다. 면제로써 정당한 이익을 가진 제3자에게 대항하지 못한다.","src":"민법 제506조"},{"t":"혼동: 채권과 채무가 동일한 주체에 귀속한 때 채권은 소멸한다. 그 채권이 제3자의 권리의 목적인 때는 제외.","src":"민법 제507조"}]}],"함정":[{"x":"지명채권증서의 반환과 변제는 동시이행관계에 있다.","o":"동시이행관계가 아니다. 변제가 먼저다.","src":"기출 2021-39 | 기출 2026-34 | 보충(추정)"},{"x":"장래의 채무에 대한 보증계약은 효력이 없다.","o":"장래의 채무에 대하여도 보증할 수 있다.","src":"민법 제428조 제2항 | 기출 2023-35"},{"x":"주채무자에 대한 시효의 중단은 보증인에 대하여 그 효력이 없다.","o":"효력이 있다.","src":"민법 제440조 | 기출 2023-35 | 기출 2025-34"},{"x":"보증인은 그 보증채무에 관한 위약금 기타 손해배상액을 예정할 수 없다.","o":"예정할 수 있다.","src":"민법 제429조 제2항 | 기출 2023-35"},{"x":"보증인의 보증의사를 표시하기 위한 ‘기명날인’은 보증인이 직접 하여야 하고 타인이 이를 대행하는 방법으로 할 수 없다.","o":"출제 오답(바른 수치 미확인). 기명날인은 타인이 대행할 수 있다고 이해한다.","src":"기출 2023-35 | 보충(추정)"},{"x":"특정물의 인도는 특별한 사정이 없는 한 채권자의 현주소에서 하여야 한다.","o":"채권성립 당시 그 물건이 있던 장소에서 한다.","src":"민법 제467조 제1항 | 기출 2025-33"},{"x":"변제는 채무자에게 이익이 되므로, 이해관계 없는 제3자라도 채무자의 의사에 반하여 변제할 수 있다.","o":"이해관계 없는 제3자는 채무자의 의사에 반하여 변제하지 못한다.","src":"민법 제469조 제2항 | 기출 2025-33"},{"x":"변제할 정당한 이익이 있는 자는 채권자의 승낙을 얻어야만 변제로 채권자를 대위할 수 있다.","o":"변제로 당연히 채권자를 대위한다(법정대위).","src":"민법 제481조 | 기출 2025-33"},{"x":"변제충당은 원본, 이자, 비용의 순서에 의한다.","o":"비용, 이자, 원본의 순서다.","src":"민법 제479조 | 기출 2025-33"},{"x":"보증인의 보증채무는 주채무의 위약금이나 손해배상을 포함하지 않는다.","o":"포함한다.","src":"민법 제429조 제1항 | 기출 2025-34"},{"x":"주채무자의 항변포기는 보증인에게 효력이 있다.","o":"항변포기는 보증인에게 효력이 없다.","src":"민법 제433조 제2항 | 기출 2025-34"},{"x":"주채무자에 대한 시효의 중단은 보증인에 대하여 효력이 없다(2025-34 ㄹ).","o":"효력이 있다.","src":"민법 제440조 | 기출 2025-34"},{"x":"채무자가 변제의 제공을 하면 특별한 사정이 없는 한 채권은 소멸한다.","o":"채무불이행책임을 면할 뿐 채권이 소멸하지는 않는다.","src":"민법 제461조 | 기출 2026-34"},{"x":"이행인수인은 변제할 정당한 이익이 있는 자에 해당하지 않는다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2026-34"},{"x":"채무자가 채무의 변제로 타인의 물건을 채권자에게 인도한 경우, 그 물건의 소유자는 채권자에게 그 물건의 반환을 청구하지 못한다.","o":"채권자가 선의로 소비하거나 양도하기 전에는 소유자가 반환을 청구할 수 있다.","src":"민법 제465조 | 기출 2026-34 | 보충(추정)"},{"x":"채권양도의 통지는 양도인이 해야 하므로 丙이 甲의 대리인으로서 채권양도의 통지에 관한 위임을 받았더라도 丙에 의한 양도통지는 효력이 없다(2023-34 ㄱ).","o":"양도인의 대리인으로서 한 통지도 유효하다.","src":"기출 2023-34 | 기출 2026-18"},{"x":"공동임차인의 임대인에 대한 임차물반환의무는 불가분채무에 해당한다(2024-35 선지 4).","o":"기출 정답상 불가분채무에 해당하지 않는 것으로 출제되었다.","src":"기출 2024-35 | 보충(추정)"}]},"계약총론(성립ㆍ해제ㆍ해지ㆍ위험부담ㆍ계약금)":{"묶음":[{"머리":"계약의 성립(청약과 승낙)","줄":[{"t":"청약의 구속력: 계약의 청약은 이를 철회하지 못한다. 청약이 상대방에게 도달하여 효력이 발생하면 청약자는 임의로 철회하지 못한다.","src":"민법 제527조 | 기출 2021-34"},{"t":"승낙기간을 정한 청약: 청약자가 그 기간 내에 승낙의 통지를 받지 못한 때 효력을 잃는다(계약이 성립하지 않음). 승낙의 통지가 기간 후에 도달한 경우 보통 그 기간 내에 도달할 수 있는 발송이었다면 청약자는 지체 없이 연착의 통지를 하여야 하고, 하지 않으면 연착되지 않은 것으로 본다.","src":"민법 제528조 | 기출 2021-34 | 기출 2026-21"},{"t":"승낙기간을 정하지 않은 청약: 청약자가 상당한 기간 내에 승낙의 통지를 받지 못한 때 효력을 잃는다. 연착된 승낙은 청약자가 새 청약으로 볼 수 있다.","src":"민법 제529조 | 민법 제530조"},{"t":"격지자 간의 계약은 승낙의 통지를 발송한 때에 성립한다(도달 시가 아님).","src":"민법 제531조 | 기출 2021-34 | 기출 2023-19"},{"t":"의사실현에 의한 계약성립: 청약자의 의사표시나 관습에 의하여 승낙의 통지가 필요하지 않은 경우 계약은 승낙의 의사표시로 인정되는 사실이 있는 때 성립한다.","src":"민법 제532조 | 기출 2021-34"},{"t":"교차청약: 당사자 간에 동일한 내용의 청약이 상호교차된 경우 양 청약이 상대방에게 도달한 때 계약이 성립한다.","src":"민법 제533조 | 기출 2021-34 | 기출 2026-21"},{"t":"변경을 가한 승낙: 조건을 붙이거나 변경을 가하여 승낙한 때 그 청약의 거절과 동시에 새로 청약한 것으로 본다.","src":"민법 제534조"},{"t":"계약체결상의 과실: 목적이 원시적으로 불능한 계약을 체결할 때 그 불능을 알았거나 알 수 있었던 자는 상대방이 계약의 유효를 믿었음으로 인하여 받은 손해(신뢰이익)를 배상한다. 배상액은 이행이익을 넘지 못한다. 상대방이 불능을 알았거나 알 수 있었던 경우는 적용하지 않는다.","src":"민법 제535조"}]},{"머리":"동시이행의 항변권","줄":[{"t":"쌍무계약의 당사자 일방은 상대방이 그 채무이행을 제공할 때까지 자기의 채무이행을 거절할 수 있다. 상대방의 채무가 변제기에 있지 않은 때는 제외. 선이행 의무자도 상대방의 이행이 곤란할 현저한 사유가 있으면 거절할 수 있다.","src":"민법 제536조"},{"t":"해제로 인한 원상회복의무는 동시이행 관계다(제536조 준용).","src":"민법 제549조"},{"t":"하자확대손해로 인한 수급인의 손해배상채무와 도급인의 공사대금채무는 동시이행 관계다.","src":"기출 2024-37 | 기출 2026-38"}]},{"머리":"위험부담","줄":[{"t":"채무자위험부담주의: 쌍무계약의 당사자 일방의 채무가 당사자 쌍방의 책임 없는 사유로 이행할 수 없게 된 때 채무자는 상대방의 이행(반대급부)을 청구하지 못한다.","src":"민법 제537조 | 기출 2026-33"},{"t":"채권자 귀책사유로 인한 이행불능: 채권자의 책임 있는 사유로 이행할 수 없게 된 때 채무자는 상대방의 이행을 청구할 수 있다. 채권자의 수령지체 중에 쌍방의 책임 없는 사유로 이행할 수 없게 된 때에도 같다. 채무자는 자기 채무를 면함으로써 얻은 이익을 채권자에게 상환하여야 한다.","src":"민법 제538조 | 기출 2021-38"},{"t":"채무자의 과실로 목적물이 소실된 경우 채권자는 이행불능에 따른 손해배상을 청구할 수 있다. 이미 대금을 지급한 후 불가항력으로 목적물이 소실되면 채권자는 부당이득을 이유로 대금 반환을 청구할 수 있다.","src":"민법 제390조 | 기출 2021-38"}]},{"머리":"제3자를 위한 계약","줄":[{"t":"계약에 의하여 당사자 일방이 제3자에게 이행할 것을 약정한 때 제3자는 채무자에게 직접 그 이행을 청구할 수 있다. 제3자의 권리는 제3자가 채무자에 대하여 계약의 이익을 받을 의사를 표시한 때 생긴다.","src":"민법 제539조"},{"t":"채무자의 최고권: 상당한 기간을 정하여 향수 여부의 확답을 제3자에게 최고할 수 있고 확답을 받지 못하면 거절한 것으로 본다.","src":"민법 제540조"},{"t":"제3자의 권리가 생긴 후에는 당사자는 이를 변경 또는 소멸시키지 못한다. 채무자는 계약에 기한 항변으로 제3자에게 대항할 수 있다.","src":"민법 제541조 | 민법 제542조"}]},{"머리":"해제ㆍ해지의 요건","줄":[{"t":"방법: 해지 또는 해제는 상대방에 대한 의사표시로 한다. 이 의사표시는 철회하지 못한다(해지·해제 모두 도달 후 철회 불가).","src":"민법 제543조 | 기출 2023-36 | 기출 2025-35"},{"t":"이행지체와 해제: 상당한 기간을 정하여 이행을 최고하고 그 기간 내에 이행하지 않으면 해제할 수 있다. 채무자가 미리 이행하지 않을 의사를 표시한 경우 최고를 요하지 않는다.","src":"민법 제544조 | 기출 2026-38"},{"t":"정기행위: 계약의 성질 또는 당사자의 의사표시에 의하여 일정한 시일 또는 기간 내에 이행하지 아니하면 계약의 목적을 달성할 수 없는 경우 최고 없이 해제할 수 있다.","src":"민법 제545조 | 기출 2025-35"},{"t":"이행불능과 해제: 채무자의 책임 있는 사유로 이행이 불능하게 된 때 채권자는 계약을 해제할 수 있다. 이행불능을 이유로 해제할 때는 자기 채무(잔대금)의 이행제공이 필요하지 않다. 채권자의 귀책사유로 인한 이행불능이면 채권자는 해제할 수 없다.","src":"민법 제546조 | 기출 2023-36 | 기출 2024-38"},{"t":"부수적 채무의 불이행을 이유로 해제하려면 그로 인하여 계약의 목적을 달성할 수 없거나 특별한 약정이 있어야 한다.","src":"기출 2024-38 | 기출 2026-35"},{"t":"본래의 채권이 시효로 소멸한 경우 채권자는 시효완성 전의 그 채권에 대한 채무불이행을 이유로 계약을 해제할 수 없다.","src":"기출 2026-35"},{"t":"토지거래허가구역 내 토지매매계약이 유동적 무효인 경우 일방이 허가절차에 협력할 의무를 이행하지 않아도 상대방은 계약을 해제할 수 없다.","src":"기출 2026-35"},{"t":"해제권 불가분성: 당사자 일방 또는 쌍방이 수인인 경우 해지·해제는 전원으로부터 또는 전원에 대하여 하여야 한다. 해제권이 당사자 1인에 대하여 소멸한 때 다른 당사자에 대하여도 소멸한다.","src":"민법 제547조 | 기출 2023-36 | 기출 2024-38"},{"t":"해제권 행사 여부의 최고: 행사기간을 정하지 않은 때 상대방은 상당한 기간을 정하여 확답을 최고할 수 있다. 그 기간 내에 해제 통지를 받지 못하면 해제권은 소멸한다.","src":"민법 제552조"},{"t":"해제권의 소멸: 해제권자의 고의나 과실로 목적물이 현저히 훼손되거나 반환할 수 없게 된 때 또는 가공·개조로 다른 종류의 물건으로 변경된 때.","src":"민법 제553조"},{"t":"소를 제기하여 계약해제권을 행사한 후 나중에 소송을 취하해도 해제권 행사의 효력에는 영향이 없다.","src":"기출 2024-38 | 기출 2026-35"}]},{"머리":"해제ㆍ해지의 효과","줄":[{"t":"해제의 효과(원상회복): 각 당사자는 상대방에 대하여 원상회복의무가 있다. 제3자의 권리를 해하지 못한다. 반환할 금전에는 받은 날부터 이자를 가하여야 한다.","src":"민법 제548조 | 기출 2025-35"},{"t":"해제는 소급효가 있어 계약이 처음부터 없었던 것으로 된다(장래에 향하여 효력을 잃는 것은 해지).","src":"민법 제548조 | 기출 2025-35 | 보충"},{"t":"해지의 효과: 계약은 장래에 대하여 효력을 잃는다.","src":"민법 제550조"},{"t":"해지·해제는 손해배상의 청구에 영향을 미치지 않는다. 해제 후에도 채무불이행에 따른 손해배상을 별도로 청구할 수 있다.","src":"민법 제551조 | 기출 2023-36 | 기출 2021-40"},{"t":"일방 당사자의 계약위반으로 해제된 경우 계약을 위반한 당사자도 해제로 계약이 소멸되었음을 들어 이행을 거절할 수 있다.","src":"기출 2024-38"},{"t":"합의해지로 반환할 금전에는 별도 약정이 없는 한 받은 날부터의 이자를 더하여 지급할 의무가 없다.","src":"기출 2023-36"}]},{"머리":"합의해제","줄":[{"t":"일부 이행된 계약의 묵시적 합의해제가 인정되려면 원상회복에 관하여도 의사가 일치되어야 한다. 일방 당사자가 원상회복 및 손해배상의 범위에 관한 조건을 제시한 경우 그 조건에 관한 합의까지 이루어져야 합의해제가 성립한다.","src":"기출 2022-35"},{"t":"합의해제에는 해제에 관한 제543조 이하의 규정이 원칙적으로 적용되지 않는다. 따라서 채무불이행에 따른 손해배상을 원칙적으로 청구할 수 없다(특약이 있으면 제외).","src":"기출 2022-35 | 기출 2026-35"},{"t":"매매계약이 합의해제되면 원칙적으로 매수인에게 이전되었던 소유권은 당연히 매도인에게 복귀한다.","src":"기출 2022-35"}]},{"머리":"계약금(해약금)","줄":[{"t":"해약금: 매매 당사자 일방이 계약 당시 금전 기타 물건을 계약금·보증금 등의 명목으로 상대방에게 교부한 때, 다른 약정이 없는 한 당사자의 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 계약을 해제할 수 있다. 이 해제에는 제551조(손해배상)를 적용하지 않는다.","src":"민법 제565조"},{"t":"배액 상환에 의한 해제: 수령자가 배액을 제공하면 족하고 상대방이 수령하지 않는다고 해서 공탁까지 해야 하는 것은 아니다.","src":"기출 2022-36 | 보충(추정)"},{"t":"토지거래허가구역 내 토지의 매매계약에서 당사자가 이행에 착수하기 전에 토지거래허가를 받았다면 매수인은 계약금(3천만 원)을 포기하고 계약을 해제할 수 있다.","src":"기출 2022-36"}]}],"함정":[{"x":"격지자간의 계약은 승낙의 통지가 도달한 때에 성립한다.","o":"승낙의 통지를 발송한 때에 성립한다.","src":"민법 제531조 | 기출 2021-34 | 기출 2023-19"},{"x":"乙의 수령지체 중에 X주택이 甲과 乙에게 책임 없는 사유로 소실된 경우, 甲은 乙에게 대금지급을 청구할 수 없다.","o":"채권자의 수령지체 중이므로 대금지급을 청구할 수 있다.","src":"민법 제538조 제1항 | 기출 2021-38"},{"x":"계약이 합의해제된 경우, 원칙적으로 채무불이행에 따른 손해배상을 청구할 수 있다.","o":"원칙적으로 청구할 수 없다.","src":"기출 2022-35"},{"x":"乙이 甲에게 6천만 원을 상환하고 매매계약을 해제하려는 경우, 甲이 6천만 원을 수령하지 않는 때에는 乙은 이를 공탁해야 유효하게 해제할 수 있다.","o":"공탁까지는 필요하지 않다.","src":"민법 제565조 | 기출 2022-36 | 보충(추정)"},{"x":"해지의 의사표시는 도달되더라도 철회할 수 있으나 해제의 의사표시는 철회할 수 없다.","o":"해지·해제 모두 철회할 수 없다.","src":"민법 제543조 제2항 | 기출 2023-36"},{"x":"채무불이행을 원인으로 계약을 해제하면 그와 별도로 손해배상을 청구하지 못한다.","o":"해제와 별도로 손해배상을 청구할 수 있다.","src":"민법 제551조 | 기출 2023-36"},{"x":"당사자의 일방이 2인인 경우, 특별한 사정이 없는 한 그 중 1인의 해제권이 소멸하더라도 다른 당사자의 해제권은 소멸하지 않는다.","o":"1인에 대하여 소멸하면 다른 당사자에 대하여도 소멸한다.","src":"민법 제547조 제2항 | 기출 2023-36"},{"x":"소유권이전등기의무의 이행불능을 이유로 매매계약을 해제하기 위해서는 그와 동시이행관계에 있는 잔대금지급의무의 이행제공이 필요하다.","o":"이행제공이 필요하지 않다.","src":"기출 2023-36 | 보충(추정)"},{"x":"매도인의 소유권이전등기의무가 매수인의 귀책사유에 의해 이행불능이 된 경우, 매수인은 이를 이유로 계약을 해제할 수 있다.","o":"채권자(매수인)의 귀책사유로 인한 이행불능이면 해제할 수 없다.","src":"민법 제546조 | 기출 2024-38"},{"x":"확정기한부 채무의 경우, 채무자는 이행청구를 받은 때부터 지체책임을 지게 된다.","o":"기한이 도래한 때부터 지체책임을 진다.","src":"민법 제387조 | 기출 2025-35"},{"x":"채권자는 채무자에게 도달한 계약해제의 의사표시를 철회할 수 있다.","o":"철회할 수 없다.","src":"민법 제543조 | 기출 2025-35"},{"x":"계약해제로 채권자가 받은 금전을 반환해야 할 경우, 채권자는 그 원금만 반환하면 족하다.","o":"받은 날부터의 이자를 가산하여야 한다.","src":"민법 제548조 제2항 | 기출 2025-35"},{"x":"채권자가 매매계약을 해제하면 그 계약은 장래에 향하여 효력을 잃는다.","o":"해제는 소급하여 효력을 잃는다. 장래효는 해지다.","src":"민법 제548조ㆍ제550조 | 기출 2025-35"},{"x":"계약의 해제에 관한 민법 제543조 이하의 규정은 원칙적으로 합의해제에도 적용된다.","o":"원칙적으로 적용되지 않는다.","src":"기출 2026-35"}]},"계약각론(매매ㆍ임대차ㆍ도급ㆍ위임 등)":{"묶음":[{"머리":"전형계약(15가지)","줄":[{"t":"민법상 전형계약(15가지): 증여, 매매, 교환, 소비대차, 사용대차, 임대차, 고용, 도급, 여행계약, 현상광고, 위임, 임치, 조합, 종신정기금, 화해. 부당이득은 법정채권으로 전형계약이 아니다.","src":"기출 2021-33 | 민법 제554조~제733조(목차)"}]},{"머리":"증여","줄":[{"t":"증여는 당사자 일방이 무상으로 재산을 상대방에 수여하는 의사를 표시하고 상대방이 승낙함으로써 효력이 생긴다(낙성·무상·편무계약).","src":"민법 제554조"},{"t":"서면에 의하지 않은 증여는 각 당사자가 해제할 수 있다. 이미 이행한 부분에는 영향이 없다.","src":"민법 제555조 | 민법 제558조"},{"t":"수증자의 행위로 인한 해제: ① 증여자 또는 그 배우자나 직계혈족에 대한 범죄행위 ② 증여자에 대하여 부양의무 있는데 이행하지 않은 때. 해제권은 해제원인 있음을 안 날부터 6월이 경과하거나 증여자가 용서의 의사를 표시한 때 소멸한다.","src":"민법 제556조"},{"t":"증여자의 재산상태가 현저히 변경되고 그 이행이 생계에 중대한 영향을 미칠 경우 증여자는 해제할 수 있다.","src":"민법 제557조"},{"t":"증여자의 담보책임: 증여의 목적인 물건 또는 권리의 하자나 흠결에 대하여 책임을 지지 않는다. 증여자가 알고 고지하지 않은 때는 책임. 상대부담 있는 증여는 부담 한도에서 매도인과 같은 담보책임. 부담부증여에는 쌍무계약 규정을 적용한다.","src":"민법 제559조 | 민법 제561조"},{"t":"정기증여는 증여자 또는 수증자의 사망으로 효력을 잃는다. 사인증여에는 유증 규정을 준용한다.","src":"민법 제560조 | 민법 제562조"}]},{"머리":"매매의 성립ㆍ예약ㆍ효력","줄":[{"t":"매매: 당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 대금을 지급할 것을 약정함으로써 효력이 생긴다.","src":"민법 제563조"},{"t":"매매의 일방예약은 상대방(예약완결권자)이 매매를 완결할 의사를 표시하는 때에 매매의 효력이 생긴다. 의사표시의 기간을 정하지 않은 때 예약자는 상당한 기간을 정해 확답을 최고할 수 있고, 확답을 받지 못하면 예약은 효력을 잃는다.","src":"민법 제564조 | 기출 2024-33"},{"t":"예약완결권은 형성권이다. 예약완결권을 재판상 행사하는 경우 그 의사표시가 담긴 소장 부본이 제척기간 내에 상대방에게 송달되면 적법하게 행사한 것이다. 제척기간 도과 여부는 법원이 직권으로 조사한다.","src":"기출 2024-33 | 기출 2023-2"},{"t":"예약완결권의 제척기간(약정이 없으면 예약 성립일부터 10년)이 지나면 예약목적물인 부동산을 인도받아 점유하고 있어도 완결권은 소멸한다. 예약완결권은 가등기의 대상이 되며 채권자대위권의 목적이 될 수 있다.","src":"기출 2024-33 | 기출 2026-36 | 보충(추정)"},{"t":"매매예약 완결의 의사표시 전에 목적물이 멸실된 경우 완결의 의사표시를 하여도 매매의 효력은 발생하지 않는다. 甲만이 예약완결권을 가지는 예약을 ‘편무예약’이라고 한 선지는 정답이 아니었고, 甲이 완결권을 행사하려면 乙에게 대금 전액을 제공하여야 한다는 선지도 정답이 아니었다.","src":"기출 2024-33 | 기출 2026-36"},{"t":"매매계약의 비용은 당사자 쌍방이 균분하여 부담한다.","src":"민법 제566조 | 기출 2025-36"},{"t":"매매의 효력: 매도인은 목적이 된 권리를 이전하고 매수인은 대금을 지급하여야 하며 쌍방 의무는 특별한 약정이나 관습이 없으면 동시에 이행한다.","src":"민법 제568조"},{"t":"동일기한의 추정: 일방에 대한 의무이행의 기한이 있는 때 상대방의 의무이행에 대하여도 동일한 기한이 있는 것으로 추정한다. 대금지급장소: 목적물의 인도와 동시에 대금을 지급할 경우 그 인도장소에서 지급한다.","src":"민법 제585조 | 민법 제586조 | 기출 2025-36"},{"t":"과실의 귀속과 대금이자: 매매계약 후에도 인도하지 않은 목적물로부터 생긴 과실은 매도인에게 속한다. 매수인은 목적물의 인도를 받은 날부터 대금의 이자를 지급한다. 대금지급에 기한이 있으면 제외.","src":"민법 제587조"},{"t":"대금지급거절권: 목적물에 권리를 주장하는 자가 있어 매수인이 권리의 전부나 일부를 잃을 염려가 있는 때 그 위험의 한도에서 대금 지급을 거절할 수 있다. 매도인이 상당한 담보를 제공하면 제외. 매도인은 대금 공탁을 청구할 수 있다.","src":"민법 제588조 | 민법 제589조"},{"t":"환매: 매도인이 매매계약과 동시에 환매권을 보류한 때 영수한 대금과 매수인이 부담한 매매비용을 반환하고 목적물을 환매할 수 있다. 기간은 부동산 5년, 동산 3년을 넘지 못하고 연장하지 못한다. 기간을 정하지 않으면 부동산 5년, 동산 3년. 환매권 보류의 등기는 매매등기와 동시에 한다.","src":"민법 제590조~제592조"},{"t":"교환은 당사자 쌍방이 금전 이외의 재산권을 상호이전할 것을 약정함으로써 효력이 생긴다. 금전의 보충지급이 있으면 그 금전에 매매대금 규정을 준용한다.","src":"민법 제596조 | 민법 제597조"}]},{"머리":"매도인의 담보책임","줄":[{"t":"타인의 권리의 매매: 매도인은 그 권리를 취득하여 매수인에게 이전하여야 한다. 이전할 수 없는 때 매수인은 계약을 해제할 수 있다. 계약 당시 권리가 매도인에게 속하지 않음을 안 매수인은 손해배상을 청구하지 못한다(악의면 해제만).","src":"민법 제569조 | 민법 제570조 | 기출 2023-37 | 기출 2025-36"},{"t":"선의의 매도인(권리가 자기에게 속하지 않음을 모르고 판 경우): 이전할 수 없는 때 손해를 배상하고 계약을 해제할 수 있다. 매수인이 악의면 매도인은 이전할 수 없음을 통지하고 계약을 해제할 수 있다.","src":"민법 제571조"},{"t":"권리의 일부가 타인에게 속한 경우: 매수인은 그 부분의 비율로 대금감액을 청구할 수 있다(선의·악의 불문). 잔존부분만이면 매수하지 않았을 때 선의의 매수인은 계약 전부를 해제할 수 있다. 선의의 매수인은 감액청구 또는 해제 외에 손해배상도 청구할 수 있다(감액청구와 손해배상 병행 가능).","src":"민법 제572조 | 기출 2021-35"},{"t":"권리행사기간: 선의의 매수인은 사실을 안 날부터, 악의의 매수인은 계약한 날부터 1년 내에 행사하여야 한다.","src":"민법 제573조 | 기출 2021-35"},{"t":"수량부족·일부멸실(수량을 지정한 매매의 목적물이 부족되거나 일부가 계약 당시 이미 멸실): 매수인이 부족 또는 멸실을 알지 못한 때 제572조·제573조를 준용한다.","src":"민법 제574조"},{"t":"제한물권이 있는 경우: 목적물이 지상권·지역권·전세권·질권·유치권의 목적이 된 경우 매수인이 알지 못한 때 계약의 목적을 달성할 수 없는 경우에 한하여 해제할 수 있고 기타는 손해배상만 청구할 수 있다. 부동산을 위하여 존재할 지역권이 없거나 등기된 임대차계약이 있는 경우 준용. 매수인이 그 사실을 안 날부터 1년 내에 행사한다.","src":"민법 제575조"},{"t":"저당권·전세권의 행사: 매수인이 소유권을 취득할 수 없거나 취득한 소유권을 잃은 때 계약을 해제할 수 있다. 출재로 소유권을 보존한 때 상환을 청구할 수 있다. 손해를 받은 때 배상을 청구할 수 있다(매수인의 선의·악의를 묻지 않는다).","src":"민법 제576조 | 기출 2023-37"},{"t":"경매: 경락인은 채무자에게 계약의 해제 또는 대금감액을 청구할 수 있다. 채무자가 자력이 없으면 대금의 배당을 받은 채권자에게 반환을 청구할 수 있다. 채무자가 흠결을 알고 고지하지 않았거나 채권자가 알고 경매를 청구한 때 손해배상을 청구할 수 있다. 하자담보책임 규정은 경매에는 적용하지 않는다.","src":"민법 제578조 | 민법 제580조 제2항"},{"t":"채권매매: 채권의 매도인이 채무자의 자력을 담보한 때 매매계약 당시의 자력을 담보한 것으로 추정한다. 변제기에 도달하지 아니한 채권의 매도인이 자력을 담보한 때 변제기의 자력을 담보한 것으로 추정한다.","src":"민법 제579조 | 기출 2023-37"},{"t":"하자담보책임: 목적물에 하자가 있는 때 제575조 제1항을 준용한다. 매수인이 하자 있는 것을 알았거나 과실로 인하여 알지 못한 때에는 책임이 없다(선의·무과실 매수인만 보호).","src":"민법 제580조 | 기출 2025-36"},{"t":"종류매매: 종류로 지정한 목적물이 특정된 후 하자가 있으면 제580조를 준용한다. 매수인은 해제·손해배상을 하지 않고 하자 없는 물건을 청구할 수 있다.","src":"민법 제581조"},{"t":"하자담보 권리행사기간: 제580조·제581조(하자담보)에 의한 권리는 매수인이 그 사실을 안 날부터 6월 내에 행사하여야 한다. 제575조의 제한물권·등기된 임대차 등은 안 날부터 1년.","src":"민법 제582조 | 민법 제575조 제3항"},{"t":"담보책임과 동시이행: 제572조~제575조, 제580조, 제581조의 경우 제536조를 준용한다.","src":"민법 제583조"},{"t":"담보책임 면제 특약: 면제하는 특약을 한 경우에도 매도인이 알고 고지하지 않은 사실 및 제3자에게 권리를 설정 또는 양도한 행위에 대하여는 책임을 면하지 못한다.","src":"민법 제584조"}]},{"머리":"임대차의 성립과 대항력","줄":[{"t":"임대차: 당사자 일방이 상대방에게 목적물을 사용·수익하게 할 것을 약정하고 상대방이 차임을 지급할 것을 약정함으로써 효력이 생긴다.","src":"민법 제618조"},{"t":"처분능력·권한 없는 자의 단기임대차 한도: 식목·채염 또는 석조·석회조·연와조 등 건축 목적의 토지 임대차 10년, 기타 토지 5년, 건물 기타 공작물 3년, 동산 6월. 갱신은 기간 만료 전 토지 1년, 건물 3월, 동산 1월 내에 하여야 한다.","src":"민법 제619조 | 민법 제620조"},{"t":"임대차의 등기: 부동산임차인은 반대약정이 없으면 임대인에 대하여 등기절차에 협력할 것을 청구할 수 있다. 등기한 때부터 제3자에 대하여 효력이 생긴다.","src":"민법 제621조 | 기출 2021-28 | 기출 2025-25"},{"t":"건물등기 있는 차지권: 건물 소유를 목적으로 한 토지임대차는 등기하지 않았어도 임차인이 지상건물을 등기한 때 제3자에 대하여 효력이 생긴다. 건물이 임대차기간 만료 전에 멸실·후폐하면 효력을 잃는다.","src":"민법 제622조 | 기출 2022-37"},{"t":"토지임차권 등기를 하지 않았더라도 지상건물 등기로 제3자에게 대항할 수 있다.","src":"민법 제622조 | 기출 2022-37"}]},{"머리":"임대인의 의무와 임차인의 권리","줄":[{"t":"임대인의 의무: 목적물을 임차인에게 인도하고 계약존속 중 사용·수익에 필요한 상태를 유지하게 할 의무를 부담한다.","src":"민법 제623조 | 기출 2022-37"},{"t":"보존행위: 임대인이 임대물의 보존에 필요한 행위를 하는 때 임차인은 거절하지 못한다. 임대인이 임차인의 의사에 반하여 보존행위를 하여 임차의 목적을 달성할 수 없는 때 임차인은 계약을 해지할 수 있다.","src":"민법 제624조 | 민법 제625조 | 기출 2022-37"},{"t":"임차인의 상환청구: 필요비는 즉시 상환 청구. 유익비는 임대차 종료 시 가액의 증가가 현존한 때에 한하여 임대인이 지출금액이나 증가액을 상환(법원이 임대인 청구로 상환기간 허여 가능). 점유자 유익비상환청구권과 같이 청구권이다.","src":"민법 제626조"},{"t":"일부멸실 등: 임차물의 일부가 임차인의 과실 없이 멸실 기타 사유로 사용·수익할 수 없는 때 그 부분의 비율로 차임감액을 청구할 수 있다. 잔존부분으로 목적을 달성할 수 없는 때 해지할 수 있다.","src":"민법 제627조"},{"t":"차임증감청구권: 공과부담의 증감 기타 경제사정의 변동으로 약정한 차임이 상당하지 않게 된 때 장래에 대한 차임의 증감을 청구할 수 있다.","src":"민법 제628조"},{"t":"임차인의 통지의무: 임차물의 수리를 요하거나 임차물에 대하여 권리를 주장하는 자가 있는 때 지체 없이 임대인에게 통지하여야 한다. 임대인이 이미 안 때 제외.","src":"민법 제634조"},{"t":"차임의 지급시기: 동산·건물·대지는 매월 말, 기타 토지는 매년 말. 수확기 있는 것은 수확 후 지체 없이.","src":"민법 제633조"}]},{"머리":"임차권의 양도ㆍ전대","줄":[{"t":"임차인은 임대인의 동의 없이 임차권을 양도하거나 임차물을 전대하지 못한다. 위반 시 임대인은 계약을 해지할 수 있다.","src":"민법 제629조"},{"t":"전대의 효과: 임대인의 동의를 얻어 전대한 때 전차인은 직접 임대인에 대하여 의무를 부담한다. 전차인은 전대인에 대한 차임 지급으로써 임대인에게 대항하지 못한다(차임 지급시기 이전의 선급은 대항 불가, 지급시기 이후 지급이나 임대인의 차임청구 전에 지급시기가 도래한 지급은 대항 가능). 임대인의 임차인에 대한 권리행사에 영향이 없다.","src":"민법 제630조 | 기출 2024-36"},{"t":"전차인의 의무 한도: 전차인은 전대차계약으로 전대인에 대하여 부담하는 의무 이상으로, 또 임대차계약으로 임차인이 임대인에 대하여 부담하는 의무 이상으로 임대인에게 의무를 지지 않는다(둘 중 작은 것).","src":"기출 2024-36 | 기출 2026-37"},{"t":"전차인의 권리 확정: 임대인의 동의를 얻어 전대한 경우 임대인과 임차인의 합의로 계약을 종료한 때에도 전차인의 권리는 소멸하지 않는다.","src":"민법 제631조 | 기출 2026-37"},{"t":"건물의 임차인이 건물의 소부분을 타인에게 사용하게 하는 경우 제629조~제631조는 적용되지 않는다.","src":"민법 제632조"},{"t":"해지통고의 전차인에 대한 통지: 임대차계약이 해지의 통고로 종료된 경우 그 임대물이 적법하게 전대되었을 때 임대인은 전차인에 대하여 그 사유를 통지하지 않으면 해지로써 전차인에게 대항하지 못한다. 차임연체 등 임차인 채무불이행을 이유로 한 해지에는 전차인에 대한 통지가 필요하지 않다.","src":"민법 제638조 | 기출 2024-36 | 기출 2026-37 | 보충(추정)"},{"t":"전차인의 부속물매수청구: 임대인의 동의를 얻어 부속한 물건이나 임대인으로부터 매수하였거나 동의를 얻어 임차인으로부터 매수한 부속물에 대하여 전대차 종료 시 임대인에게 매수를 청구할 수 있다.","src":"민법 제647조 | 기출 2026-37"},{"t":"임대차와 전대차가 모두 종료된 경우 전차인이 목적물을 임대인에게 직접 인도하면 전대인에 대한 인도의무를 면한다.","src":"기출 2026-37"}]},{"머리":"임대차의 종료","줄":[{"t":"기간의 약정이 없는 임대차: 언제든지 해지통고를 할 수 있다. 상대방이 통고를 받은 날부터 토지·건물 기타 공작물은 임대인 통고 6월, 임차인 통고 1월, 동산은 5일이 경과하면 해지의 효력이 생긴다.","src":"민법 제635조"},{"t":"기간의 약정이 있는 경우에도 당사자 일방 또는 쌍방이 그 기간 내에 해지할 권리를 보류한 때 제635조를 준용한다. 임차인이 파산선고를 받은 경우 약정기간이 있어도 임대인 또는 파산관재인은 해지통고할 수 있고 각 당사자는 손해배상을 청구하지 못한다.","src":"민법 제636조 | 민법 제637조"},{"t":"묵시의 갱신: 임대차기간 만료 후 임차인이 사용·수익을 계속하는 경우 임대인이 상당한 기간 내에 이의를 하지 아니한 때 전임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 당사자는 제635조에 의한 해지통고를 할 수 있다. 전임대차에 대하여 제3자가 제공한 담보는 기간 만료로 소멸한다.","src":"민법 제639조"},{"t":"차임연체와 해지: 건물 기타 공작물의 임대차에서 차임연체액이 2기의 차임액에 달하는 때 임대인은 계약을 해지할 수 있다. 건물 기타 공작물의 소유 또는 식목·채염·목축 목적의 토지임대차에도 준용한다.","src":"민법 제640조 | 민법 제641조 | 기출 2022-37"},{"t":"토지임차인의 갱신청구권·매수청구권: 건물 기타 공작물의 소유 또는 식목·채염·목축을 목적으로 한 토지임대차의 기간 만료 시 건물·수목 기타 지상시설이 현존한 때 제283조를 준용한다(지상물매수청구권은 형성권).","src":"민법 제643조 | 기출 2021-4 | 기출 2025-37"},{"t":"전차인의 임대청구권·매수청구권: 건물 기타 공작물의 소유 등을 목적으로 한 토지임차인이 적법하게 토지를 전대한 경우, 임대차 및 전대차의 기간이 동시에 만료되고 지상시설이 현존하면 전차인은 임대인에게 전전대차와 동일한 조건으로 임대할 것을 청구할 수 있다. 임대인이 원하지 않으면 제283조 제2항을 준용한다. 건물 전차인에게는 이 청구권이 없다.","src":"민법 제644조 | 민법 제645조 | 기출 2024-36"},{"t":"임차인의 부속물매수청구권: 건물 기타 공작물의 임차인이 사용의 편익을 위하여 임대인의 동의를 얻어 부속한 물건이나 임대인으로부터 매수한 부속물에 대하여 임대차 종료 시 매수를 청구할 수 있다. 토지임차인에게는 지상물매수청구권이 있고 부속물매수청구권은 건물 임차인의 권리다.","src":"민법 제646조 | 기출 2025-37"},{"t":"토지임차인이 임대인에게 행사할 수 있는 권리: 비용상환청구권, 차임감액청구권, 계약갱신청구권, 건물(지상물)매수청구권. 부속물매수청구권은 건물 임차인에게 인정된다.","src":"민법 제626조 | 민법 제628조 | 민법 제643조 | 기출 2025-37"},{"t":"법정질권·법정저당권: 토지임대인이 변제기를 경과한 최후 2년의 차임채권에 의하여 지상 임차인 소유 건물을 압류한 때 저당권과 동일한 효력이 있다. 토지임대인이 임대차에 관한 채권에 의하여 임차지에 부속한 임차인 소유 동산 및 과실을 압류한 때, 건물 임대인이 부속한 임차인 소유 동산을 압류한 때 질권과 동일한 효력이 있다.","src":"민법 제648조 | 민법 제649조 | 민법 제650조 | 기출 2022-37"},{"t":"강행규정: 제627조, 제628조, 제631조, 제635조, 제638조, 제640조, 제641조, 제643조~제647조에 위반하는 약정으로 임차인이나 전차인에게 불리한 것은 효력이 없다. 일시사용을 위한 임대차에는 제628조, 제638조, 제640조, 제646조~제648조, 제650조 및 제652조를 적용하지 않는다.","src":"민법 제652조 | 민법 제653조"}]},{"머리":"도급","줄":[{"t":"도급: 당사자 일방이 어느 일을 완성할 것을 약정하고 상대방이 그 일의 결과에 대하여 보수를 지급할 것을 약정함으로써 효력이 생긴다. 부대체물을 제작하여 공급하는 계약도 도급의 성질을 갖는다(제작물공급계약).","src":"민법 제664조 | 기출 2022-38"},{"t":"수급인은 특약 등 특별한 사정이 없는 한 제3자를 사용하여 일을 완성할 수 있다(직접 완성할 필요 없음).","src":"기출 2021-36 | 기출 2022-38 | 기출 2024-37"},{"t":"보수의 지급시기: 완성된 목적물의 인도와 동시에 지급한다. 목적물의 인도를 요하지 않는 경우 일을 완성한 후 지체 없이 지급한다. 보수 일부를 선급하기로 하는 특약이 있으면 수급인은 그 제공이 있을 때까지 일의 착수를 거절할 수 있다.","src":"민법 제665조 | 기출 2022-38 | 기출 2023-38"},{"t":"제작물공급계약에서 완성된 목적물의 인도와 동시에 보수를 지급해야 하는 경우, 목적물의 인도는 단순한 점유의 이전만으로 충분하지 않다.","src":"기출 2022-38 | 보충(추정)"},{"t":"수급인의 저당권설정청구권: 부동산공사의 수급인은 보수에 관한 채권을 담보하기 위하여 그 부동산을 목적으로 한 저당권의 설정을 청구할 수 있다.","src":"민법 제666조 | 기출 2023-38"},{"t":"완성된 주택을 도급인이 원시취득한 경우 수급인은 보수를 지급받을 때까지 그 주택에 유치권을 행사할 수 있다.","src":"기출 2021-36"},{"t":"수급인의 담보책임: 완성된 목적물 또는 완성 전의 성취된 부분에 하자가 있는 때 도급인은 상당한 기간을 정하여 보수를 청구할 수 있다. 하자가 중요하지 않은 경우 보수에 과다한 비용이 들 때는 보수를 청구할 수 없다. 보수에 갈음하여 또는 보수와 함께 손해배상을 청구할 수 있다(동시이행).","src":"민법 제667조 | 기출 2022-38 | 기출 2023-38"},{"t":"도급인의 해제권: 하자로 계약의 목적을 달성할 수 없는 때 해제할 수 있다. 단 건물 기타 토지의 공작물에 대하여는 해제할 수 없다. 완성된 주택의 하자로 목적을 달성할 수 없어도 해제할 수 없다.","src":"민법 제668조 | 기출 2021-36"},{"t":"도급인이 제공한 재료의 성질 또는 지시에 기인한 하자는 면책된다. 단 수급인이 부적당함을 알고 고지하지 않은 때는 책임.","src":"민법 제669조"},{"t":"담보책임의 존속기간: 하자의 보수·손해배상 청구 및 해제는 목적물의 인도를 받은 날부터 1년 내(인도를 요하지 않는 경우 일의 종료일부터). 토지·건물 기타 공작물은 인도 후 5년(석조·석회조·연와조·금속 기타 유사한 재료는 10년). 멸실·훼손된 때는 그 날부터 1년 내 행사한다.","src":"민법 제670조 | 민법 제671조"},{"t":"담보책임 면제 특약: 수급인이 담보책임이 없음을 약정한 경우에도 알고 고지하지 아니한 사실에 대하여는 책임을 면하지 못한다.","src":"민법 제672조"},{"t":"완성 전의 도급인의 해제권: 수급인이 일을 완성하기 전에는 도급인은 손해를 배상하고 계약을 해제할 수 있다.","src":"민법 제673조 | 기출 2021-36 | 기출 2023-38"},{"t":"도급인의 파산: 도급인이 파산선고를 받은 때 수급인 또는 파산관재인은 계약을 해제할 수 있다. 수급인은 완성된 부분에 대한 보수 및 비용에 대하여 파산재단의 배당에 가입할 수 있다. 각 당사자는 계약해제로 인한 손해배상을 청구하지 못한다.","src":"민법 제674조 | 기출 2021-36 | 기출 2024-37 | 기출 2026-38"},{"t":"수급인이 미리 계약을 이행하지 않을 의사를 표시한 경우 도급인은 최고 없이 해제할 수 있다.","src":"민법 제544조 | 기출 2026-38"},{"t":"지체상금: 완공기한을 넘겨 도급계약이 해제된 경우 지체상금의 발생 시기는 완공기한 다음 날이다. 선급금 지급을 도급인이 지체한 기간은 지체상금 발생기간에서 공제된다.","src":"기출 2024-37"},{"t":"하자보수에 갈음한 손해배상청구권은 하자가 발생하여 보수가 필요하게 된 시점에서 성립한다. 하자확대손해로 인한 수급인의 손해배상채무와 도급인의 공사대금채무는 동시이행 관계다.","src":"기출 2024-37 | 기출 2026-38"},{"t":"도급인이 공사대금을 지급하기 곤란한 현저한 사유가 있으면 수급인은 동시이행의 항변권(제536조 제2항)에 의하여 공사 완공의무를 거절할 수 있다.","src":"민법 제536조 제2항 | 기출 2026-38"}]},{"머리":"위임","줄":[{"t":"위임: 당사자 일방이 상대방에 대하여 사무의 처리를 위탁하고 상대방이 이를 승낙함으로써 효력이 생긴다.","src":"민법 제680조"},{"t":"수임인의 선관의무: 위임의 본지에 따라 선량한 관리자의 주의로 위임사무를 처리하여야 한다(자기 재산과 동일한 주의가 아님).","src":"민법 제681조 | 기출 2025-38"},{"t":"복임권의 제한: 위임인의 승낙이나 부득이한 사유 없이 제3자로 하여금 자기에 갈음하여 위임사무를 처리하게 하지 못한다.","src":"민법 제682조 | 기출 2025-38"},{"t":"보고의무: 위임인의 청구가 있는 때 처리상황을 보고하고 위임이 종료한 때 지체 없이 그 전말을 보고한다. 취득물 등의 인도: 위임사무 처리로 받은 금전 기타 물건 및 과실을 위임인에게 인도하고 자기 명의로 취득한 권리를 이전한다. 위임인에게 인도할 금전을 소비한 때 소비한 날 이후의 이자와 손해배상.","src":"민법 제683조~제685조"},{"t":"수임인의 보수청구: 특별한 약정이 없으면 위임인에 대하여 보수를 청구하지 못한다(무보수가 원칙). 보수를 받을 경우 위임사무 완료 후 청구(기간으로 정한 때에는 그 기간 경과 후). 수임인의 책임 없는 사유로 위임이 종료된 때 이미 처리한 사무 비율에 따른 보수를 청구할 수 있다.","src":"민법 제686조 | 기출 2025-38"},{"t":"비용: 위임사무의 처리에 비용을 요하는 때 위임인은 수임인의 청구에 의하여 선급한다. 필요비 지출 시 지출한 날 이후의 이자 청구. 필요한 채무를 부담한 때 위임인에게 대신 변제하게 하거나 담보를 제공하게 할 수 있다. 과실 없이 받은 손해의 배상 청구.","src":"민법 제687조 | 민법 제688조 | 기출 2025-38"},{"t":"위임의 해지: 각 당사자가 언제든지 해지할 수 있다. 부득이한 사유 없이 상대방의 불리한 시기에 해지한 때 손해를 배상하여야 한다(불리한 시기에도 해지는 가능).","src":"민법 제689조 | 기출 2025-38"},{"t":"위임의 종료: 당사자 한쪽의 사망이나 파산으로 종료한다. 수임인이 성년후견개시의 심판을 받은 경우에도 같다. 급박한 사정이 있으면 수임인 등은 위임인 등이 처리할 수 있을 때까지 처리를 계속한다. 종료사유는 상대방에게 통지하거나 상대방이 안 때가 아니면 대항하지 못한다.","src":"민법 제690조~제692조"}]}],"함정":[{"x":"도급인의 파산선고로 수급인이 계약을 해제한 경우, 수급인은 도급인에 대하여 계약 해제로 인한 손해배상을 청구할 수 있다.","o":"각 당사자는 계약해제로 인한 손해배상을 청구하지 못한다.","src":"민법 제674조 제2항 | 기출 2021-36"},{"x":"X토지에 대한 임차권등기를 하지 않았다면 특별한 사정이 없는 한 乙은 X토지에 대한 임차권으로 제3자에게 대항하지 못한다.","o":"건물 소유 목적의 토지임대차는 임차인이 지상건물을 등기하면 제3자에게 대항할 수 있다.","src":"민법 제622조 | 기출 2022-37"},{"x":"제작물공급계약에서 완성된 목적물의 인도와 동시에 보수(報酬)를 지급해야 하는 경우, 특별한 사정이 없는 한 목적물의 인도는 단순한 점유의 이전만으로 충분하다.","o":"단순한 점유 이전만으로는 충분하지 않다.","src":"기출 2022-38 | 보충(추정)"},{"x":"乙은 단순히 그 200 m2 부분이 丙에게 속한 사실을 안 날로부터 1년 내에 손해배상청구권을 행사하여야 한다(2021-35 ㄹ).","o":"출제 오답(바른 수치 미확인). 제573조의 행사기간은 선의 매수인 안 날, 악의 매수인 계약한 날부터 1년이다.","src":"민법 제573조 | 기출 2021-35"},{"x":"매매의 목적 부동산에 설정된 저당권 행사로 매수인이 그 소유권을 취득할 수 없는 경우, 저당권 설정 사실에 관하여 악의의 매수인은 그 입은 손해의 배상을 청구할 수 없다.","o":"매수인의 선의·악의를 묻지 않고 손해배상을 청구할 수 있다.","src":"민법 제576조 | 기출 2023-37"},{"x":"매매의 목적이 된 권리가 타인에게 속하여 매도인이 그 권리를 취득한 후 매수인에게 이전할 수 없는 때에는 매수인이 계약 당시 그 권리가 매도인에게 속하지 아니함을 알았더라도 손해배상을 청구할 수 있다.","o":"악의의 매수인은 손해배상을 청구하지 못한다(해제만).","src":"민법 제570조 | 기출 2023-37"},{"x":"하자보수에 관한 담보책임이 없음을 약정한 경우에는 수급인이 하자에 관하여 알고서 고지하지 아니한 사실에 대하여 담보책임이 없다.","o":"알고 고지하지 않은 사실에 대하여는 책임을 면하지 못한다.","src":"민법 제672조 | 기출 2023-38"},{"x":"예약목적물인 부동산을 인도받은 경우, 예약완결권은 제척기간의 경과로 인하여 소멸하지 않는다.","o":"인도받아도 제척기간 경과로 소멸한다.","src":"기출 2024-33 | 기출 2026-36 | 보충(추정)"},{"x":"건물전차인은 임대차 및 전대차의 기간이 동시에 만료되고 건물이 현존하는 경우, 특별한 사정이 없는 한 임대인에 대하여 이전 전대차와 동일한 조건으로 임대할 것을 청구할 수 있다.","o":"이 청구권은 건물 소유 등을 목적으로 한 토지 전차인에게 인정된다.","src":"민법 제644조 | 기출 2024-36"},{"x":"하자확대손해로 인한 수급인의 손해배상채무와 도급인의 공사대금채무는 동시이행 관계가 인정되지 않는다.","o":"동시이행 관계가 인정된다.","src":"기출 2024-37 | 기출 2026-38"},{"x":"매매목적물에 하자가 있다는 사실을 과실로 알지 못한 매수인은 매도인에 대하여 하자담보책임을 물을 수 있다.","o":"선의이며 과실이 없는 매수인만 물을 수 있다.","src":"민법 제580조 | 기출 2025-36"},{"x":"민법상 건물의 소유를 목적으로 한 토지임차인이 토지소유자인 임대인에게 행사할 수 있는 권리는 부속물매수청구권이다(2025-37 정답 선지 3은 ‘아닌 것’).","o":"부속물매수청구권은 토지임차인의 권리가 아니다. 지상물(건물)매수청구권이 있다.","src":"민법 제643조ㆍ제646조 | 기출 2025-37"},{"x":"위임인은 수임인에 대하여 보수를 지급하여야 함이 원칙이다.","o":"특별한 약정이 없으면 보수를 청구하지 못한다(무상이 원칙).","src":"민법 제686조 | 기출 2025-38"},{"x":"수임인은 자기재산과 동일한 주의로 위임사무를 처리하여야 한다.","o":"선량한 관리자의 주의로 처리한다.","src":"민법 제681조 | 기출 2025-38"},{"x":"위임인의 승낙이나 부득이한 사유가 없더라도 수임인은 제3자로 하여금 자기에 갈음하여 위임사무를 처리하게 할 수 있다.","o":"승낙이나 부득이한 사유 없이는 못한다.","src":"민법 제682조 | 기출 2025-38"},{"x":"수임인은 위임인의 불리한 시기에 위임계약을 해지하지 못한다.","o":"언제든 해지할 수 있고 부득이한 사유 없이 불리한 시기에 해지하면 손해를 배상한다.","src":"민법 제689조 | 기출 2025-38"},{"x":"乙의 차임연체로 甲이 임대차계약을 해지한 경우, 甲이 이를 丙에게 통지하지 않으면 그 해지로써 丙에게 대항할 수 없다.","o":"해지통고(제635조)에 의한 종료와 달리 차임연체 해지에는 전차인에 대한 통지가 필요하지 않다.","src":"민법 제638조 | 기출 2026-37 | 보충(추정)"},{"x":"도급인이 공사대금을 지급하기 곤란한 현저한 사유가 있더라도 수급인은 그 사유를 이유로 공사 완공의무를 거절할 수 없다.","o":"제536조 제2항에 의해 거절할 수 있다.","src":"민법 제536조 제2항 | 기출 2026-38"},{"x":"부당이득은 민법이 규정하고 있는 전형계약이다(2021-33 정답 선지 1).","o":"부당이득은 전형계약이 아니다.","src":"기출 2021-33"}]},"부당이득":{"묶음":[{"머리":"부당이득의 요건","줄":[{"t":"부당이득: 법률상 원인 없이 타인의 재산 또는 노무로 인하여 이익을 얻고 이로 인하여 타인에게 손해를 가한 자는 그 이익을 반환하여야 한다.","src":"민법 제741조"},{"t":"부당이득은 법정채권이며 전형계약이 아니다.","src":"기출 2021-33"},{"t":"횡령한 금전으로 자신의 채권자에게 변제한 경우 채권자가 변제 수령 시 횡령 사실을 알았거나 모른 데 중대한 과실이 있으면 채권자의 금전취득은 피해자에 대한 관계에서 법률상 원인이 없다(악의 또는 중과실 시).","src":"기출 2022-39 | 보충(추정)"},{"t":"연대보증인이 있는 주채무를 제3자가 변제하여 주채무가 소멸한 경우, 제3자는 연대보증인에게 부당이득반환을 청구할 수 없다.","src":"기출 2022-39"},{"t":"임차인이 임대차계약 종료 후 임차건물을 계속 점유하였더라도 이익을 얻지 않았다면 부당이득반환의무를 지지 않는다.","src":"기출 2022-39"},{"t":"과반수 지분의 공유자로부터 공유물의 사용·수익을 허락받아 점유하고 있는 제3자에 대하여 소수지분권자는 점유로 인한 부당이득반환을 청구할 수 없다.","src":"기출 2022-39"},{"t":"토지소유자가 독점적·배타적 사용수익권을 포기하여 공중의 이용에 제공한 경우 토지의 점유자를 상대로 부당이득반환을 청구할 수 없다.","src":"기출 2026-39"},{"t":"채무 없음을 알면서도 자기의 자유로운 의사에 반하여 변제를 강제당한 경우 변제자는 부당이득반환청구권을 상실하지 않는다.","src":"기출 2022-39"}]},{"머리":"비채변제 등 반환청구의 제한","줄":[{"t":"비채변제: 채무 없음을 알고 변제한 때에는 반환을 청구하지 못한다.","src":"민법 제742조 | 기출 2023-39 | 기출 2026-39"},{"t":"기한 전의 변제: 변제기에 있지 않은 채무를 변제한 때 반환을 청구하지 못한다. 단 채무자가 착오로 변제한 때 채권자는 이로 인하여 얻은 이익(중간이자)을 반환하여야 한다.","src":"민법 제743조 | 기출 2023-39"},{"t":"도의관념에 적합한 비채변제: 채무 없는 자가 착오로 변제한 경우 그 변제가 도의관념에 적합한 때에는 반환을 청구하지 못한다.","src":"민법 제744조 | 기출 2024-39 | 기출 2026-39"},{"t":"타인의 채무의 변제: 채무자 아닌 자가 착오로 타인의 채무를 변제한 경우 채권자가 선의로 증서를 훼멸하거나 담보를 포기하거나 시효로 채권을 잃은 때 변제자는 반환을 청구하지 못한다. 변제자는 채무자에게 구상권을 행사할 수 있다.","src":"민법 제745조"},{"t":"불법원인급여: 불법의 원인으로 재산을 급여하거나 노무를 제공한 때 이익의 반환을 청구하지 못한다. 불법원인이 수익자에게만 있는 때에는 반환을 청구할 수 있다.","src":"민법 제746조 | 기출 2023-39"},{"t":"불법원인급여로 부당이득반환청구가 불가능한 경우 특별한 사정이 없는 한 불법의 원인에 가공한 상대방에게 불법행위에 의한 손해배상청구권도 행사할 수 없다.","src":"기출 2024-39"},{"t":"불법도박채무에 대하여 양도담보의 명목으로 소유권이전등기를 해주는 것은 불법원인급여에 해당한다.","src":"기출 2024-39 | 기출 2026-39"},{"t":"무효인 명의신탁약정에 의해 명의수탁자 명의의 등기가 마쳐진 경우는 불법원인급여에 해당하지 않는다.","src":"기출 2026-39 | 부동산 실권리자명의 등기에 관한 법률 제4조"}]},{"머리":"반환의 범위","줄":[{"t":"원물반환 불능: 수익자가 받은 목적물을 반환할 수 없는 때 그 가액을 반환하여야 한다. 수익자로부터 무상으로 이익의 목적물을 양수한 악의의 제3자도 반환할 책임이 있다.","src":"민법 제747조"},{"t":"선의의 수익자: 받은 이익이 현존한 한도에서 반환한다.","src":"민법 제748조 제1항"},{"t":"악의의 수익자: 받은 이익에 이자를 붙여 반환하고 손해가 있으면 배상한다.","src":"민법 제748조 제2항 | 기출 2023-39"},{"t":"악의의 인정 시기: 수익자가 이익을 받은 후 법률상 원인 없음을 안 때 ‘그때부터’ 악의의 수익자로서 반환책임을 진다. 선의의 수익자가 패소한 때에는 소를 제기한 때부터 악의로 본다.","src":"민법 제749조 | 기출 2023-39"},{"t":"수익자가 부당이득을 얻기 위하여 지출한 비용은 반환할 이득의 범위에서 공제된다.","src":"기출 2024-39 | 보충(추정)"},{"t":"부당이득반환채무는 이행의 기한이 없는 채무로서 이행청구를 받은 때부터 지체책임이 있다(상당 기간 경과가 필요하지 않음).","src":"민법 제387조 제2항 | 기출 2024-39"},{"t":"부당이득반환채무의 소멸시효는 채무가 성립한 때부터 진행한다.","src":"기출 2026-23 | 보충(추정)"}]},{"머리":"사무관리","줄":[{"t":"사무관리: 의무 없이 타인을 위하여 사무를 관리하는 자는 그 사무의 성질에 좇아 가장 본인에게 이익이 되는 방법으로 관리하여야 한다. 본인의 의사를 알거나 알 수 있는 때에는 그 의사에 적합하도록 관리하여야 한다.","src":"민법 제734조 제1항ㆍ제2항"},{"t":"위반하여 관리한 경우 과실 없는 때에도 손해를 배상할 책임이 있다. 단 공공의 이익에 적합한 관리행위는 중대한 과실이 없으면 배상할 책임이 없다. 긴급사무관리: 급박한 위해를 면하게 하기 위한 관리는 고의나 중대한 과실이 없으면 책임이 없다.","src":"민법 제734조 제3항 | 민법 제735조"},{"t":"관리자의 비용상환청구권: 본인을 위하여 필요비 또는 유익비를 지출한 때 본인에 대하여 상환을 청구할 수 있다. 본인의 의사에 반하여 관리한 때에는 본인의 현존이익의 한도에서 준용한다.","src":"민법 제739조"}]}],"함정":[{"x":"채무자가 피해자로부터 횡령한 금전을 자신의 채권자에 대한 변제에 사용한 경우, 채권자가 변제를 수령할 때 횡령사실을 알았던 때에도 채권자의 금전취득은 피해자에 대한 관계에서 법률상 원인이 있다.","o":"악의인 채권자의 금전취득은 법률상 원인이 없다.","src":"기출 2022-39 | 보충(추정)"},{"x":"수익자가 이익을 받은 후 법률상 원인 없음을 안 때에는 이익을 받은 때부터 악의의 수익자로서 이익반환의 책임이 있다.","o":"법률상 원인 없음을 안 때부터 악의의 수익자로서 책임이 있다.","src":"민법 제749조 제1항 | 기출 2023-39"},{"x":"불법도박채무에 대하여 양도담보의 명목으로 소유권이전등기를 해주는 것은 불법원인 급여에 해당하지 않는다.","o":"불법원인급여에 해당한다.","src":"기출 2024-39 | 기출 2026-39"},{"x":"부당이득반환채무는 이행의 기한이 없는 채무로서 이행청구 후 상당한 기간이 경과하면 지체책임이 있다.","o":"이행청구를 받은 때부터 지체책임이 있다.","src":"민법 제387조 제2항 | 기출 2024-39"},{"x":"수익자가 부당이득을 얻기 위하여 비용을 지출한 경우, 그 비용은 수익자가 반환하여야 할 이득의 범위에서 공제되지 않는다.","o":"공제된다.","src":"기출 2024-39 | 보충(추정)"},{"x":"채무없는 자가 착오로 인하여 변제한 경우에 그 변제가 도의관념에 적합한 때에도 그 반환을 청구할 수 있다.","o":"도의관념에 적합한 때에는 반환을 청구하지 못한다.","src":"민법 제744조 | 기출 2024-39 | 기출 2026-39"},{"x":"변제자가 채무없음을 알고 이를 변제한 때에는 그 반환을 청구할 수 있다.","o":"반환을 청구하지 못한다.","src":"민법 제742조 | 기출 2026-39"},{"x":"무효인 명의신탁약정에 의해 명의수탁자 명의의 등기가 마쳐진 경우, 이는 불법원인 급여에 해당한다.","o":"불법원인급여에 해당하지 않는다.","src":"기출 2026-39"}]},"불법행위":{"묶음":[{"머리":"일반불법행위","줄":[{"t":"일반불법행위: 고의 또는 과실로 인한 위법행위로 타인에게 손해를 가한 자는 그 손해를 배상할 책임이 있다.","src":"민법 제750조"},{"t":"재산 이외의 손해(위자료): 타인의 신체·자유 또는 명예를 해하거나 기타 정신상 고통을 가한 자는 재산 이외의 손해에 대하여도 배상한다. 법원은 정기금 지급을 명하고 담보 제공을 명할 수 있다.","src":"민법 제751조"},{"t":"생명침해로 인한 위자료: 타인의 생명을 해한 자는 피해자의 직계존속·직계비속 및 배우자에 대하여 재산상 손해 없는 경우에도 배상한다. 태아는 손해배상의 청구권에 관하여 이미 출생한 것으로 본다.","src":"민법 제752조 | 민법 제762조 | 기출 2026-3"},{"t":"손해배상의 범위·방법·과실상계·손해배상자 대위는 채무불이행 규정(제393조, 제394조, 제396조, 제399조)을 준용한다.","src":"민법 제763조"},{"t":"명예훼손: 법원은 피해자의 청구에 의하여 손해배상에 갈음하거나 손해배상과 함께 명예회복에 적당한 처분을 명할 수 있다.","src":"민법 제764조"},{"t":"배상액의 경감청구: 손해가 고의 또는 중대한 과실에 의한 것이 아니고 배상으로 배상자의 생계에 중대한 영향을 미치게 될 경우 법원에 경감을 청구할 수 있다.","src":"민법 제765조"},{"t":"소멸시효: 피해자나 법정대리인이 손해 및 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년. 미성년자가 성적 침해를 당한 경우 성년이 될 때까지 진행하지 않는다.","src":"민법 제766조"},{"t":"정당방위·긴급피난: 타인의 불법행위에 대하여 자기 또는 제3자의 이익을 방위하기 위하여 부득이 타인에게 손해를 가한 자는 배상책임이 없다. 단 피해자는 불법행위에 대하여 손해배상을 청구할 수 있다. 급박한 위난을 피하기 위한 긴급피난에 준용한다.","src":"민법 제761조"},{"t":"과실로 인하여 스스로 심신상실을 초래하고 그 상태에서 타인에게 위법하게 손해를 가한 자는 손해배상책임을 진다.","src":"민법 제754조 단서 | 기출 2022-40"}]},{"머리":"책임능력과 감독자 책임","줄":[{"t":"미성년자 책임능력: 미성년자가 타인에게 손해를 가한 경우 그 행위의 책임을 변식할 지능이 없는 때에는 배상책임이 없다.","src":"민법 제753조"},{"t":"심신상실자: 심신상실 중에 타인에게 손해를 가한 자는 배상책임이 없다. 고의 또는 과실로 심신상실을 초래한 때에는 책임이 있다.","src":"민법 제754조"},{"t":"감독자의 책임: 책임능력 없는 자를 감독할 법정의무가 있는 자가 손해를 배상할 책임이 있다. 감독의무를 게을리하지 않은 경우(자신의 과실 없음 증명)에는 면책된다. 감독의무자를 갈음하여 감독하는 자(대리감독자)도 같다.","src":"민법 제755조 | 기출 2021-37"},{"t":"책임능력 있는 미성년자의 불법행위: 감독의무자(친권자)의 감독의무 위반과 손해 사이에 상당인과관계를 피해자가 증명하면 감독의무자는 일반불법행위(제750조)에 따른 손해배상책임을 진다.","src":"민법 제750조 | 기출 2024-40 | 기출 2025-40"},{"t":"12세 미성년자 가해자의 학교 선생님은 법정감독의무자가 아니다(법정감독의무자는 친권자 등). 대리감독자일 뿐이다.","src":"민법 제755조 제2항 | 기출 2026-40 | 보충(추정)"}]},{"머리":"사용자책임ㆍ도급인책임","줄":[{"t":"사용자책임: 타인을 사용하여 어느 사무에 종사하게 한 자는 피용자가 사무집행에 관하여 제3자에게 가한 손해를 배상할 책임이 있다. 사용자가 피용자의 선임 및 사무감독에 상당한 주의를 한 때 또는 상당한 주의를 하여도 손해가 있을 경우에는 면책된다. 사용자에 갈음하여 사무를 감독하는 자도 책임이 있다. 사용자·감독자는 피용자에게 구상권을 행사할 수 있다.","src":"민법 제756조 | 기출 2021-37"},{"t":"도급인의 책임: 도급인은 수급인이 일에 관하여 제3자에게 가한 손해를 배상할 책임이 없다. 단 도급 또는 지시에 관하여 도급인에게 중대한 과실이 있는 때에는 책임이 있다.","src":"민법 제757조 | 기출 2022-40"}]},{"머리":"공작물책임ㆍ동물점유자책임","줄":[{"t":"공작물책임: 공작물의 설치 또는 보존의 하자로 타인에게 손해를 가한 때 공작물 점유자가 배상한다. 점유자가 손해의 방지에 필요한 주의를 해태하지 않은 때 소유자가 배상한다(소유자는 무과실책임). 수목의 재식·보존의 하자에도 준용. 점유자·소유자는 손해의 원인에 책임 있는 자에게 구상할 수 있다.","src":"민법 제758조 | 기출 2021-37"},{"t":"공작물 소유자는 자기에게 과실이 없음을 증명하여도 책임을 면하지 못한다(공작물 임차인에 대한 소유자의 책임이 이에 해당).","src":"민법 제758조 제1항 | 기출 2021-37"},{"t":"제3자의 행위와 공작물의 설치·보존상의 하자가 공동원인이 되어 발생한 손해도 공작물의 하자에 의하여 발생한 것으로 볼 수 있다.","src":"기출 2022-40"},{"t":"동물점유자의 책임: 동물의 점유자는 그 동물이 타인에게 가한 손해를 배상한다. 동물의 종류와 성질에 따라 상당한 주의를 해태하지 않은 때 면책된다. 점유자에 갈음하여 동물을 보관한 자도 같다.","src":"민법 제759조"}]},{"머리":"공동불법행위","줄":[{"t":"수인이 공동의 불법행위로 타인에게 손해를 가한 때 연대하여 배상할 책임이 있다. 공동 아닌 수인의 행위 중 어느 자의 행위가 손해를 가한 것인지 알 수 없는 때에도 같다. 교사자나 방조자는 공동행위자로 본다.","src":"민법 제760조 | 기출 2026-40"},{"t":"망을 보는 역할을 한 자도 공동불법행위자로서 피해자에 대하여 전체 손해(100만원 전부)를 배상할 책임이 있다.","src":"민법 제760조 | 기출 2026-40"},{"t":"공동불법행위자의 책임은 연대(부진정연대)이므로 과실비율에 따른 일부(예: 100만원)만 부담하는 것이 아니라 피해자의 과실을 참작한 책임 범위 전액을 부담한다.","src":"민법 제760조 | 기출 2024-40 | 보충(추정)"},{"t":"공동불법행위자 중 1인이 변제한 때 변제 시부터 다른 공동불법행위자에 대한 구상권의 소멸시효가 기산한다.","src":"기출 2026-40"},{"t":"공동불법행위자는 피해자에 대하여 자기의 고의·과실이 없음을 증명하여 책임을 면할 수 없다(책임 발생 요건은 피해자가 증명).","src":"기출 2024-40 | 보충(추정)"},{"t":"과실상계: 고의의 불법행위자는 피해자의 부주의를 이용한 경우 과실상계를 주장할 수 없다. 과실로 가해한 공동불법행위자의 손해배상액 산정에서는 피해자의 과실을 참작한다.","src":"민법 제396조 | 민법 제763조 | 기출 2023-40 | 기출 2024-40 | 기출 2025-40"}]}],"함정":[{"x":"甲이 자신의 과실 없음을 스스로 증명하여 불법행위책임을 면할 수 있는 경우는 공작물 소유자 甲이 임차인에게 손해를 입힌 경우이다(2021-37 ㄷ).","o":"공작물 소유자의 책임은 무과실책임이므로 과실 없음을 증명해도 면책되지 않는다. 감독자·사용자는 면책 가능.","src":"민법 제758조 | 기출 2021-37"},{"x":"제3자의 행위와 공작물의 설치 또는 보존상의 하자가 공동원인이 되어 발생한 손해는 공작물의 설치 또는 보존상의 하자에 의하여 발생한 것이라고 볼 수 없다.","o":"하자에 의하여 발생한 것으로 볼 수 있다.","src":"기출 2022-40"},{"x":"甲의 손해배상액을 산정할 때 丙의 과실을 참작해야 한다(고의 불법행위자 甲이 丙의 부주의를 이용한 사안).","o":"참작할 수 없다(고의로 피해자 부주의를 이용한 경우).","src":"기출 2023-40"},{"x":"乙의 丙에 대한 잔존 손해배상채무는 2,000만 원이다(2023-40 ㄹ).","o":"출제 오답(바른 수치 미확인).","src":"기출 2023-40"},{"x":"乙, 丙, 丁이 甲에 대한 손해배상채무를 면하려면 스스로 고의나 과실이 없다는 것을 증명해야 한다.","o":"출제 오답(바른 수치 미확인). 가해자의 고의·과실은 피해자가 증명한다.","src":"기출 2024-40 | 보충(추정)"},{"x":"과실비율이 50%인 乙이 甲에게 300만원을 배상한 경우, 乙은 丙과 丁에게 구상권을 행사할 수 없다.","o":"출제 오답(바른 수치 미확인).","src":"기출 2024-40"},{"x":"乙, 丙, 丁의 과실비율이 동일한 경우, 丙은 甲에게 100만원의 손해배상채무만을 부담한다.","o":"공동불법행위자는 연대하여 전체를 배상한다.","src":"민법 제760조 | 기출 2024-40"},{"x":"甲의 부주의를 이용하여 乙, 丙, 丁이 고의로 기계를 고장 낸 경우, 甲의 부주의를 이유로 한 과실상계가 적용된다.","o":"고의의 불법행위자는 피해자의 부주의를 이유로 과실상계를 주장할 수 없다.","src":"기출 2024-40"},{"x":"乙이 12세의 미성년자인 경우, 乙의 학교선생님은 법정감독의무자로서 감독자책임을 진다.","o":"법정감독의무자가 아니다.","src":"민법 제755조 | 기출 2026-40 | 보충(추정)"}]}};
